typedef struct {
    time_t timestamp;
    int event_type;
    char *metadata;
} NetworkEventRecord;

// Dynamic array of NetworkEventRecords
NetworkEventRecord *events = NULL;
int num_events = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// API request function
void fetch_events(int *start_time, int *end_time) {
    // Send REST API request and populate events array
}

// Periodic cleanup function
void periodic_cleanup() {
    time_t current_time = time(NULL);
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < num_events; i++) {
        if ((events[i].timestamp + RETENTION_PERIOD) <= current_time) {
            // Release memory for unused records
            free(events[i].metadata);
            events[i] = events[num_events - 1];
            num_events--;
            i--; // Decrement i to re-check the same index
        }
    }
    pthread_mutex_unlock(&mutex);
}

// Performance monitoring function
void monitor_performance() {
    static int last_cleanup_time = 0;
    time_t current_time = time(NULL);
    if (current_time - last_cleanup_time >= RETENTION_PERIOD) {
        // Calculate rate of cleanup operations
        int num_cleanups = (int) ((time(NULL) - last_cleanup_time) / RETENTION_PERIOD);
        printf("Performed %d cleanups in the last hour.\n", num_cleanups);
    }
}

// Thread-safe event processing function
void process_events() {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < num_events; i++) {
        // Process each event
        printf("Processing event %d...\n", events[i].event_type);
    }
    pthread_mutex_unlock(&mutex);
}

// Main function
int main(int argc, char *argv[]) {
    pthread_t thread;
    pthread_create(&thread, NULL, process_events, NULL);

    while (1) {
        // Monitor performance and perform periodic cleanup
        monitor_performance();
        periodic_cleanup();

        // Fetch new events from API
        int start_time = 0; // Set start time based on retention period
        int end_time = 0; // Set end time based on retention period
        fetch_events(&start_time, &end_time);
    }

    return 0;
}

