    Request(const std::string& method, const std::string& url, const std::string& body)
        : method(method), url(url), body(body) {}
};

class Response {
public:
    int status_code;
    std::string response_body;

    Response(int status_code, const std::string& response_body)
        : status_code(status_code), response_body(response_body) {}
};

class Client {
public:
    static void send_request(const Request& request,
                               std::function<void(const Response&)> callback,
                               int timeout = 5000);

private:
    class Impl;
    std::unique_ptr<Impl> pimpl;

    Client();
    ~Client();

    friend class Request;
    friend class Response;
};

class Client::Impl {
public:
    void send_request(const Request& request,
                       std::function<void(const Response&)> callback,
                       int timeout);

private:
    // Implementation details
};

#endif  // HTTPCLIENT_H

// Implementation file
