#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <pthread.h>

#define MAX_PACKET_SIZE 1024
#define MAX_CLIENTS 100
#define LOG_FILE "server_log.txt"

int largest_integer = INT_MIN;
int *integer_array = NULL;
int array_size = 0;

void* handle_client(void* arg) {
    int client_socket = *(int*)arg;
    free(arg);

    int packet_size;
    unsigned char buffer[MAX_PACKET_SIZE];
    while ((packet_size = read(client_socket, buffer, MAX_PACKET_SIZE)) > 0) {
        for (int i = 0; i < packet_size; i++) {
            if ((buffer[i] & 0x80) != 0) {
                // Corrupted packet detected
                fprintf(stderr, "Corrupted packet received from client %d\n", client_socket);
                continue;
            }

            int integer_value = buffer[i] | (buffer[i + 1] << 8) | (buffer[i + 2] << 16) | (buffer[i + 3] << 24);

            if (integer_value < 0 || integer_value > 10000) {
                // Out-of-range value detected
                fprintf(stderr, "Invalid integer value received from client %d: %d\n", client_socket, integer_value);
                continue;
            }

            array_size++;
            integer_array = realloc(integer_array, sizeof(int) * (array_size + 1));
            integer_array[array_size - 1] = integer_value;

            if (integer_value > largest_integer) {
                largest_integer = integer_value;
            }
        }
    }

    close(client_socket);
}

int main() {
    int server_socket;
    struct sockaddr_in server_address;

    if ((server_socket = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        perror("socket creation failed");
        return -1;
    }

    server_address.sin_family = AF_INET;
    server_address.sin_port = htons(8080);
    inet_pton(AF_INET, "127.0.0.1", &server_address.sin_addr);

    if (bind(server_socket, (struct sockaddr*)&server_address, sizeof(server_address)) < 0) {
        perror("binding failed");
        return -1;
    }

    if (listen(server_socket, MAX_CLIENTS) < 0) {
        perror("listening failed");
        return -1;
    }

    pthread_t threads[MAX_CLIENTS];
    int client_sockets[MAX_CLIENTS];

    for (int i = 0; i < MAX_CLIENTS; i++) {
        client_sockets[i] = accept(server_socket, NULL, NULL);
        if (client_sockets[i] < 0) {
            perror("accept failed");
            return -1;
        }

        pthread_create(&threads[i], NULL, handle_client, &client_sockets[i]);
    }

    for (int i = 0; i < MAX_CLIENTS; i++) {
        pthread_join(threads[i], NULL);
    }

    free(integer_array);

    return 0;
}

