    public void start() {
        ThreadPoolExecutor executor = new ThreadPoolExecutor(LOG_PROCESSOR_POOL_SIZE, LOG_PROCESSOR_POOL_SIZE,
                0L, TimeUnit.MILLISECONDS, new LinkedBlockingQueue<Runnable>());
        executor.submit(() -> processLogs(executor));
    }

