                LogEntry logEntry = getNextLogEntry();
                if (logEntry != null) {
                    logQueue.put(logEntry);
                }
            }

            while (!logQueue.isEmpty()) {
                executor.submit(() -> flushLogs(logQueue.take()));
                try {
