typedef struct {
    CipherMode mode;
    unsigned char* key;
    int key_len;
    unsigned char* iv; // Initialization vector
    int iv_len;
} CipherContext;

// Function to create a new cipher context
CipherContext* cipher_create(CipherMode mode, const unsigned char* key, int key_len, const unsigned char* iv, int iv_len) {
    CipherContext* ctx = (CipherContext*)malloc(sizeof(CipherContext));
    ctx->mode = mode;
    ctx->key = malloc(key_len);
    memcpy(ctx->key, key, key_len);
    ctx->key_len = key_len;
    ctx->iv = malloc(iv_len);
    memcpy(ctx->iv, iv, iv_len);
    ctx->iv_len = iv_len;
    return ctx;
}

// Function to encrypt data using the cipher context
unsigned char* cipher_encrypt(CipherContext* ctx, const unsigned char* plaintext, int plaintext_len) {
    // Implement DES-based encryption algorithm for the specified mode
    // ...
    return encrypted_data;
}

// Function to decrypt data using the cipher context
unsigned char* cipher_decrypt(CipherContext* ctx, const unsigned char* ciphertext, int ciphertext_len) {
    // Implement DES-based decryption algorithm for the specified mode
    // ...
    return decrypted_data;
}

// Function to free the cipher context
void cipher_free(CipherContext* ctx) {
    if (ctx != NULL) {
        free(ctx->key);
        free(ctx->iv);
        free(ctx);
    }
}

// Example usage:
int main() {
    CipherMode mode = ECB_MODE;
    const unsigned char* key = "my_secret_key";
    int key_len = strlen(key);
    const unsigned char* iv = "my_initialization_vector";
    int iv_len = strlen(iv);

    CipherContext* ctx = cipher_create(mode, key, key_len, iv, iv_len);

    const unsigned char* plaintext = "Hello, World!";
    int plaintext_len = strlen(plaintext);

    unsigned char* ciphertext = cipher_encrypt(ctx, plaintext, plaintext_len);
    printf("Encrypted data: ");
    for (int i = 0; i < ciphertext_len; i++) {
        printf("%02x", ciphertext[i]);
    }
    printf("\n");

    unsigned char* decrypted_data = cipher_decrypt(ctx, ciphertext, ciphertext_len);
    printf("Decrypted data: %s\n", decrypted_data);

    cipher_free(ctx);
    return 0;
