        // Start a scheduling service to periodically retrieve and analyze data
        ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);
        scheduler.scheduleWithFixedDelay(() -> {
            // Retrieve Pokémon data from API
            try {
                CloseableHttpResponse response = httpClient.execute(new HttpGet("https://api.pokemon.com/pokemon"));
                HttpEntity entity = EntityUtils.toByteArray(response.getEntity());
                String jsonString = new String(entity.getContent(), "UTF-8");

                // Analyze data and send notifications if necessary
                PokemonData data = JSON.parseObject(jsonString, PokemonData.class);
                for (Pokemon p : data.getPokemons()) {
                    if (p.getWeaknesses().size() > config.thresholds.getOrDefault(p.getId(), 0)) {
                        sendNotification(p);
                    }
                }

            } catch (IOException e) {
                logger.log(Level.SEVERE, "Failed to retrieve Pokémon data: " + e.getMessage());
            }
        }, 1, TimeUnit.HOURS, TimeUnit.MILLISECONDS);

        // Start a caching service
        ExecutorService cacheExecutor = Executors.newFixedThreadPool(5);
        for (String id : config.pokemonIds) {
            cacheExecutor.submit(() -> {
                try {
                    // Cache Pokémon data
                    CloseableHttpResponse response = httpClient.execute(new HttpGet("https://api.pokemon.com/pokemon/" + id));
                    HttpEntity entity = EntityUtils.toByteArray(response.getEntity());
                    String jsonString = new String(entity.getContent(), "UTF-8");
                    PokemonData data = JSON.parseObject(jsonString, PokemonData.class);
                    cache.put(id, data);

                } catch (IOException e) {
                    logger.log(Level.SEVERE, "Failed to retrieve Pokémon data: " + e.getMessage());
                }
            });
        }

        // Start a notification service
        ExecutorService notificationExecutor = Executors.newScheduledThreadPool(1);
        notificationExecutor.scheduleAtFixedRate(() -> {
            // Send notifications for critical weaknesses
            for (Pokemon p : cache.values()) {
                if (p.getWeaknesses().size() > config.thresholds.getOrDefault(p.getId(), 0)) {
                    sendNotification(p);
                }
            }
        }, 1, TimeUnit.MINUTES, TimeUnit.MILLISECONDS);

        // Start a logging service
        logger.info("Pokémon Insights Microservice started");
    }

