#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <semaphore.h>

class SemaphoreManager {
public:
    SemaphoreManager() : semaphoreCount(0) {}

    void createSemaphore(const std::string& name, int value) {
        sem_t* semaphore = sem_open(name.c_str(), O_CREAT | O_EXCL, 0666, value);
        if (semaphore == SEM_FAILED) {
            perror("sem_open");
            return;
        }
        semaphores[semaphore] = true;
        ++semaphoreCount;
    }

    void deleteSemaphore(const std::string& name) {
        sem_t* semaphore = sem_open(name.c_str(), O_RDWR | O_NONBLOCK);
        if (semaphore == SEM_FAILED || !semaphores.count(semaphore)) {
            perror("sem_open");
            return;
        }
        sem_close(semaphore);
        --semaphoreCount;
    }

    void acquire(const std::string& name) {
        sem_t* semaphore = sem_open(name.c_str(), O_RDWR | O_NONBLOCK);
        if (semaphore == SEM_FAILED || !semaphores.count(semaphore)) {
            perror("sem_open");
            return;
        }
        int value = sem_trywait(semaphore);
        if (value < 0) {
            // Handle semaphore timeout or resource exhaustion
            perror("sem_trywait");
            return;
        }
    }

    void release(const std::string& name) {
        sem_t* semaphore = sem_open(name.c_str(), O_RDWR | O_NONBLOCK);
        if (semaphore == SEM_FAILED || !semaphores.count(semaphore)) {
            perror("sem_open");
            return;
        }
        sem_post(semaphore);
    }

private:
    std::unordered_map<sem_t*, bool> semaphores;
    int semaphoreCount;
};

int main() {
    SemaphoreManager manager;

    // Create and delete semaphores
    manager.createSemaphore("my_semaphore", 5);
    manager.deleteSemaphore("my_semaphore");

    // Acquire and release semaphore
    manager.acquire("my_semaphore");
    manager.release("my_semaphore");

    return 0;
}

