};

void appendOrInsertWithLogging(std::forward_list<std::string>& list,
                                const std::string& target,
                                const std::string& element,
                                ExternalLoggingService& logger) {
    std::lock_guard<std::mutex> lock(logger.mutex);

    auto it = list.begin();
    bool found = false;
    while (it != list.end()) {
        if (*it == target) {
            found = true;
            break;
        }
        ++it;
    }

    if (found) {
        list.insert_after(it, element);
    } else {
        list.append(element);
    }
}
