class RandomNumberGenerator {
private:
    std::mt19937 engine;
    mutable std::mutex mtx;

public:
    RandomNumberGenerator(size_t seed) : engine(seed) {}

    void setSeed(size_t newSeed) {
        std::lock_guard<std::mutex> lock(mtx);
        engine.seed(newSeed);
    }

    template<typename T>
    T generate(const std::string& distribution, bool isUniform = false) {
        std::lock_guard<std::mutex> lock(mtx);

        if (distribution == "uniform_int") {
            return static_cast<T>(engine() % 100); // UniformInt(0, 99)
        } else if (distribution == "normal_float") {
            std::normal_distribution<float> dist(0.0f, 1.0f);
            return T(dist(engine()));
        } else if (distribution == "uniform_bool") {
            std::bernoulli_distribution boolDist(0.5);
            return T(boolDist(engine()) ? true : false);
        } else {
            throw std::runtime_error("Invalid distribution");
        }
    }

