// Define a database to store technology information
const techDB = {};

// Define a cache for storing frequently accessed data
const cache = {};

// Initialize the technology trends API client
const apiClient = axios.create({
  baseURL: 'https://technology-trends-api.com',
});

// Set an interval to update the technology database every 24 hours
setInterval(() => {
  apiClient.get('/technologies')
    .then((response) => {
      techDB = response.data;
      // Update local cache with the latest data
      cache.technologies = techDB;
    })
    .catch((error) => {
      console.error('Error updating technology database:', error);
    });
}, 24 * 60 * 60 * 1000); // every 24 hours

// Define a function to extract technology names from log entries
const extractTechnologies = (logEntry) => {
  const technologies = [];
  for (const token of logEntry.split(' ')) {
    if (techDB[token]) {
      technologies.push({ name: token, version: techDB[token].version });
    } else if (cache.technologies[token]) {
      technologies.push({ name: token, version: cache.technologies[token].version });
    }
  }
  return technologies;
};

// Define a function to process log entries
const processLogEntries = async (logEntries) => {
  const results = [];
  for (const logEntry of logEntries) {
    try {
      const technologies = extractTechnologies(logEntry);
      results.push({ logEntry, technologies });
    } catch (error) {
      console.error('Error processing log entry:', error);
    }
  }
  return results;
};

// Define a function to handle incoming requests
app.post('/process', async (req, res) => {
  try {
    const logEntries = req.body.logEntries;
    const results = await processLogEntries(logEntries);
    res.json(results);
  } catch (error) {
    console.error('Error handling request:', error);
    res.status(500).send({ message: 'Internal Server Error' });
  }
});

// Start the server
app.listen(port, () => {
  console.log(`Server started on port ${port}`);
});
