function renderDynamicFooter(footerScripts) {
  const scriptQueue = [];
  const asyncScripts = [];

  footerScripts.forEach((script) => {
    if (script.src || script.innerHTML) {
      if (!script.scriptId.includes('/')) {
        throw new Error(`Invalid script ID: ${script.scriptId}`);
      }

      if (script.type === 'async') {
        asyncScripts.push(script);
      } else {
        scriptQueue.push(script);
      }
    }
  });

  const loadScript = (script) => {
    return new Promise((resolve, reject) => {
      const scriptTag = document.createElement('script');
      scriptTag.src = script.src || '';
      scriptTag.innerHTML = script.innerHTML || '';

      if (!script.async && !script.defer) {
        scriptTag.onload = resolve;
        scriptTag.onerror = reject;
      } else {
        scriptTag.onload = () => resolve();
        scriptTag.onerror = () => reject();
      }

      document.body.appendChild(scriptTag);
    });
  };

  const loadScripts = async (scripts) => {
    for await (const script of scripts) {
      try {
        await loadScript(script);
      } catch (error) {
        console.error(`Error loading script ${script.scriptId}:`, error);
        // Log to centralized logging service
      }
    }
  };

  await loadScripts(asyncScripts);
  await loadScripts(scriptQueue);

  // Customization hooks
