import java.util.*;

public class DisjointPairFinder {
    private static final int MAX_MERGE = 1000000;

    public static void main(String[] args) throws Exception {
        List<DisjointPair> disjointPairs = new ArrayList<>();
        long startTime = System.currentTimeMillis();

        // Initialize the Union-Find data structure
        UnionFind uf = new UnionFind(MAX_MERGE);

        // Read input data from external database
        try (DatabaseConnection dbConn = new DatabaseConnection()) {
            List<Integer> inputData = dbConn.readData();

            // Process each element in the dataset
            for (int num : inputData) {
                int root = uf.find(num);
                if (!uf.isRoot(root)) {
                    uf.union(num, root);
                }
            }
        } catch (Exception e) {
            System.out.println("Error reading data: " + e.getMessage());
            return;
        }

        // Calculate the total count of disjoint pairs
        long endTime = System.currentTimeMillis();
        int pairCount = 0;
        for (int i = 1; i <= MAX_MERGE; i++) {
            if (!uf.isRoot(uf.find(i))) {
                pairCount++;
            }
        }

        // Generate a summary report of execution times for each pair
        try (PrintWriter reportFile = new PrintWriter("report.txt")) {
            reportFile.println("Disjoint Pair Count: " + pairCount);
            reportFile.println("Execution Time: " + (endTime - startTime) + " milliseconds");
        } catch (Exception e) {
            System.out.println("Error writing report: " + e.getMessage());
        }

        // Print the total count of disjoint pairs
        System.out.println("Total Disjoint Pair Count: " + pairCount);
    }
}

class UnionFind {
    private int[] parent;
    private int[] size;

    public UnionFind(int max) {
        this.parent = new int[max];
        this.size = new int[max];

        for (int i = 0; i < max; i++) {
            this.parent[i] = i;
            this.size[i] = 1;
        }
    }

    public int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    public void union(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);

        if (rootX == rootY) {
            return;
        }

        if (size[rootX] < size[rootY]) {
            parent[rootX] = rootY;
            size[rootY] += size[rootX];
        } else {
            parent[rootY] = rootX;
            size[rootX] += size[rootY];
        }
    }

    public boolean isRoot(int x) {
        return parent[x] == x;
    }
}

class DatabaseConnection {
    public List<Integer> readData() throws Exception {
        // Implement database connection logic here
        // For demonstration purposes, assume reading data from a file
        try (BufferedReader reader = new BufferedReader(new FileReader("input.txt"))) {
            List<Integer> inputData = new ArrayList<>();
            String line;
            while ((line = reader.readLine()) != null) {
                inputData.add(Integer.parseInt(line));
            }
            return inputData;
        } catch (Exception e) {
            throw new Exception("Error reading data: " + e.getMessage());
        }
    }
}
