public class TCPMessageBroker {

    private static final int PORT = 9090;
    private static final String KAFKA_BOOTSTRAP_SERVERS = "localhost:9092";
    private static final String KAFKA_TOPIC = "my_topic";

    public static void main(String[] args) throws IOException, InterruptedException {
        // Initialize the TCP server
        ServerSocketChannel server = ServerSocketChannel.open();
        server.bind(new InetSocketAddress(PORT));
        server.configureBlocking(false);
        Selector selector = Selector.open();

        // Start the Kafka consumer and producer
        ExecutorService executor = Executors.newSingleThreadExecutor();
        KafkaConsumer kafkaConsumer = new KafkaConsumer(KAFKA_BOOTSTRAP_SERVERS, KAFKA_TOPIC);
        KafkaProducer kafkaProducer = new KafkaProducer(KAFKA_BOOTSTRAP_SERVERS);

        // Set up connection pool
        ConnectionPool connectionPool = new ConnectionPool(200);

        while (true) {
            selector.select();
            List<SelectionKey> keys = selector.selectedKeys().keys();

            for (SelectionKey key : keys) {
                if (key.isAcceptable()) {
                    ServerSocketChannel channel = (ServerSocketChannel) key.channel();
                    ChannelHandler handler = new ChannelHandler(channel, connectionPool, kafkaConsumer, kafkaProducer);
                    channel.register(selector, SelectionKey.OP_ACCEPT | SelectionKey.OP_READ);
                } else if (key.isReadable()) {
                    // Handle incoming messages
                    ChannelHandlerContext context = (ChannelHandlerContext) key.channel();
                    Message message = context.readMessage();
                    if (message != null) {
                        // Process the message
                        processMessage(message);
                    }
                }
            }

            // Periodically clean up connections and Kafka consumer/producer
            connectionPool.cleanup();
            kafkaConsumer.close();
            kafkaProducer.close();

            Thread.sleep(1000); // Sleep for 1 second before next iteration
        }
