class ChannelHandler implements Runnable {

    private final ServerSocketChannel channel;
    private final ConnectionPool connectionPool;
    private final KafkaConsumer kafkaConsumer;
    private final KafkaProducer kafkaProducer;

    public ChannelHandler(ServerSocketChannel channel, ConnectionPool connectionPool, KafkaConsumer kafkaConsumer, KafkaProducer kafkaProducer) {
        this.channel = channel;
        this.connectionPool = connectionPool;
        this.kafkaConsumer = kafkaConsumer;
        this.kafkaProducer = kafkaProducer;
    }

    @Override
    public void run() {
        // Accept and handle incoming connections
        while (true) {
            try {
                SocketChannel socket = channel.accept();
                Connection connection = new Connection(socket, connectionPool);
                connection.start();

                // Start consuming Kafka messages asynchronously
                executor.submit(() -> kafkaConsumer.subscribe(new Subscription()));

                // Start producing messages to Kafka asynchronously
                executor.submit(() -> kafkaProducer.send(new ProducerRecord<>(KAFKA_TOPIC, "key", "value")));
            } catch (IOException e) {
                // Handle connection errors
            }
        }
    }
