import java.util.concurrent.atomic.AtomicInteger;

public class SessionManager {
    private final AtomicInteger _retryCount = new AtomicInteger(0);

    public void loadSessionAsync(int sessionId) {
        try {
            // Load the session data from external system
            var sessionData = fetchSessionDataFromExternalSystemAsync(sessionId);
            return sessionData;
        } catch (Exception e) {
            if (_retryCount.incrementAndGet() < MAX_RETRIES) {
                // Retry loading the session data after a delay
                try {
                    Thread.sleep(RETRY_DELAY_MILLIS);
                    loadSessionAsync(sessionId);
                } catch (InterruptedException ex) {
                    Thread.currentThread().interrupt();
                }
