['```
using System;
using System.Data.SqlClient;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Caching.Distributed;

namespace HrManagementSystem
{
    public class EmployeeService
    {
        private readonly string _connectionString;
        private readonly IDistributedCache _distributedCache;

        public EmployeeService(string connectionString, IDistributedCache distributedCache)
        {
            _connectionString = connectionString;
            _distributedCache = distributedCache;
        }

        public async Task<EmployeeDetails> GetEmployeeDetailsAsync(int supervisorId)
        {
            // Fetch employee details from database
            using (var connection = new SqlConnection(_connectionString))
            {
                await connection.OpenAsync();
                using (var command = new SqlCommand("sp_GetEmployeeDetails", connection))
                {
                    command.Parameters.AddWithValue("@supervisorId", supervisorId);
                    using (var reader = command.ExecuteReader())
                    {
                        EmployeeDetails employeeDetails = null;
                        while (reader.Read())
                        {
                            employeeDetails = new EmployeeDetails
                            {
                                Name = reader["Name"].ToString(),
                                City = reader["City"].ToString(),
                                Address = reader["Address"].ToString(),
                                Department = reader["Department"].ToString(),
                                JobTitle = reader["JobTitle"].ToString()
                            };
                        }
                    }
                }
            }

            // Fetch real-time department updates from external API
            try
            {
                using (var httpClient = new HttpClient())
                {
                    var response = await httpClient.GetAsync($"https://external-api.com/departments/{supervisorId}");
                    if (response.IsSuccessStatusCode)
                    {
                        string responseBody = await response.Content.ReadAsStringAsync();
                        employeeDetails.Department = JsonConvert.DeserializeObject<Department>(responseBody).Name;
                    }
                }
            }
            catch (HttpRequestException ex)
            {
                // Handle API rate limits and network delays
                if (ex.StatusCode == System.Net.HttpStatusCode.TooManyRequests)
                {
                    await Task.Delay(1000); // exponential backoff
                    return await GetEmployeeDetailsAsync(supervisorId);
                }
                else
                {
                    throw;
                }
            }

            // Cache employee details for a configurable time window
            var cacheOptions = new DistributedCacheEntryOptions();
            _distributedCache.Set("employee:" + supervisorId, JsonConvert.SerializeObject(employeeDetails), cacheOptions);

            return employeeDetails;
        }
    }
}

