<?php
declare(strict_types=1);

namespace PasswordUpdater;

use Doctrine\DBAL\Connection;
use Doctrine\ORM\EntityManagerInterface;
use League\Event\AbstractEventEmitter;
use League\Event\EventDispatcherInterface;
use League\Event\ListenerProviderInterface;
use League\Event\QueueableEvent;
use PDO;

class PasswordUpdater {
    private $entityManager;
    private $connection;
    private $eventEmitter;

    public function __construct(EntityManagerInterface $entityManager, Connection $connection) {
        $this->entityManager = $entityManager;
        $this->connection = $connection;
        $this->eventEmitter = new AbstractEventEmitter();
    }

    public function updatePassword(string $userId, string $oldPassword, string $newPassword): void {
        try {
            $user = $this->entityManager->getRepository(User::class)->find($userId);
            if (!$user || !password_verify($oldPassword, $user->getPassword())) {
                throw new InvalidCredentialsException();
            }

            if (!isValidPassword($newPassword)) {
                throw new WeakPasswordException();
            }

            $transaction = $this->connection->beginTransaction();

            try {
                // Update user password
                $user->setPassword(password_hash($newPassword, PASSWORD_DEFAULT));
                $this->entityManager->flush();

                // Trigger event to notify other services of the password update
                $this->eventEmitter->dispatch(new PasswordUpdatedEvent($userId));

                $transaction->commit();
            } catch (\PDOException $e) {
                $transaction->rollback();
                throw $e;
            }
        } catch (InvalidCredentialsException | WeakPasswordException $e) {
            // Log the error and retry the password update after 5 minutes
            $this->logError($e);
            sleep(300); // Wait for 5 minutes before retrying
            $this->updatePassword($userId, $oldPassword, $newPassword);
        }
    }

    private function logError(\Throwable $exception): void {
        // Log the error to an audit log table
        $auditLog = new AuditLog();
        $auditLog->setUserId($exception->getUserId());
        $auditLog->setErrorDescription($exception->getMessage());
        $this->entityManager->persist($auditLog);
        $this->entityManager->flush();
    }

    public function listenForPasswordUpdates(EventDispatcherInterface $eventDispatcher): void {
        // Listen for password update events and trigger asynchronous updates
