    if (fsa == NULL || count <= 0) return NULL;

    State* list = (State*)malloc(sizeof(State) * (count + 1));
    pthread_mutex_init(&list[last_state].lock, NULL);

    for (int i = 0; i < count; i++) {
        list[i].state = states[i];
    }

    // Validate FSA
    if (!validate_fsa(fsa)) {
        free(list);
        return NULL;
    }

    // Optimize for concurrent processing
    pthread_t threads[count];
    for (int i = 0; i < count; i++) {
        pthread_create(&threads[i], NULL, process_state, &list[i]);
    }
    for (int i = 0; i < count; i++) {
        pthread_join(threads[i], NULL);
    }

    // Cache state information
    list[count].state = last_state;
    pthread_mutex_unlock(&list[last_state].lock);

    return list;
}

