        public string Name { get; set; }
        public string Description { get; set; }
        public string Unit { get; set; }
        public bool IsInclusive { get; set; }
        public double Min { get; set; }
        public double Max { get; set; }

        public Random Rand = new Random();
    }

    public class DynamicValueManager
    {
        private readonly Dictionary<string, DynamicValueRange> _ranges;
        private readonly Task _fetchTask;

        public DynamicValueManager()
        {
            _ranges = new Dictionary<string, DynamicValueRange>();
            _fetchTask = FetchRangesAsync();
        }

        public async Task FetchRangesAsync()
        {
            // Implementation to fetch ranges from an external API
            // and handle errors accordingly
        }

        public void AddRange(string name, string description, string unit, double min, double max, bool isInclusive)
        {
            _ranges.Add(name, new DynamicValueRange { Name = name, Description = description, Unit = unit, IsInclusive = isInclusive, Min = min, Max = max });
        }

        public void RemoveRange(string name)
        {
            _ranges.Remove(name);
        }

        public async Task<double> GenerateRandomValueAsync(string rangeName)
        {
            if (!_ranges.TryGetValue(rangeName, out var range))
            {
                throw new ArgumentException("Invalid range name");
            }

            return await Task.Run(() => Rand.NextDouble() * (range.Max - range.Min) + range.Min);
        }

        public async Task<double[]> GenerateRandomValuesAsync(int count, string rangeName)
        {
            if (!_ranges.TryGetValue(rangeName, out var range))
            {
                throw new ArgumentException("Invalid range name");
            }

            return await Task.Run(() => Enumerable.Range(0, count).Select(_ => Rand.NextDouble() * (range.Max - range.Min) + range.Min).ToArray());
        }
    }
}
