// Function to read and parse data from text files
void process_file(char *filename) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error opening file: %s\n", filename);
        return;
    }

    int line_count = 0;
    double last_two_numbers_sum = 0.0;

    while (fgets(line, sizeof(line), file)) {
        // Tokenize the line and calculate the sum of the last two numbers
        char *token = strtok(line, " ");
        double num1 = atof(token);
        token = strtok(NULL, " ");
        double num2 = atof(token);

        last_two_numbers_sum += num1 + num2;
        line_count++;

        if (line_count % 2 == 0) {
            printf("%.2f\n", last_two_numbers_sum / 2.0); // Output average of the last two numbers
            last_two_numbers_sum = 0.0;
        }
    }

    fclose(file);
}

