public class ApplicationRegistry
{
    private readonly IWebHost _host;
    private readonly ILogger<ApplicationRegistry> _logger;
    private readonly IConfiguration _config;
    private static readonly object _lock = new object();

    public string RegisterApplication(string directoryPath)
    {
        if (!Directory.Exists(directoryPath))
        {
            _logger.LogError($"Invalid directory path: {directoryPath}");
            return null;
        }

        if (!IsValidDirectory(directoryPath))
        {
            _logger.LogError("Directory is not writable or missing required files.");
            return null;
        }

        // Concurrency handling
        lock (_lock)
        {
            try
            {
                var config = GetConfiguration(directoryPath);
                _host = Host.CreateDefaultBuilder().ConfigureWebHost(builder =>
                {
                    builder.UseConfiguration(config);
                }).Build();
                _config = config;

                if (!_host.Start())
                {
                    _logger.LogError("Failed to start the application.");
                    return null;
                }

                _logger.LogInformation($"Application registered at: {directoryPath}");
                return directoryPath;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error registering the application");
                return null;
            }
        }
    }

    private IConfiguration GetConfiguration(string directoryPath)
    {
        // Dependency management
        var cache = new Dictionary<string, string>();
        // ... load cached configurations ...

        var config = new ConfigurationBuilder()
            .AddJsonFile(Path.Combine(directoryPath, "appsettings.json"))
            .AddXmlFile(Path.Combine(directoryPath, "web.config"), optional: true)
            .Build();

        // Apply caching strategy
        foreach (var key in cache.Keys)
        {
            config[key] = cache[key];
        }

        return config;
    }

    private bool IsValidDirectory(string directoryPath)
    {
        if (!Directory.Exists(directoryPath))
        {
            return false;
        }

        if (!File.Exists(Path.Combine(directoryPath, "appsettings.json")))
        {
            return false;
        }

        if (!File.Exists(Path.Combine(directoryPath, "web.config")))
        {
            return false;
        }

        try
        {
            using var fileStream = File.OpenRead(Path.Combine(directoryPath, "appsettings.json"));
            // ... validate file content ...
        }
        catch (Exception)
        {
            return false;
        }

        return true;
    }
}
