import java.io.*;
import java.util.*;
import org.apache.commons.exec.*;

public class ShellCommandExecutor {
    private static final Logger logger = LoggerFactory.getLogger(ShellCommandExecutor.class);
    private Configuration config;
    private ExecutorService executor;

    public ShellCommandExecutor(Configuration config) throws Exception {
        this.config = config;
        this.executor = new ThreadPoolExecutor(config.getThreadPoolSize(), config.getThreadPoolSize(), 0, TimeUnit.MILLISECONDS, new ArrayBlockingQueue<Runnable>(config.getMaxConcurrentCommands()));
    }

    public void executeCommand(String command) throws Exception {
        CommandRunner commandRunner = new CommandRunner(command);
        executor.submit(() -> {
            try {
                int exitValue = commandRunner.run();
                if (exitValue != 0) {
                    logger.error("Command '{}' failed with exit value {}", command, exitValue);
                }
            } catch (Exception e) {
                logger.error("Error executing command '{}': {}", command, e.getMessage(), e);
            }
        });
    }

    public void cleanup() {
        executor.shutdown();
        try {
            if (!executor.awaitTermination(1, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException ie) {
            Thread.currentThread().interrupt();
        }
    }

    private class CommandRunner implements Runnable {
        private final String command;
        private Process process;

        public CommandRunner(String command) {
            this.command = command;
        }

        @Override
        public void run() {
            try {
                process = Runtime.getRuntime().exec(command);
                new StreamGobbler(process.getInputStream()).start();
                new StreamGobbler(process.getErrorStream()).start();

                int exitValue = process.waitFor();
                if (exitValue != 0) {
                    logger.error("Command '{}' failed with exit value {}", command, exitValue);
                }
            } catch (IOException | InterruptedException e) {
                logger.error("Error executing command '{}': {}", command, e.getMessage(), e);
            } finally {
                try {
                    process.destroy();
                } catch (Exception e) {
                    logger.warn("Failed to destroy process for command '{}'", command, e);
                }
            }
        }
    }

    private class StreamGobbler extends Thread {
        private final InputStream stream;

        public StreamGobbler(InputStream stream) {
            this.stream = stream;
        }

        @Override
        public void run() {
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(stream))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    logger.info(line);
                }
            } catch (IOException e) {
                logger.error("Error reading stream for command '{}': {}", null, e.getMessage(), e);
            }
        }
    }

    public static void main(String[] args) throws Exception {
        Properties properties = new Properties();
        properties.load(new FileInputStream("config.properties"));
        Configuration config = new Configuration(properties);

        ShellCommandExecutor executor = new ShellCommandExecutor(config);
        executor.executeCommand("your_command_here");
        executor.cleanup();
    }
}

class Configuration {
    private int threadPoolSize;
    private int maxConcurrentCommands;

    public Configuration(Properties properties) throws Exception {
        this.threadPoolSize = Integer.parseInt(properties.getProperty("thread.pool.size", "5"));
        this.maxConcurrentCommands = Integer.parseInt(properties.getProperty("max.concurrent.commands", "10"));

        // Add other configuration property parsing logic here
    }

    public int getThreadPoolSize() {
        return threadPoolSize;
    }

    public int getMaxConcurrentCommands() {
        return maxConcurrentCommands;
    }
}
