#define SCHEMA_FILE "schema.json"
#define UPDATE_API "https://api.config.service/schema"

int validate_token(const char* token_json) {
    json_error_t error;
    json_t *token = json_loadb(token_json, strlen(token_json), JSON_DISABLE_EOF_CHECK);
    if (!token) {
        return 0; // Malformed JSON
    }

    // Schema validation
    json_t *schema = json_file.SCHEMA_FILE, *access_token = json_object_get(token, "access_token"), *expires_in = json_object_get(token, "expires_in"), *token_type = json_object_get(token, "token_type");
    if (!json_is_string(access_token) || !json_is_integer(expires_in) || !json_is_string(token_type)) {
        return 0; // Partial JSON
    }
    const char* token_access = json_string_value(access_token), *token_expires = json_integer_value(expires_in), *token_type_value = json_string_value(token_type);
    if (strlen(token_access) == 0 || atoi(token_expires) > 604800 || strcmp(token_type_value, "Bearer") != 0) {
        return 0; // Invalid token
    }

    json_t *refresh_token = json_object_get(token, "refresh_token");
    if (refresh_token && !json_is_string(refresh_token)) {
        return 0; // Malformed JSON
    }
    const char* refresh_token_value = json_string_value(refresh_token);
    if (refresh_token_value) {
        if (strlen(refresh_token_value) == 0) {
            return 0; // Invalid token
        }
    }

    // Update schema if necessary
    json_t *updated_schema = json_loadf(UPDATE_API, &error);
    if (!updated_schema) {
        printf("Error updating schema: %s\n", error.message);
        json_decref(token);
        return 0; // Unable to update schema
    }

    // Parse updated schema
    json_error_t new_error;
    json_t *new_token = json_loadb(token_json, strlen(token_json), JSON_DISABLE_EOF_CHECK | JSON_UPDATE_SCHEMA(updated_schema, &new_error));
    if (!new_token) {
        printf("Error parsing updated schema: %s\n", new_error.message);
        json_decref(token);
        return 0; // Unable to parse updated schema
    }

    // Perform token validation again with updated schema
    json_t *new_access_token = json_object_get(new_token, "access_token"), *new_expires_in = json_object_get(new_token, "expires_in"), *new_token_type = json_object_get(new_token, "token_type");
    if (!json_is_string(new_access_token) || !json_is_integer(new_expires_in) || !json_is_string(new_token_type)) {
        return 0; // Partial JSON
    }
    const char* new_token_access = json_string_value(new_access_token), *new_token_expires = json_integer_value(new_expires_in), *new_token_type_value = json_string_value(new_token_type);
    if (strlen(new_token_access) == 0 || atoi(new_token_expires) > 604800 || strcmp(new_token_type_value, "Bearer") != 0) {
        return 0; // Invalid token
    }

    json_decref(token);
    json_decref(updated_schema);
    json_decref(new_token);

    return 1; // Valid token

}
