using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class DataProcessor
{
    public static long ProcessData(string filePath)
    {
        if (!File.Exists(filePath))
            throw new FileNotFoundException("The file was not found.");

        try
        {
            using (var fileStream = File.OpenRead(filePath))
            {
                var buffer = new byte[4096];
                long maxInteger = 0;
                long totalRead = 0;

                while ((totalRead = fileStream.Read(buffer, 0, buffer.Length)) > 0)
                {
                    for (int i = 0; i < totalRead; i++)
                    {
                        int value = BitConverter.ToInt32(new byte[] { buffer[i] }, 0);
                        if (value > maxInteger) 
                            maxInteger = value;
                    }
                }

                return maxInteger;
            }
        }
        catch (Exception ex)
        {
            throw new InvalidOperationException("An error occurred while processing the file.", ex);
        }
    }
}

public class SecureDataHandler
{
    public static byte[] EncryptData(byte[] plainText, string key, string iv)
    {
        using (var tripleDes = TripleDESCryptoServiceProvider.Create())
        {
            tripleDes.Key = Convert.FromBase64String(key);
            tripleDes.IV = Convert.FromBase64String(iv);

            return tripleDes.TransformFinalBlock(plainText, 0, plainText.Length);
