import java.io.ByteArrayInputStream;
import java.io.DataInputStream;
import java.io.IOException;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class DeserializationUtility {
    private static final int MAX_THREADS = 10; // adjust as needed

    public <T> T deserialize(byte[] data, Class<T> clazz) throws IOException, DeserializationException {
        try (ByteArrayInputStream bais = new ByteArrayInputStream(data);
             DataInputStream dis = new DataInputStream(bais)) {
            return deserialize(dis, clazz);
        }
    }

    private <T> T deserialize(DataInputStream dis, Class<T> clazz) throws IOException, DeserializationException {
        try {
            ExecutorService executor = Executors.newCachedThreadPool(MAX_THREADS);
            Callable<T> deserializer = () -> {
                try (ObjectInputStream ois = new ObjectInputStream(dis)) {
                    return (T) ois.readObject();
                }
            };
            T result = executor.submit(deserializer).get();
            executor.shutdownNow();
            return result;
        } catch (InterruptedException | ExecutionException e) {
            throw new DeserializationException("Failed to deserialize object", e);
        }
    }

    public static class DeserializationException extends Exception {
        public DeserializationException(String message, Throwable cause) {
            super(message, cause);
        }
    }
}
