        if not file_obj.name.lower().endswith(('.jpg', '.jpeg')):
            return False

        return True

    def upload_to_cloud_storage(self, file_path):
        s3 = boto3.client('s3', aws_access_key_id=settings.AWS_ACCESS_KEY_ID,
