        transfer_config = TransferConfig(multipart_threshold=15 * 1024 * 1024)
        bucket = 'my-bucket'
        key = f"images/{file_path}"
        s3.upload_file(file_path, bucket, key, ExtraArgs={'ContentType': 'image/jpeg'}, Config=transfer_config)

    @shared_task
    def process_upload(self):
        result = AsyncResult('upload_file_to_cloud_storage', args=['/path/to/file'])
        return result.get()

    def get_upload_status(self):
        status = None
        try:
            result = AsyncResult('process_upload')
            if result.status == 'success':
                status = "complete"
            elif result.status == 'failure':
                status = "failed"
        except Exception as e:
