        try {
            const response = await axios.get(url);
            return response.data;
        } catch (err) {
            if (err.response) {
                // Handle API rate limits or errors...
                console.error(`Error fetching data from ${url}: ${err.response.status} ${err.response.statusText}`);
            } else {
                // Handle network failures or timeouts...
                console.error(`Network error: ${err.message}`);
            }
        }
    }
}

