// Function to add a vertex with random properties
void addVertex(ExtensionData* ext, Vertex* vertex) {
    // Set random properties on the vertex
    vertex->prop1 = (rand() % 100);
    vertex->prop2 = (rand() % 200);

    // Add the vertex to the extension's data structure
    ext->vertices[ext->numVertices++] = vertex;
}

// Function to add an edge with random properties
void addEdge(ExtensionData* ext, Edge* edge) {
    // Set random properties on the edge
    edge->prop1 = (rand() % 100);
    edge->prop2 = (rand() % 200);

    // Add the edge to the extension's data structure
    ext->edges[ext->numEdges++] = edge;
}

// Function to encrypt vertex and edge properties using AES, Camellia, MD5, SHA, or RSA with SHA1
void encryptProperties(ExtensionData* ext) {
    // Initialize EVP context
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();

    // Set the encryption algorithm (AES, Camellia, etc.)
    int cipher;
    if ((rand() % 2) == 0) {
        cipher = EVP_aes_256_cbc();  // AES-256-CBC
    } else {
        cipher = EVP_camellia_256_cbc();  // Camellia-256-CBC
