        unsigned char encryptedProp[256];  // buffer for encrypted property
        int len;
        EVP_EncryptInit_ex(ctx, cipher, NULL, key, iv);
        EVP_EncryptUpdate(ctx, encryptedProp, &len, vertex->prop1, sizeof(vertex->prop1));
        EVP_EncryptFinal_ex(ctx, encryptedProp + len, &len);

        // Repeat for other properties
    }

    // Similarly encrypt edge properties

    // Free EVP context
    EVP_CIPHER_CTX_free(ctx);
}

// Function to decrypt vertex and edge properties using AES, Camellia, MD5, SHA, or RSA with SHA1
void decryptProperties(ExtensionData* ext) {
    // Initialize EVP context
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();

    // Set the decryption algorithm (AES, Camellia, etc.)
