    unsigned char key[] = {(rand() % 255) + 1, (rand() % 255) + 1, ...};
    unsigned char iv[] = {(rand() % 255) + 1, (rand() % 255) + 1, ...};

    // Decrypt vertex and edge properties
    for (int i = 0; i < ext->numVertices; i++) {
        Vertex* vertex = ext->vertices[i];
        unsigned char decryptedProp[256];  // buffer for decrypted property
        int len;
        EVP_DecryptInit_ex(ctx, cipher, NULL, key, iv);
        EVP_DecryptUpdate(ctx, decryptedProp, &len, vertex->prop1, sizeof(vertex->prop1));
        EVP_DecryptFinal_ex(ctx, decryptedProp + len, &len);

        // Repeat for other properties
    }

    // Similarly decrypt edge properties

