use std::collections::HashMap;
use std::fs;
use std::path::PathBuf;
use std::process::{Command, exit};
use std::thread;

use actix_web::{web, App, HttpResponse, HttpServer};
use futures::channel::mpsc;
use futures::stream::StreamExt;
use serde_json::json;

#[derive(Debug)]
struct Config {
    kafka_brokers: Vec<String>,
    data_sources: HashMap<String, String>, // Map of data source names to formats
    log_level: String,
}

impl Default for Config {
    fn default() -> Self {
        Config {
            kafka_brokers: vec!["localhost:9092".to_string()],
            data_sources: HashMap::new(),
            log_level: "info".to_string(),
        }
    }
}

async fn start_kafka_consumer(
    config: &Config,
    data_source_name: &str,
) -> Result<(), Box<dyn std::error::Error>> {
    let mut child = Command::new("kafka-console-consumer")
        .arg("--bootstrap-server")
        .arg(&config.kafka_brokers[0])
        .arg("--topic")
        .arg(data_source_name)
        .spawn()
        .unwrap();

    Ok(child.wait().unwrap())
}

async fn process_data(config: &Config) -> Result<(), Box<dyn std::error::Error>> {
    let mut kafka_consumers = vec![];

    for (data_source_name, data_source_format) in config.data_sources.iter() {
        match data_source_format.as_str() {
            "json" => {
                // JSON processing logic here
                println!("Processing JSON data from {}...", data_source_name);
            }
            "csv" => {
                // CSV processing logic here
                println!("Processing CSV data from {}...", data_source_name);
            }
            "binary" => {
                // Binary processing logic here
                println!("Processing binary data from {}...", data_source_name);
            }
            _ => return Err("Unsupported data source format".to_string().into()),
        }

        let kafka_consumer = start_kafka_consumer(config, data_source_name).await?;
        kafka_consumers.push(kafka_consumer);
    }

    Ok(())
}

#[actix_web::main]
async fn main() {
    let config_file_path = PathBuf::from("config.json");
    if !config_file_path.exists() {
        println!("Config file not found. Using default configuration.");
    } else {
        let config_json = fs::read_to_string(config_file_path).unwrap();
        let config: Config = serde_json::from_str(&config_json).unwrap();
        println!("Using custom configuration: {:?}", config);
    }

    let _ = process_data(&Config::default()).await;

    HttpServer::new(|| {
        App::new()
            .service(web::resource("/").to(|| HttpResponse::Ok().body("Hello, World!")))
    })
    .bind("0.0.0.0:8080")?
    .run()
    .unwrap();
}

