from typing import Dict, List

class LogSource(ABC):
    @abstractmethod
    def read_logs(self) -> List[Dict]:
        pass

class ServerLogSource(LogSource):
    def __init__(self, server_ip: str):
        self.server_ip = server_ip

    def read_logs(self) -> List[Dict]:
        # Simulate reading logs from a server
        return [
            {"log_id": 1, "server_ip": self.server_ip, "timestamp": 1643723400},
            {"log_id": 2, "server_ip": self.server_ip, "timestamp": 1643723410}
        ]

class ApplicationLogSource(LogSource):
    def __init__(self, app_name: str):
        self.app_name = app_name

    def read_logs(self) -> List[Dict]:
        # Simulate reading logs from an application
        return [
            {"log_id": 3, "app_name": self.app_name, "timestamp": 1643723400},
            {"log_id": 4, "app_name": self.app_name, "timestamp": 1643723410}
        ]

class IoTLogSource(LogSource):
    def __init__(self, device_id: str):
        self.device_id = device_id

    def read_logs(self) -> List[Dict]:
        # Simulate reading logs from an IoT device
        return [
            {"log_id": 5, "device_id": self.device_id, "timestamp": 1643723400},
            {"log_id": 6, "device_id": self.device_id, "timestamp": 1643723410}
        ]

class LogAggregator:
    def __init__(self):
        self.logs = []

    def aggregate_logs(self, log_sources: List[LogSource]):
        for log_source in log_sources:
            self.logs.extend(log_source.read_logs())

    def deduplicate_logs(self) -> None:
        self.logs = list(set(self.logs))

class LogTransformer:
    def __init__(self):
        pass

    def transform_logs(self, logs: List[Dict]) -> List[Dict]:
        # Simulate transforming logs
        return [
            {"log_id": log["log_id"], "transformed_data": f"Transformed {log['log_id']}"}
            for log in logs
        ]

class LogStorage:
    def __init__(self):
        self.stored_logs = []

    def store_logs(self, logs: List[Dict]) -> None:
        self.stored_logs.extend(logs)

class LogAnalyzer:
    def __init__(self):
        pass

    def analyze_logs(self, stored_logs: List[Dict]) -> Dict:
        # Simulate analyzing logs
        return {"analysis_result": "Some analysis result"}

class AlertSystem:
    def __init__(self):
        self.alerts = []

    def send_alert(self, rule: str) -> None:
        self.alerts.append(rule)

class LogPipeline:
    def __init__(self):
        self.log_aggregator = LogAggregator()
        self.log_transformer = LogTransformer()
        self.log_storage = LogStorage()
        self.log_analyzer = LogAnalyzer()
        self.alert_system = AlertSystem()

    def run(self, log_sources: List[LogSource]) -> None:
        self.log_aggregator.aggregate_logs(log_sources)
        deduplicated_logs = self.log_aggregator.deduplicate_logs()
        transformed_logs = self.log_transformer.transform_logs(deduplicated_logs)
        self.log_storage.store_logs(transformed_logs)
        analysis_result = self.log_analyzer.analyze_logs(self.log_storage.stored_logs)
        if analysis_result["analysis_result"] == "Some threshold exceeded":
            self.alert_system.send_alert("Alert sent")

# Example usage
log_pipeline = LogPipeline()
server_log_source = ServerLogSource("192.168.1.100")
app_log_source = ApplicationLogSource("My App")
iot_log_source = IoTLogSource("Device123")

log_pipeline.run([server_log_source, app_log_source, iot_log_source])
