// Define a struct to hold command execution information
typedef struct {
    char* command;
    int timeout; // in seconds
} Command;

// Define a function to execute a shell command
int execute_command(Command cmd) {
    pid_t child_pid = fork();
    if (child_pid == 0) { // Child process
        // Execute the command and exit
        system(cmd.command);
        exit(0);
    } else { // Parent process
        int status;
        waitpid(child_pid, &status, 0); // Wait for the child to finish
        return WEXITSTATUS(status); // Return the exit status of the command
    }
}

// Define a function to execute multiple shell commands in parallel
void* execute_commands(void* arg) {
    Command* cmds = (Command*)arg;
    int i;
    for (i = 0; i < 5; i++) { // Execute up to 5 commands in parallel
        pthread_create(&cmds[i].child_pid, NULL, &execute_command, &cmds[i]);
    }
}

int main() {
    Command cmds[5];
    int i;

    // Initialize the command execution information
    for (i = 0; i < 5; i++) {
        cmds[i].command = "ls -l";
        cmds[i].timeout = 10;
    }

    pthread_t threads[5];
    int thread_id = 0;

    // Create and start the worker threads
    for (i = 0; i < 5; i++) {
        if (pthread_create(&threads[thread_id], NULL, &execute_commands, &cmds[i]) != 0) {
            perror("Error creating thread");
            return 1;
        }
        thread_id++;
    }

    // Wait for the worker threads to finish
    for (i = 0; i < 5; i++) {
        pthread_join(threads[i], NULL);
