        // Handle TCP packet
    }
};

class UDP : public NetworkProtocol {
public:
    void handlePacket(std::string packet) override {
        // Handle UDP packet
    }
};

class SCTP : public NetworkProtocol {
public:
    void handlePacket(std::string packet) override {
        // Handle SCTP packet
    }
};

class ProtocolManager {
private:
    std::map<std::string, NetworkProtocol*> protocols_;
    std::mutex mutex_;

public:
    ~ProtocolManager() {
        for (auto& pair : protocols_) {
            delete pair.second;
        }
    }

    void addProtocol(std::string protocolName, NetworkProtocol* protocol) {
        std::lock_guard<std::mutex> lock(mutex_);
        protocols_[protocolName] = protocol;
    }

    void removeProtocol(std::string protocolName) {
        std::lock_guard<std::mutex> lock(mutex_);
        protocols_.erase(protocolName);
    }

    void handlePacket(std::string packet, std::string protocolName) {
        if (protocols_.count(protocolName)) {
            std::lock_guard<std::mutex> lock(mutex_);
            protocols_[protocolName]->handlePacket(packet);
        }
    }
};

class NetworkService {
public:
