#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>
#include <mutex>
#include <thread>
#include <chrono>

// Event record structure
struct NetworkEventRecord {
    int timestamp;
    std::string eventType;
    std::string metadata;
};

// Event cache layer
class EventCache {
public:
    EventCache(size_t capacity) : capacity_(capacity), cache_{} {}

    void put(const NetworkEventRecord& event, size_t expirationTime) {
        auto it = cache_.find(event.timestamp);
        if (it == cache_.end()) {
            // If not found, add new entry with expiration time
            cache_[event.timestamp] = {expirationTime, event};
        } else {
            // If found, update expiration time if necessary
            if (cache_[event.timestamp].second.expirationTime < expirationTime) {
                cache_[event.timestamp].second.expirationTime = expirationTime;
            }
        }
    }

    NetworkEventRecord get(size_t timestamp) {
        auto it = cache_.find(timestamp);
        if (it == cache_.end()) {
            // If not found, return empty record
            return {};
        } else {
            // If found, check expiration time and update if necessary
            auto& event = it->second.second;
            if (event.expirationTime <= std::chrono::system_clock::now().time_since_epoch().count) {
                // Cache hit but expired, remove from cache
                cache_.erase(it);
                return {};
            }
            return event.second;
        }
    }

private:
    size_t capacity_;
    std::unordered_map<size_t, std::pair<std::chrono::time_point<std::chrono::system_clock>, NetworkEventRecord>> cache_;
};

// Event management library
class EventManager {
public:
    EventManager(size_t cacheCapacity) : eventCache_(cacheCapacity), retentionPeriod_(std::chrono::hours(1)) {}

    void addEvent(const NetworkEventRecord& event) {
        // Add event to internal storage (not shown)
        // ...
    }

    void cleanup() {
        auto now = std::chrono::system_clock::now();
        for (auto it = eventCache_.begin(); it != eventCache_.end();) {
            if (it->second.expirationTime <= now.time_since_epoch().count) {
                // Cache hit and expired, remove from cache
                it = eventCache_.erase(it);
            } else {
                ++it;
            }
        }
    }

    void configureRetentionPeriod(const std::chrono::duration<double>& retentionPeriod) {
        retentionPeriod_ = retentionPeriod;
    }

private:
    EventCache eventCache_;
    std::chrono::duration<double> retentionPeriod_;
};

// External REST API client
class RestApiClient {
