// Function to read file line by line
void readFile(char* filename) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error opening file %s\n", filename);
        return;
    }

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        // Process the line here
        // For example:
        int count = 0;
        char* p = strtok(line, " ");
        while (p) {
            p = strtok(NULL, " ");
            count++;
        }
        printf("Line contains %d words\n", count);
    }

    fclose(file);
}

// Function to get word frequency
void getWordFrequency(char* filename) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error opening file %s\n", filename);
        return;
    }

    WordFrequency wf;

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        // Process the line here
        // For example:
        int count = 0;
        char* p = strtok(line, " ");
        while (p) {
            p = strtok(NULL, " ");
            count++;
        }
        wf.word = p;
        wf.count = count;
    }

    fclose(file);
}

int main(int argc, char* argv[]) {
    // Check if correct number of arguments are passed
    if (argc != 2) {
        printf("Usage: %s <filename>\n", argv[0]);
        return 1;
    }

    char* filename = argv[1];

    // Read file line by line
    readFile(filename);

    // Get word frequency
    getWordFrequency(filename);

    return 0;
}

