class CSVData {
public:
    std::string filename;
    int row_count = 0;

    // Constructor to initialize CSV data
    CSVData(const std::string& filename) : filename(filename) {}

    // Function to read CSV file and extract specific columns based on dynamic configuration schema
    void process_csv_data() {
        std::ifstream csv_file(filename);
        if (!csv_file.is_open()) {
            std::cerr << "Error opening the CSV file." << std::endl;
            return;
        }

        // Read the CSV file row by row and extract specific columns based on dynamic configuration schema
        while (std::getline(csv_file, line)) {
            // Split the line into individual values
            std::vector<std::string> values = split(line, ',');

            // Check if the number of values matches the expected count for the current line
            if (values.size() != row_count) {
                std::cerr << "Error: Inconsistent data in CSV file." << std::endl;
                return;
            }

            // Extract specific columns based on dynamic configuration schema
            for (int i = 0; i < values.size(); i++) {
                // Check if the current column matches the expected column name or index
                if (expected_columns[i] == values[i]) {
                    extracted_data.push_back(values[i]);
                }
            }

            row_count++;
        }
    }

    // Function to split a string into individual values based on a delimiter
    std::vector<std::string> split(const std::string& line, char delimiter) {
        std::vector<std::string> values;
        std::stringstream ss(line);
        std::string value;

        while (std::getline(ss, value, delimiter)) {
            values.push_back(value);
        }

        return values;
    }
};

// Define a class to represent JSON data
class JSONObject {
