void* resolveHostname(void* arg) {
    // Get the hostname from the shared memory region
    char hostname[MAX_HOSTNAME_LENGTH];
    pthread_memcpy(hostname, arg, MAX_HOSTNAME_LENGTH);

    // Perform DNS resolution using the configured timeout and retry logic
    int timeout = 1000; // configurable timeout in milliseconds
    int retries = 3;     // configurable number of retries

    while (retries--) {
        // Send a DNS query to the configured server(s)
        struct sockaddr_in server;
        server.sin_family = AF_INET;
        server.sin_port = htons(DNS_PORT);
        inet_pton(AF_INET, "8.8.8.8", &server.sin_addr); // example DNS server

        // Wait for response and handle any errors
        if (handleTimeout(timeout)) {
            logError("DNS resolution failed", hostname, 1);
            return NULL;
        }

        // Check the response for errors or timeouts
        if (!strncasecmp(hostname, " NXDOMAIN", 10) || strncasecmp(hostname, " SERVFAIL", 9) == 0) {
            logError("Invalid DNS response", hostname, 1);
            return NULL;
        }

        // Store the response in the shared memory region
        pthread_memcpy(responses[0].hostname, hostname, MAX_HOSTNAME_LENGTH);
        pthread_memcpy(responses[0].response, " DNS resolved successfully!", MAX_RESPONSE_LENGTH);

        // Release the semaphore to signal completion
        sem_post(&semaphore);
    }

    return NULL;
}

void handleTimeout(int timeout) {
    // Handle timeouts and retries as needed...
    sleep(timeout / 1000); // example implementation
    return false;
}

void logError(const char* message, const char* hostname, int level) {
    // Log the error to the configured logging service...
    printf("%d: %s - %s\n", level, message, hostname);
}
