    int sockets[MAX_CLIENTS];
    packet_info_t packets[MAX_CLIENTS];

    // Initialize semaphore
    sem_init(&sem, 0, MAX_CLIENTS);

    for (int i = 0; i < MAX_CLIENTS; i++) {
        // Create socket and bind to port
        int sock = socket(AF_INET, SOCK_STREAM, 0);
        struct sockaddr_in addr;
        addr.sin_family = AF_INET;
        addr.sin_port = htons(8080);
        inet_pton(AF_INET, "127.0.0.1", &addr.sin_addr);

        // Set QoS level and source IP
        packets[i].qos_level = i % QOS_LEVELS;
        strcpy(packets[i].source_ip, inet_ntoa(addr.sin_addr));

        // Start processing thread for each client
        pthread_create(&threads[i], NULL, process_packet, &packets[i]);
