#include <json-c/json.h>
#include <pthread.h>

#define MAX_ARGUMENTS 10
#define RETRIES 5
#define BACKOFF_MULTIPLIER 2

typedef struct {
    char* message;
    int num_args;
    json_object* metadata;
} LogMessage;

int conditionalLogError(int condition, ...) {
    static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    static pthread_once_t once_control = PTHREAD_ONCE_INIT;

    pthread_once(&once_control, () -> {
        // Initialize logging system
    });

    va_list args;
    va_start(args, condition);

    LogMessage message;
    message.message = NULL;
    message.num_args = 0;
    message.metadata = json_object_new_object();

    for (int i = 0; i < MAX_ARGUMENTS && i < va_arg_count(); i++) {
        char* arg = va_arg(args, char*);
        if (i == 0) {
            message.message = arg;
        } else {
            json_object_object_add(message.metadata, "arg", json_object_new_string(arg));
        }
        message.num_args++;
    }

    va_end(args);

    if (!condition) {
        // Log the error message
        for (int i = 0; i < RETRIES; i++) {
            int retry = (1 << i);
            pthread_mutex_lock(&mutex);
            try {
                // Log the message to the external system
                json_object_put(message.metadata); // Free any allocated metadata
                return;
            } catch (const std::exception& e) {
                if (i < RETRIES - 1) {
                    // Retry with exponential backoff
                    sleep(retry);
                } else {
                    // Log error and exit
                    LOG_ERROR("Failed to log message after %d retries", retry);
                    return;
                }
            }
        }
    }

    pthread_mutex_unlock(&mutex);

    return 0;
}
