class ExternalLoggingService {
public:
    virtual void log(const std::string& message) = 0;
};

void appendOrInsertWithLogging(std::forward_list<std::string>& list, const std::string& target, const std::string& value, ExternalLoggingService& loggingService) {
    std::lock_guard<std::recursive_mutex> lock(mutex); // Ensure thread safety

    auto it = list.begin();
    bool found = false;
    while (it != list.end()) {
        if (*it == target) {
            found = true;
            break;
        }
        ++it;
    }

    if (found) {
        list.insert_after(it, value);
    } else {
        list.append(value);
    }

    try {
        // Attempt to log the operation
        loggingService.log(std::string("Operation ") + (found ? "inserted" : "appended") + " successfully. Target: " + target + ", Value: " + value + ". List size: " + std::to_string(list.size()));
    } catch (...) {
        // Handle external logging service failure
        try {
            loggingService.log(std::string("Error during operation. Operation ") + (found ? "inserted" : "appended") + " failed. Target: " + target + ", Value: " + value + ". List size: " + std::to_string(list.size()));
        } catch (...) {
            // If the logging service fails again, log an error message
            std::cerr << "Error during operation. Operation " << (found ? "inserted" : "appended") << " failed. Target: " << target << ", Value: " << value << ". List size: " << list.size() << "." << std::endl;
        }
    }
}
