namespace UserAuthenticationService
{
    public class UserAuthenticator
    {
        private readonly List<IAuthenticationService> _authServices;
        private readonly Dictionary<string, string> _connectionStrings;
        private readonly Dictionary<string, Func<SqlConnection>> _dbQueryFunctions;

        public UserAuthenticator(List<IAuthenticationService> authServices, 
            Dictionary<string, string> connectionStrings, 
            Dictionary<string, Func<SqlConnection>> dbQueryFunctions)
        {
            _authServices = authServices;
            _connectionStrings = connectionStrings;
            _dbQueryFunctions = dbQueryFunctions;
        }

        public async Task<UserData> AuthenticateUser(string userId, 
            CancellationToken cancellationToken = default)
        {
            // Input validation
            if (string.IsNullOrEmpty(userId))
                throw new ArgumentException("Invalid user ID");

            foreach (var authService in _authServices)
            {
                try
                {
                    var authenticationResponse = await authService.AuthenticateAsync(userId);
                    if (!string.IsNullOrEmpty(authenticationResponse))
                    {
                        return new UserData { Id = userId, Token = authenticationResponse };
                    }
                }
                catch (HttpRequestException ex) when (ex.StatusCode == HttpStatusCode.ServiceUnavailable)
                {
                    // Exponential backoff for retries
                    await Task.Delay(TimeSpan.FromSeconds(Math.Pow(2, 1)), cancellationToken);
                }
            }

            throw new AuthenticationException("Failed to authenticate user");
        }

