            var dbQueryFunction = _dbQueryFunctions["default"];
            using (var connection = dbQueryFunction())
            {
                using (var command = new SqlCommand("SELECT * FROM Users WHERE Id = @userId", connection))
                {
                    command.Parameters.AddWithValue("@userId", userId);
                    using (var reader = command.ExecuteReader())
                    {
                        while (await reader.ReadAsync(cancellationToken))
                        {
                            return new UserData
                            {
                                Id = reader["Id"].ToString(),
                                // Map retrieved user data to a specified schema
                            };
                        }
                    }
                }
            }
