use Predis\Client as PredisClient;

class MultiTenantApi {
    private $config;
    private $logger;
    private $predis;
    private $client;

    public function __construct(array $config) {
        $this->config = $config;
        $this->logger = new Logger('multi_tenant_api');
        $this->predis = new PredisClient($this->config['predis']);
        $this->client = new Client(['base_uri' => $this->config['message_broker']]);
    }

    public function login(array $credentials) {
        // Authenticate user with external authentication provider
        $authResponse = $this->client->post('authenticate', ['json' => $credentials]);

        if ($authResponse->getStatusCode() !== 200) {
            throw new Exception('Invalid credentials');
        }

        $token = json_decode($authResponse->getBody(), true)['token'];

        // Store token in distributed cache for faster access
        $this->predis->setex('token_' . $credentials['username'], 3600, $token);

        return $token;
    }

    public function getUserData(array $credentials) {
        // Get user data from external services
        $userData = $this->client->get('user_data', ['query' => ['username' => $credentials['username']]])->getBody()->json();

        if ($userData['status'] === 'error') {
            throw new Exception($userData['message']);
        }

        return $userData;
    }

    public function updateUserData(array $data, array $credentials) {
        // Check for concurrent updates using optimistic locking
        $token = $this->predis->get('token_' . $credentials['username']);
        if ($token === false || $token !== $data['token']) {
            throw new Exception('Concurrent update detected');
        }

        // Update user data in external services
        $updateResponse = $this->client->put('user_data', ['json' => $data]);

        if ($updateResponse->getStatusCode() !== 200) {
            throw new Exception('Update failed');
        }

        // Store updated token in distributed cache
        $this->predis->setex('token_' . $credentials['username'], 3600, $data['new_token']);

        return $data;
    }
}

// Initialize API instance with config and start the server
$api = new MultiTenantApi([
    'predis' => ['host' => 'localhost', 'port' => 6379],
