// Rust utility function for compiling crate and measuring compilation time
use std::process::{Command, exit};
use std::time::Instant;

fn compile_rust_crate(crate_name: &str) -> Result<(), Box<dyn std::error::Error>> {
    let start = Instant::now();
    let output = Command::new("cargo")
        .arg("build")
        .arg("--manifest-path")
        .arg(crate_name)
        .output()?;

    if !output.status.success() {
        eprintln!("Compilation failed with exit code {}", output.status.exit_code());
        for line in String::from_utf8_lossy(&output.stdout).lines() {
            eprintln!("{}", line);
        }
        for line in String::from_utf8_lossy(&output.stderr).lines() {
            eprintln!("{}", line);
        }
        exit(1);
    }

    let duration = start.elapsed();
    println!("Compilation took {:.2} seconds", duration.as_secs_f64());

    Ok(())
}

fn main() {
    if let Err(err) = compile_rust_crate("my_crate") {
        println!("Error: {}", err);
        exit(1);
    }
}
