      config.asyncScripts.map(script => asyncScriptLoader.loadScript(path.join(__dirname, script)))
    );
  }

  // Function to load scripts with defer attribute
  function loadDeferScripts() {
    return Promise.all(
      config.deferScripts.map(script => asyncScriptLoader.loadScriptWithDefer(path.join(__dirname, script)))
    );
  }

  // Function to deserialize footer content
  function deserializeFooter() {
    const { data } = require('./footerData.json');
    return data.footerComponents;
  }

  // Main execution flow
  async function execute() {
    try {
      // Load scripts asynchronously
      await loadAsyncScripts();

      // Load scripts with defer attribute
      await loadDeferScripts();

      // Deserialize footer content
      const footerComponents = deserializeFooter();
      console.log('Footer components:', footerComponents);

      // Render footer components
      const renderHTML = () => {
        return footerComponents.map(component => `<div>${component}</div>`).join('');
      };

      document.getElementById('footer').innerHTML = renderHTML();

    } catch (error) {
      errorLogger.logError(error);
    }
  }

  execute();
}

module.exports = deserializeFooterContent;
