    new RegExp('^(Psalms|Proverbs|Ecclesiastes|Song of Solomon|Isaiah|Jeremiah|Lamentations|Ezekiel|Daniel|Hosea|Joel|Amos|Obadiah|Jonah|Micah| Nahum|Habakkuk|Zephaniah|Haggai|Zechariah|Malachi)', 'i')
