      .then(function(response) {
        var dialogFields = response.data;
        angular.forEach(dialogFields, function(field) {
          if (field.name in oldTestamentRegexes) {
            // Extract Old Testament book names from the text
            var oldTestamentBooks = extractOldTestamentBooks(field.text);
            // Update the dialog field with the extracted book names and frequency counts
            field.text = oldTestamentBooks.join(', ');
          }
        });
      }, function(error) {
        console.error('Error refreshing dialog fields:', error);
      });
  };

  service.extractOldTestamentBooks = function(text) {
    var oldTestamentBooks = {};
    angular.forEach(oldTestamentRegexes, function(regex) {
      var matches = text.match(regex);
      if (matches && matches.length > 0) {
        for (var i = 0; i < matches.length; i++) {
          var match = matches[i].trim();
          if (!oldTestamentBooks[match]) {
            oldTestamentBooks[match] = 1;
          } else {
            oldTestamentBooks[match]++;
          }
        }
      }
    });
    return Object.keys(oldTestamentBooks).map(function(book) {
      return { name: book, frequency: oldTestamentBooks[book] };
    });
  };

