// Filtering and paginating module
export class FilterPaginator {
  constructor(rootElement, filterOptions = {}) {
    this.rootElement = rootElement;
    this.filterOptions = filterOptions;
    this.currentPage = 1;
    this.pageSize = 10;
  }

  setFilterOptions(options) {
    this.filterOptions = options;
  }

  setPage(pageNumber) {
    this.currentPage = pageNumber;
  }

  setPageSize(size) {
    this.pageSize = size;
  }

  // Filter and paginate the DOM tree
  filterAndPaginate() {
    const filteredElements = Array.from(this.rootElement.children)
      .filter((element, index) => {
        for (const [attributeName, attributeValue] of Object.entries(
          this.filterOptions
        )) {
          if (
            element.getAttribute(attributeName) !== null &&
            element.getAttribute(attributeName).toLowerCase() !==
              attributeValue.toLowerCase()
          ) {
            return false;
          }
        }
        return true;
      })
      .slice((this.currentPage - 1) * this.pageSize, this.currentPage * this.pageSize);

    const paginatedElements = filteredElements.length > 0 ? filteredElements : [];

    // Update the DOM with the filtered and paginated elements
    this.rootElement.innerHTML = '';
    paginatedElements.forEach((element) => this.rootElement.appendChild(element));

    return paginatedElements;
  }
}

