    public void processIntegersAsync(int[] integers) {
        IntStream.range(0, integers.length)
                .parallel()
                .mapToObj(i -> CompletableFuture.supplyAsync(() -> {
                    int num1 = integers[i];
                    // Fetch metadata and validate uniqueness
                    Metadata metadata = ExternalDataSource.fetchMetadata(num1);
                    if (metadata == null || !metadata.isValid()) {
                        return 0;
                    }
                    return processPair(integers, i, num1);
                }, executor))
                .thenAcceptAsync(results -> {
                    int disjointPairsCount = Arrays.stream(results.toArray()).filter(count -> count > 0).sum();
                    LOG.info("Disjoint pairs count: {}", disjointPairsCount);
                });
    }

    private int processPair(int[] integers, int i, int num1) {
        for (int j = i + 1; j < integers.length; j++) {
            if (num1 != integers[j]) {
                // Check if pair is disjoint
                if (!isDisjoint(num1, integers[j])) {
                    return 0;
                }
                // Count the pair
