<?php

// Redis session cache
$redis = new Redis();
$redis->connect('localhost', 6379);

// Session management API
class SessionManager {
    public function startSession($userId) {
        // Create a unique session ID
        $sessionId = generateUUID();

        // Store the session in Redis with a TTL of 1 hour
        $redis->setex($sessionId, 3600, json_encode(['userId' => $userId]));

        return $sessionId;
    }

    public function getSession($sessionId) {
        // Retrieve the session from Redis
        $sessionData = $redis->get($sessionId);

        if (!$sessionData) {
            return null;
        }

        return json_decode($sessionData, true);
    }

    public function refreshSession($sessionId) {
        // Update the session TTL in Redis
        $redis->expire($sessionId, 3600);
    }

    public function invalidateSession($sessionId) {
        // Delete the session from Redis
        $redis->delete($sessionId);
    }
}

