import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PatchMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestAttribute;
import org.springframework.web.bind.annotation.RestController;

import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.RejectedExecutionHandler;
import java.util.logging.Level;
import java.util.logging.Logger;
import java.util.stream.Collectors;

@SpringBootApplication
@RestController
public class BackgroundProcessingMicroservice {

    private static final Logger logger = Logger.getLogger(BackgroundProcessingMicroservice.class.getName());

    public static void main(String[] args) {
        SpringApplication.run(BackgroundProcessingMicroservice.class, args);
    }

    @Bean
    public ExecutorService executorService() {
        return Executors.newFixedThreadPool(10, new RejectedExecutionHandler() {
            @Override
            public void rejectedExecution(Runnable r, ThreadPoolExecutor executor) {
                logger.log(Level.SEVERE, "Task execution failed", r);
            }
        });
    }

    @GetMapping("/resources")
    public List<Resource> getResources() {
        // fetch data from external APIs and store in NoSQL database
        return dbResources.values().stream().collect(Collectors.toList());
    }

    @PutMapping("/resources/{id}")
    public Resource updateResource(@RequestAttribute String id, @RequestBody Resource updatedResource) {
        // update resource data and return updated or default resource data
        return dbResources.computeIfAbsent(id, k -> updatedResource);
    }

    @DeleteMapping("/resources/{id}")
    public void deleteResource(@RequestAttribute String id) {
        // remove resource from NoSQL database
        dbResources.remove(id);
    }

    private Map<String, Resource> dbResources = new HashMap<>();
}
