**C Code for DNS Resolution:**
```c
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

#define DNS_RESOLUTION_THREADS 5

// Function to perform DNS resolution using standard library functions
void* dns_resolve(void* arg) {
    // Get the hostname and IP address from the argument
    char* hostname = (char*)arg;
    char* ip_address;

    // Perform DNS resolution using gethostbyname()
    struct hostent* host_entry = gethostbyname(hostname);
    if (host_entry == NULL) {
        // Handle DNS resolution failure
        printf("DNS resolution failed for %s\n", hostname);
        return NULL;
    }

    // Get the IP address from the host entry
    ip_address = inet_ntoa(*(struct in_addr*)host_entry->h_addr);

    // Print the resolved IP address
    printf("%s resolved to %s\n", hostname, ip_address);

    free(host_entry);
    return NULL;
}

// Function to start DNS resolution threads
void start_dns_resolution(char* hostnames[], int num_hostnames) {
    pthread_t threads[DNS_RESOLUTION_THREADS];
    int i;

    // Create and start the DNS resolution threads
    for (i = 0; i < DNS_RESOLUTION_THREADS; i++) {
        if (pthread_create(&threads[i], NULL, dns_resolve, hostnames[i]) != 0) {
            printf("Error creating thread %d\n", i);
            return;
        }
    }

    // Wait for the threads to finish
    for (i = 0; i < DNS_RESOLUTION_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }
}

// Main function
int main() {
    char* hostnames[] = {"example.com", "another.example.com"};
    int num_hostnames = sizeof(hostnames) / sizeof(char*);

    start_dns_resolution(hostnames, num_hostnames);

    return 0;
}
```

