import os
from flask import Flask, request, jsonify
from flask_sqlalchemy import SQLAlchemy
from flask_caching import Cache
from flask_redis import FlaskRedis
from flask_api import status
from flask_marshmallow import Marshmallow
from rq import Queue
from worker import conn

app = Flask(__name__)
app.config["SQLALCHEMY_DATABASE_URI"] = os.environ.get("DATABASE_URL", "sqlite:///inventory.db")
db = SQLAlchemy(app)
cache = Cache(app, config={"CACHE_TYPE": "RedisCache"})
redis = FlaskRedis(app)
marshmallow = Marshmallow(app)

class Product(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(100), nullable=False)
    price = db.Column(db.Float, nullable=False)
    stock_level = db.Column(db.Integer, nullable=False)

class Supplier(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(100), nullable=False)
    api_url = db.Column(db.String(200), nullable=False)

@app.route('/products', methods=['GET'])
@cache.cached(timeout=60)  # cache for 1 minute
def get_products():
    products = Product.query.all()
    return jsonify([product.to_dict() for product in products])

@app.route('/products/<int:product_id>', methods=['GET'])
def get_product(product_id):
    product = Product.query.get_or_404(product_id)
    return jsonify(product.to_dict())

@app.route('/replenish', methods=['POST'])
def replenish():
    data = request.get_json()
    if not data:
        return {'error': 'Invalid input'}, status.HTTP_400_BAD_REQUEST
    try:
        product = Product.query.get(data['product_id'])
        product.stock_level += data['amount']
        db.session.commit()
        return jsonify({'message': f"Replenished {data['amount']} units of {product.name}"})
    except Exception as e:
        return {'error': str(e)}, status.HTTP_500_INTERNAL_SERVER_ERROR

if __name__ == '__main__':
    app.run(debug=True)
```

This code sets up a Flask API with SQLAlchemy for database operations, Cache and Flask-Redis for caching, and Marshmallow for serialization. It defines two models: Product and Supplier. The API has endpoints to retrieve all products, get a specific product by ID, and replenish stock levels.']

