#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    time_t timestamp;
    char* payload;
    void* sensor_config;
} DataRecord;

typedef struct Node {
    DataRecord data;
    struct Node* next;
} Node;

Node* create_node(DataRecord* data) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;

    node->data = *data;
    node->next = NULL;
    return node;
}

void add_node(Node** head, DataRecord* data) {
    Node* new_node = create_node(data);
    if (!new_node) return;

    if (*head == NULL || (*head)->data.timestamp > new_node->data.timestamp) {
        new_node->next = *head;
        *head = new_node;
    } else {
        Node* current = *head;
        while (current->next && current->next->data.timestamp <= new_node->data.timestamp)
            current = current->next;

        new_node->next = current->next;
        current->next = new_node;
    }
}

void remove_node(Node** head, DataRecord* data) {
    Node* current = *head;
    Node* prev = NULL;

    while (current && current->data.timestamp != data->timestamp)
        if ((prev = current)->next == current)
            current = current->next;
        else
            current = current->next;

    if (current) {
        if (prev) prev->next = current->next;
        else *head = current->next;

        free(current);
    }
}

void print_list(Node* head) {
    while (head) {
        printf("Timestamp: %ld, Payload: %s, Sensor Config: %p\n", 
               head->data.timestamp, head->data.payload, head->data.sensor_config);
        head = head->next;
    }
}
