            // Directory Validation
            if (!Directory.Exists(directoryPath))
                throw new FileNotFoundException($"The specified directory '{directoryPath}' does not exist.");

            var webConfigFile = Path.Combine(directoryPath, "web.config");
            var appSettingsFile = Path.Combine(directoryPath, "appsettings.json");
            var databaseConnectionFile = Path.Combine(directoryPath, "database_connection.json");

            if (!File.Exists(webConfigFile) || !File.Exists(appSettingsFile) || !File.Exists(databaseConnectionFile))
                throw new FileNotFoundException($"The directory '{directoryPath}' is missing necessary files.");

            // Database Connection Validation
            try
            {
                var databaseConnectionString = File.ReadAllText(databaseConnectionFile);
                using (var connection = new SqlConnection(databaseConnectionString))
                {
                    await connection.OpenAsync();
                }
            }
            catch (Exception ex)
            {
                throw new Exception($"Failed to establish a database connection: {ex.Message}");
            }

            // Concurrency Handling
            while (!_distributedLock.Wait(1000, CancellationToken.None))
                await Task.Delay(500);

            try
            {
                // Register the web application
                // ...
            }
            finally
            {
                _distributedLock.Release();
            }
        }
    }
}
