using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Threading.Tasks;

namespace DataStreamProcessor
{
    public class StreamDataProcessor
    {
        private const int BUFFER_SIZE = 1024 * 8; // 8 MB

        public async Task ProcessDataStream(Stream inputStream, Action<int> callback)
        {
            using var streamReader = new StreamReader(inputStream);
            long bytesRead = 0;
            while ((await streamReader.ReadLineAsync()) != null)
            {
                bytesRead += BUFFER_SIZE;
                if (bytesRead % 1024 * 16 == 0) // process every 16 MB
                {
                    callback(bytesRead / 1024 / 1024); // report max value
                }
            }
        }

        public async Task<double> CalculateMeanAsync(Stream inputStream)
        {
            long bytesRead = 0;
            double sum = 0;
            using var streamReader = new StreamReader(inputStream);
            while ((await streamReader.ReadLineAsync()) != null)
            {
                bytesRead += BUFFER_SIZE;
                foreach (var line in await streamReader.ReadLineAsync().Split('\n'))
                {
                    sum += int.Parse(line.Trim());
                }
            }
            return sum / bytesRead;
        }

        public async Task<double> CalculateMedianAsync(Stream inputStream)
        {
            long bytesRead = 0;
            List<int> numbers = new List<int>();
            using var streamReader = new StreamReader(inputStream);
            while ((await streamReader.ReadLineAsync()) != null)
            {
                bytesRead += BUFFER_SIZE;
                foreach (var line in await streamReader.ReadLineAsync().Split('\n'))
                {
                    numbers.Add(int.Parse(line.Trim()));
                }
            }
            numbers.Sort();
            return numbers[numbers.Count / 2];
        }

        public async Task<int> CalculateModeAsync(Stream inputStream)
        {
            long bytesRead = 0;
            Dictionary<int, int> frequencyMap = new Dictionary<int, int>();
            using var streamReader = new StreamReader(inputStream);
            while ((await streamReader.ReadLineAsync()) != null)
            {
                bytesRead += BUFFER_SIZE;
                foreach (var line in await streamReader.ReadLineAsync().Split('\n'))
                {
                    int number = int.Parse(line.Trim());
                    if (!frequencyMap.ContainsKey(number))
                    {
                        frequencyMap.Add(number, 0);
                    }
                    frequencyMap[number]++;
                }
            }
            return frequencyMap.Aggregate((x, y) => x.Value > y.Value ? x : y).Key;
        }
    }

    public class SecureDataHandler
    {
        private const int KEY_SIZE = 32; // 256-bit key

        public async Task EncryptDataStream(Stream inputStream, string key)
        {
            using var aes = Aes.Create();
            aes.Key = Convert.FromBase64String(key);
            using var encryptor = aes.CreateEncryptor();
            using var memoryStream = new MemoryStream();
            await inputStream.CopyToAsync(memoryStream);
            byte[] encryptedBytes = encryptor.TransformFinalBlock(memoryStream.ToArray(), 0, (int)memoryStream.Length);
            memoryStream.SetLength(0);
            memoryStream.Write(encryptedBytes, 0, encryptedBytes.Length);
            await Task.Yield();
        }

        public async Task DecryptDataStream(Stream inputStream, string key)
        {
            using var aes = Aes.Create();
            aes.Key = Convert.FromBase64String(key);
            using var decryptor = aes.CreateDecryptor();
            using var memoryStream = new MemoryStream();
            await inputStream.CopyToAsync(memoryStream);
            byte[] decryptedBytes = decryptor.TransformFinalBlock(memoryStream.ToArray(), 0, (int)memoryStream.Length);
            memoryStream.SetLength(0);
            memoryStream.Write(decryptedBytes, 0, decryptedBytes.Length);
            await Task.Yield();
        }
