import java.io.*;
import java.util.logging.*;

public class ScalableLogger {
    private static Logger logger;
    private static File logFile;
    private static boolean remoteLoggingEnabled;

    public static void main(String[] args) {
        configureLogger();
        // Sample usage: logging levels and outputs
        logger.info("This is an INFO message.");
        logger.warn("Warning log entry.");
        logger.error("Error occurred.");

        try (FileWriter writer = new FileWriter(logFile, true)) {
            PrintWriter printWriter = new PrintWriter(writer);
            printWriter.println("Sample log entry.");
        } catch (IOException ex) {
            System.out.println("Exception writing to file: " + ex.getMessage());
        }

        if (remoteLoggingEnabled) {
            try (Socket socket = new Socket("remote.logging.server", 1234)) {
                OutputStream outputStream = socket.getOutputStream();
                PrintStream printStream = new PrintStream(outputStream);
                printStream.println("Remote log entry.");
            } catch (IOException ex) {
                System.out.println("Exception connecting to remote logging server: " + ex.getMessage());
            }
        }
    }

    private static void configureLogger() {
        logger = Logger.getLogger(ScalableLogger.class.getName());

        // Configure file output
        logFile = new File("log_file.log");
        FileHandler fileHandler;
        try {
            fileHandler = new FileHandler(logFile.getAbsolutePath(), 1000, 1);
            logger.addHandler(fileHandler);
        } catch (IOException ex) {
            System.out.println("Exception configuring file logging: " + ex.getMessage());
        }

        // Configure remote logging
        remoteLoggingEnabled = Boolean.getBoolean("remote.logging.enabled");
        if (remoteLoggingEnabled) {
            SocketHandler socketHandler;
            try {
                socketHandler = new SocketHandler(new InetSocketAddress("remote.logging.server", 1234));
                logger.addHandler(socketHandler);
            } catch (IOException ex) {
                System.out.println("Exception configuring remote logging: " + ex.getMessage());
                remoteLoggingEnabled = false;
            }
        }

        // Configure log levels
        logger.setLevel(Level.parse(System.getProperty("logging.level", Level.ALL.toString())));
    }
}
