import java.io.*;
import java.util.logging.*;

public class SocketHandler extends Handler {
    private final Socket socket;

    public SocketHandler(InetSocketAddress address) throws IOException {
        this.socket = new Socket(address.getHostName(), address.getPort());
    }

    @Override
    public void publish(LogRecord record) {
        try (OutputStream outputStream = socket.getOutputStream()) {
            PrintStream printStream = new PrintStream(outputStream);
            printStream.println(record.getMessage());
        } catch (IOException ex) {
            System.out.println("Exception publishing log entry to remote logging server: " + ex.getMessage());
        }
    }

    @Override
    public void flush() {}

    @Override
    public void close() throws SecurityException {
        try {
            socket.close();
        } catch (IOException ex) {
            System.out.println("Exception closing remote logging socket: " + ex.getMessage());
        }
    }
}
