from typing import Dict, List
from pydantic import BaseModel

class Configuration(BaseModel):
    __root__: Dict[str, str]

class ConfigService:
    def __init__(self):
        self.configs = {}
        self.data_sources = {
            "local_files": {"path": "/config"},
            "remote_databases": {"host": "database_host", "port": 5432},
            "cloud_storage": {"bucket_name": "my_bucket"}
        }

    def load_config(self, config_type: str) -> Configuration:
        if config_type not in self.data_sources:
            raise ValueError(f"Unsupported configuration type: {config_type}")

        data_source = self.data_sources[config_type]

        if config_type == "local_files":
            try:
                with open(data_source["path"], "r") as file:
                    return Configuration.parse_file(file)
            except FileNotFoundError:
                pass
        elif config_type == "remote_databases":
            try:
                response = requests.get(f"{data_source['host']}:{data_source['port']}/config")
                if response.status_code == 200:
                    return Configuration.parse_json(response.json())
                else:
                    raise ValueError("Failed to retrieve configuration from remote database")
            except Exception as e:
                print(f"Error loading config from remote database: {e}")
        elif config_type == "cloud_storage":
            try:
                response = requests.get(f"https://s3.amazonaws.com/{data_source['bucket_name']}/config.json")
                if response.status_code == 200:
                    return Configuration.parse_json(response.json())
                else:
                    raise ValueError("Failed to retrieve configuration from cloud storage")
            except Exception as e:
                print(f"Error loading config from cloud storage: {e}")

        return Configuration()

    def update_config(self, config_type: str, config_data: Dict[str, str]) -> None:
        if config_type not in self.data_sources:
            raise ValueError(f"Unsupported configuration type: {config_type}")

        data_source = self.data_sources[config_type]

        if config_type == "local_files":
            with open(data_source["path"], "w") as file:
                json.dump(config_data, file)
        elif config_type == "remote_databases":
            response = requests.put(f"{data_source['host']}:{data_source['port']}/config", json=config_data)
            if response.status_code != 200:
                raise ValueError("Failed to update configuration in remote database")
        elif config_type == "cloud_storage":
            response = requests.put(f"https://s3.amazonaws.com/{data_source['bucket_name']}/config.json", json=config_data)
            if response.status_code != 200:
                raise ValueError("Failed to update configuration in cloud storage")

    def get_config(self, config_type: str) -> Configuration:
        if config_type not in self.data_sources:
            raise ValueError(f"Unsupported configuration type: {config_type}")

        data_source = self.data_sources[config_type]

        if config_type == "local_files":
            try:
                with open(data_source["path"], "r") as file:
                    return Configuration.parse_file(file)
            except FileNotFoundError:
                pass
        elif config_type == "remote_databases":
            try:
                response = requests.get(f"{data_source['host']}:{data_source['port']}/config")
                if response.status_code == 200:
                    return Configuration.parse_json(response.json())
                else:
                    raise ValueError("Failed to retrieve configuration from remote database")
            except Exception as e:
                print(f"Error loading config from remote database: {e}")
        elif config_type == "cloud_storage":
            try:
                response = requests.get(f"https://s3.amazonaws.com/{data_source['bucket_name']}/config.json")
                if response.status_code == 200:
                    return Configuration.parse_json(response.json())
                else:
                    raise ValueError("Failed to retrieve configuration from cloud storage")
            except Exception as e:
                print(f"Error loading config from cloud storage: {e}")

        return Configuration()

    def start(self) -> None:
        for data_source in self.data_sources.values():
            if data_source.get("path"):
                os.makedirs(os.path.dirname(data_source["path"]), exist_ok=True)
