const { spawn } = require('child_process');
const { WorkerPool } = require('worker-pool');
const { Logger } = require('@loglevel/logger');
const { retry } = require('async-retry');

class SystemCommandUtility {
  constructor({
    command,
    environmentVariables,
    workerPoolConfig,
    loggingConfig,
  }) {
    this.command = command;
    this.environmentVariables = environmentVariables;
    this.workerPool = new WorkerPool(workerPoolConfig);
    this.logger = new Logger(loggingConfig);
  }

  async executeCommand() {
    try {
      const { stdout, stderr } = await this.workerPool.exec(this.command, {
        env: this.environmentVariables,
      });

      if (stdout) {
        return stdout.toString();
      }

      if (stderr) {
        throw new Error(stderr.toString());
      }
    } catch (error) {
      await retry(
        async () => {
          // implement retry logic here
        },
        {
          retries: 3, // configurable maximum number of retries
          factor: 2, // exponential backoff strategy
          jitter: true, // randomize the delay between retries
        }
      );

      throw error;
    } finally {
      this.workerPool.terminate();
      this.logger.info('Command execution completed');
    }
  }

  async start() {
    try {
      await this.executeCommand();
    } catch (error) {
      this.logger.error(`Error executing command: ${error.message}`);
    } finally {
      this.logger.info('Utility terminated');
    }
  }
}

module.exports = SystemCommandUtility;
