#include "logging.h"
#include "config.h"

#define PATH_MAX_LENGTH 256
#define TRUNCATION_THRESHOLD 128

char* truncate_path(const char* path, size_t max_length) {
    if (!path || strlen(path) >= max_length) {
        return NULL;
    }

    char* truncated_path = malloc(PATH_MAX_LENGTH);
    if (!truncated_path) {
        logging_error("Failed to allocate memory for truncated path");
        return NULL;
    }

    int length = 0;
    bool in_trailing_dir = false;
    for (int i = strlen(path) - 1; i >= 0; --i) {
        char c = path[i];
        if (c == '/') {
            in_trailing_dir = true;
        } else if (!in_trailing_dir && c != '.') {
            break;
        }
        truncated_path[length++] = c;
    }

    if (length + 1 > max_length - TRUNCATION_THRESHOLD) {
        // Truncate the path to avoid exceeding the maximum length
        char* new_path = malloc(max_length);
        if (!new_path) {
            logging_error("Failed to allocate memory for truncated path");
            free(truncated_path);
            return NULL;
        }
        strncpy(new_path, truncated_path, max_length - 1);
        new_path[max_length - 1] = '\0';
        free(truncated_path);
        return new_path;
    }

    truncated_path[length] = '\0';
    return truncated_path;
}

int main() {
    const char* path = "/Users/john/doctest/file.txt";
    size_t max_length = PATH_MAX_LENGTH;
    char* truncated_path = truncate_path(path, max_length);
    if (truncated_path) {
        printf("%s\n", truncated_path);
        free(truncated_path);
    }
    return 0;
}
