public class ModularLoggingFramework {
    private static final AtomicInteger LOG_LEVELS = new AtomicInteger(0);
    private ConcurrentHashMap<String, String> logConfig = new ConcurrentHashMap<>();
    private ConcurrentHashMap<String, String> aggregatorMap = new ConcurrentHashMap<>();

    public ModularLoggingFramework() {
        this.logConfig.put("INFO", "info");
        this.logConfig.put("DEBUG", "debug");
        this.logConfig.put("ERROR", "error");
        // Add more log levels as needed
    }

    public void log(String message, String level) {
        if (!this.aggregatorMap.containsKey(level)) {
            this.aggregatorMap.put(level, this.configureAggregator());
        }
        try {
            // Send the log message to the configured aggregator
            this.aggregatorMap.get(level).log(message);
        } catch (Exception e) {
            // Handle aggregator failure and log error
            System.out.println("Error logging: " + e.getMessage());
        }
    }

    public void configureAggregator() {
        // Configure external aggregator using HTTP/HTTPS endpoint
        // Implement rate limiting, quota enforcement, and circuit breaker pattern as needed
        return new Aggregator();
    }

