// Define a structure to hold shell command information
typedef struct {
    char* command;
    pthread_t thread_id;
} ShellCommand;

// Define a function to execute shell commands in parallel
void execute_shell_commands(ShellCommand* commands, int num_commands) {
    // Create a pool of threads for parallel execution
    pthreadpool_create(num_commands);

    // Iterate over each shell command and execute it concurrently
    for (int i = 0; i < num_commands; i++) {
        ShellCommand command = commands[i];
        pthread_create(&command.thread_id, NULL, &execute_shell_command, &command);
    }

    // Wait for all threads to complete execution
    pthreadpool_join(num_commands);
}

// Define a function to execute each shell command in parallel
void* execute_shell_command(void* arg) {
    ShellCommand* command = (ShellCommand*)arg;
    system(command->command);
    free(command);
    return NULL;
}

int main() {
    // Initialize an array of shell commands
    ShellCommand* commands = malloc(sizeof(ShellCommand) * 5);
    for (int i = 0; i < 5; i++) {
        commands[i].command = malloc(strlen("ls -l") + strlen("/home/user") + 1);
        sprintf(commands[i].command, "ls -l %s", "/home/user");
    }

    // Execute the shell commands in parallel
    execute_shell_commands(commands, 5);

    return 0;
}
