    private BlockingQueue<String> cache = new LinkedBlockingQueue<>(CACHE_SIZE);

    public void put(String logEntry) {
        try {
            if (cache.size() < CACHE_SIZE) {
                cache.put(logEntry);
            }
        } catch (InterruptedException e) {
