public class DistributedLogger {
    private Map<String, LoggerNode> nodes;
    private LoggerConfig config;

    public DistributedLogger(LoggerConfig config) {
        this.config = config;
        this.nodes = new HashMap<>();
    }

    public void addNode(String nodeId, LoggerNode node) {
        nodes.put(nodeId, node);
    }

    public void log(String message, LogLevel level, long timestamp, Map<String, String> metadata) {
        // Asynchronous logging
        if (config.getAsynchronousLogging()) {
            new Thread(() -> {
                for (String nodeId : nodes.keySet()) {
                    LoggerNode node = nodes.get(nodeId);
                    node.sendLogMessage(message, level, timestamp, metadata);
                }
            }).start();
        } else {
            for (String nodeId : nodes.keySet()) {
                LoggerNode node = nodes.get(nodeId);
                node.sendLogMessage(message, level, timestamp, metadata);
            }
        }
    }

    public interface LoggerNode {
        void sendLogMessage(String message, LogLevel level, long timestamp, Map<String, String> metadata);
    }

    public enum LogLevel {
        DEBUG,
        INFO,
        WARNING,
        ERROR
    }

    public static class LoggerConfig {
        private boolean asynchronousLogging;
        private int logLevel;

        // getters and setters
    }
}
