#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <pthread.h>

#define MAX_TASKS 1000
#define MAX_COMMAND_LENGTH 1024

typedef struct {
    int id;
    char* command;
} Task;

void* execute_task(void* task) {
    Task* t = (Task*)task;
    printf("Executing task %d: %s\n", t->id, t->command);
    // Execute the command
    system(t->command);
    return NULL;
}

int main() {
    int num_tasks = 0;
    char commands[MAX_TASKS][MAX_COMMAND_LENGTH];

    // Initialize tasks array
    for (int i = 0; i < MAX_TASKS; i++) {
        commands[i][0] = '\0';
    }

    // Read commands from file or user input
    FILE* file = fopen("commands.txt", "r");
    if (file == NULL) {
        printf("Error opening file\n");
        return 1;
    }
    while (!feof(file)) {
        fgets(commands[num_tasks], MAX_COMMAND_LENGTH, file);
        num_tasks++;
    }
    fclose(file);

    // Create threads to execute tasks
    pthread_t threads[MAX_TASKS];
    Task tasks[MAX_TASKS];

    for (int i = 0; i < num_tasks; i++) {
        tasks[i].id = i;
        strcpy(tasks[i].command, commands[i]);
        pthread_create(&threads[i], NULL, execute_task, &tasks[i]);
    }

    // Wait for threads to finish
    for (int i = 0; i < num_tasks; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
