// API Gateway Code Block

import (
	"context"
	"fmt"
	"net/http"
	"time"

	"github.com/aws/aws-lambda-go/lambda"
	"github.com/go-chi/chi/v5"
	"github.com/go-chi/middleware/realip"
	"github.com/grpc-ecosystem/grpc-gateway/runtime"
	"google.golang.org/grpc/codes"
)

func main() {
	lambda.Start(apiGatewayHandler)
}

func apiGatewayHandler(ctx context.Context) {
	r := chi.NewRouter()
	r.Use(realip.RealIP())

	mux := runtime.NewServeMux()
	RegisterService(mux)

	r.Route("/v1", func(r chi.Router) {
		r.Use(HeaderCheck())
		r.Use(Cors())
		r.Get("/users/{username}", GetUserHandler)
	})

	http.ListenAndServe(":8080", r)
}

func RegisterService(m *runtime.ServeMux) {
	// Register gRPC services
	lambda.RegisterService(&lambda.Service{
		Name: "my-service",
		Version: "v1",
	}, m)
}

func HeaderCheck(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Header.Get("X-Forwarded-For") == "" {
			http.Error(w, "Invalid request", 400)
			return
		}
		next.ServeHTTP(w, r)
	})
}

func Cors(next http.Handler) http.Handler {
	return cors.New(cors.Options{
		AllowedOrigins: []string{"*"},
	}).Handler(next)
}

func GetUserHandler(w http.ResponseWriter, r *http.Request) {
	// Retrieve user data from database or service
	if _, ok := users.Load(chi.URLParam(r, "username")); !ok {
		http.Error(w, "User not found", 404)
		return
	}
	w.Write([]byte("Hello, " + chi.URLParam(r, "username")))
}

func mainAPI() {
	// Start API Gateway
}

type apiGateway struct{}

func (a *apiGateway) Handle(ctx context.Context, req *http.Request, resp http.ResponseWriter) {
	// Route request to appropriate backend service
	if req.Method == "GET" && req.URL.Path == "/v1/users/{username}" {
		GetUserHandler(resp, req)
		return
	}
	http.Error(resp, "Invalid request", 400)
}

func main() {
	a := &apiGateway{}
	lambda.Start(func(ctx context.Context) {
		a.Handle(ctx, lambda.Request{}, nil)
	})
}

