import http.server
import socketserver
import json
import logging

class RequestRouter:
    def __init__(self):
        self.microservices = {}
        self.config_cache = {}

    def route_request(self, request):
        headers = dict(request.headers)
        query_params = dict(request.query_string.split('&'))
        auth_token = None if 'Authorization' not in headers else headers['Authorization']

        # Determine the microservice to route to based on headers and query params
        for microservice_name, routing_config in self.microservices.items():
            if all(key in headers.values() or key in query_params.values() for key in routing_config['headers']):
                return f"{microservice_name} - {routing_config.get('path', '')}"

        # If no matching microservice found, default to a generic error page
        return "Error: No matching microservice found"

    def handle_request(self, request):
        response = http.server.BaseHTTPRequestHandler().handle_request(request)

        if not response:
            response = self.route_request(request)
            if isinstance(response, dict):
                response = json.dumps(response)
        elif isinstance(response, bytes):
            response = response.decode('utf-8')

        return f"HTTP/1.1 {response.status_code} {response.reason}\n\n{response.read().decode('utf-8')}"

