// Function to truncate file path
char* truncate_path(const char* filepath, int length) {
    if (!filepath || strlen(filepath) > length) {
        return NULL;
    }

    // Truncate the path
    char* truncated = malloc(length + 1);
    strncpy(truncated, filepath, length);
    truncated[length] = '\0';

    return truncated;
}

// Function to log truncation events
void log_truncation(const char* filepath) {
    printf("Truncated file path: %s\n", filepath);
}

int main() {
    const char* filepath = "/home/user/documents/long/path/to/file.txt";
    int length = 20;

    char* truncated_path = truncate_path(filepath, length);

    if (truncated_path) {
        log_truncation(truncated_path);
        free(truncated_path);
    }

