// Function to initialize the Component Manager and create a new list
ComponentManager *init_component_manager() {
    ComponentManager *manager = (ComponentManager *)malloc(sizeof(ComponentManager));
    manager->components = NULL;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

// Function to add a new component to the list
void add_component(ComponentManager *manager, Component component) {
    Node *new_node = (Node *)malloc(sizeof(Node));
    new_node->component = component;
    new_node->next = manager->components;
    pthread_mutex_lock(&manager->lock);
    if (!manager->components) {
        manager->components = new_node;
    } else {
        Node *current = manager->components;
        while (current->next) {
            current = current->next;
        }
        current->next = new_node;
    }
    pthread_mutex_unlock(&manager->lock);
}

// Function to retrieve a component by name
Component *get_component_by_name(ComponentManager *manager, char *name) {
    Node *node = manager->components;
    while (node) {
        if (!strcmp(node->component.name, name)) {
            return &node->component;
        }
        node = node->next;
    }
    return NULL;
}

