import java.util.concurrent.BlockingQueue;
import java.util.concurrent.LinkedBlockingQueue;

public class DistributedProcessor {

    private static final int NUM_THREADS = Runtime.getRuntime().availableProcessors();
    private static final BlockingQueue<Runnable> queue = new LinkedBlockingQueue<>();

    public void startProcessing() {
        for (int i = 0; i < NUM_THREADS; i++) {
            Thread thread = new Thread(new Processor(queue));
            thread.start();
        }
    }

    public void stopProcessing() {
        // Stop threads
        for (Thread thread : Thread.currentThread().getThreads())
            thread.stop();
    }

    private static class Processor implements Runnable {

        private final BlockingQueue<Runnable> queue;

        public Processor(BlockingQueue<Runnable> queue) {
            this.queue = queue;
        }

        @Override
        public void run() {
            while (true) {
                try {
                    Runnable task = queue.take();
                    task.run();
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    return;
                }
            }
        }
    }

    public static void main(String[] args) {
        // Start processing
        new DistributedProcessor().startProcessing();

        // Stop processing
        //new DistributedProcessor().stopProcessing();
    }
}
