class RandomNumberGenerator {
public:
    static const int SEED = 123456789;
    static std::atomic<int> seed(SEED);
    static std::atomic<bool> initialized(false);

    template<typename T>
    static void setSeed(const T& value) {
        seed.store(value);
    }

    template<typename T>
    static T getSeed() const {
        return seed.load();
    }

    template<typename T>
    static void initialize() {
        if (!initialized.exchange(true)) {
            std::random_device rd;
            std::mt19937 generator(rd());
            setSeed(generator());
        }
    }

    static double uniformRandom(double min, double max) {
        std::uniform_real_distribution<double> distribution(min, max);
        return distribution(getSeed());
    }

    static double normalRandom(double mean = 0.0, double stdev = 1.0) {
        std::normal_distribution<double> distribution(mean, stdev);
        return distribution(getSeed());
    }

    static double exponentialRandom(double rate) {
        std::exponential_distribution<double> distribution(rate);
        return distribution(getSeed());
    }
};

class RandomNumberService {
public:
    RandomNumberService() : generator_(0.0) {}

    void setDistribution(const std::string& dist, const double param1 = 0.0, const double param2 = 0.0) {
        if (dist == "uniform") {
            uniformMin_ = param1;
            uniformMax_ = param2;
        } else if (dist == "normal") {
            normalMean_ = param1;
            normalStdev_ = param2;
        } else if (dist == "exponential") {
            exponentialRate_ = param1;
        }
    }

    double generateRandomNumber() {
        RandomNumberGenerator::initialize();

        std::unique_lock<std::mutex> lock(mutex_);
        switch (distribution_) {
            case "uniform":
                return RandomNumberGenerator::uniformRandom(uniformMin_, uniformMax_);
            case "normal":
                return RandomNumberGenerator::normalRandom(normalMean_, normalStdev_);
            case "exponential":
                return RandomNumberGenerator::exponentialRandom(exponentialRate_);
        }
    }

private:
    std::string distribution_;
    double uniformMin_;
    double uniformMax_;
    double normalMean_;
    double normalStdev_;
    double exponentialRate_;

    std::mutex mutex_;
};

int main() {
    // Usage example
    RandomNumberService rng;
    rng.setDistribution("uniform", 0.0, 1.0);
    for (int i = 0; i < 10; ++i) {
        std::cout << "Random number: " << rng.generateRandomNumber() << std::endl;
    }
}

