<?php

declare(strict_types=1);

namespace MyApp\Services\Account;

use GuzzleHttp\Client;
use GuzzleHttp\Psr7\Request;
use Illuminate\Support\Facades\Log;
use Illuminate\Database\QueryException;

class AccountService {
    private $cache;
    private $client;
    private $retryCounter = 0;

    public function __construct(CacheInterface $cache, Client $httpClient) {
        $this->cache = $cache;
        $this->client = $httpClient;
    }

    public function createAccount(array $data): array {
        try {
            // Handle concurrent operations with minimal latency
            $accountData = $this->cache->get('accounts', 'create_account');
            if ($accountData) {
                return ['message' => 'success', 'status_code' => 200, 'details' => $accountData];
            }

            // Asynchronous request to create account
            $request = new Request('POST', 'https://idp.com/create-account', [
                'Content-Type' => 'application/json',
                'Authorization' => 'Bearer ' . $this->getAccessToken(),
            ]);
            $response = $this->client->send($request, ['json' => json_encode($data)]);
            $responseBody = json_decode($response->getBody()->__toString(), true);

            // Store created account in cache
            $this->cache->put('accounts', 'create_account', $responseBody);

            return ['message' => 'success', 'status_code' => 201, 'details' => $responseBody];
        } catch (QueryException | GuzzleHttp\Exception\RequestException $e) {
            // Handle errors and retries
            if ($this->retryCounter < 3) {
                sleep(1);
                return $this->createAccount($data);
            }

            return ['message' => 'error', 'status_code' => 500, 'details' => $e->getMessage()];
        }
    }

    public function updateAccount(array $data): array {
        try {
            // Partial updates
            $partialUpdate = array_filter($data, fn ($field) => !empty($field));

            if (count($partialUpdate)) {
                // Asynchronous request to update account
                $request = new Request('PUT', 'https://idp.com/update-account', [
                    'Content-Type' => 'application/json',
                    'Authorization' => 'Bearer ' . $this->getAccessToken(),
                ]);
                $response = $this->client->send($request, ['json' => json_encode($partialUpdate)]);
                $responseBody = json_decode($response->getBody()->__toString(), true);

                return ['message' => 'success', 'status_code' => 200, 'details' => $responseBody];
            }

            // Handle errors
            return ['message' => 'error', 'status_code' => 400, 'details' => 'Invalid request'];
        } catch (QueryException | GuzzleHttp\Exception\RequestException $e) {
            // Handle errors and retries
            if ($this->retryCounter < 3) {
                sleep(1);
                return $this->updateAccount($data);
            }

            return ['message' => 'error', 'status_code' => 500, 'details' => $e->getMessage()];
        }
    }

    public function deleteAccount(string $accountId): array {
        try {
            // Asynchronous request to delete account
            $request = new Request('DELETE', 'https://idp.com/delete-account/' . $accountId, [
                'Content-Type' => 'application/json',
                'Authorization' => 'Bearer ' . $this->getAccessToken(),
            ]);
            $response = $this->client->send($request);
            $responseBody = json_decode($response->getBody()->__toString(), true);

            return ['message' => 'success', 'status_code' => 200, 'details' => $responseBody];
        } catch (QueryException | GuzzleHttp\Exception\RequestException $e) {
            // Handle errors and retries
            if ($this->retryCounter < 3) {
                sleep(1);
                return $this->deleteAccount($accountId);
            }

            return ['message' => 'error', 'status_code' => 500, 'details' => $e->getMessage()];
        }
    }

    private function getAccessToken(): string {
        // Get access token from cache or IdP
        // ...
    }
}

interface CacheInterface {
    public function get(string $key): array;
    public function put(string $key, string $value): void;
}
