```javascript
const express = require('express');
const app = express();
const { Kafka } = require('kafkajs');
const { LogParser } = require('./log-parser');
const { AnalyticsService } = require('./analytics-service');

// Configure Kafka client and subscribe to log topic
const kafka = new Kafka({
  clientId: 'log-aggregator',
  brokers: ['localhost:9092'],
});
const consumer = kafka.consumer({ groupId: 'log-group' });
consumer.subscribe({ topic: 'logs', fromBeginning: true });

// Parse logs and aggregate events
app.use((req, res, next) => {
  const logBuffer = [];
  consumer.on('message', (msg) => {
    logBuffer.push(msg.value.toString());
    if (logBuffer.length >= 10000) {
      // Process aggregated logs
      processLogs(logBuffer);
      logBuffer.length = 0;
    }
  });
  next();
});

// Handle analytics service submission and retries
app.post('/analytics', async (req, res) => {
  try {
    await AnalyticsService.submit(req.body);
  } catch (error) {
    // Retry logic for transient errors
    setTimeout(() => AnalyticsService.submit(req.body), 5000);
  }
  res.send({ status: 'ok' });
});

// Start the microservice
app.listen(3000, () => {
  console.log('Log Aggregator listening on port 3000');
});
```

