use std::fs;
use std::process;

fn compile_and_measure_crate(crate_name: &str) -> Result<(), String> {
    let crate_dir = format!("target/{}/debug", crate_name);
    fs::create_dir_all(&crate_dir).unwrap();
    println!("Compiling {}...", crate_name);

    // Compile the Rust crate
    process::Command::new("rustc")
        .arg(format!("--out={}/{}", crate_dir, crate_name))
        .arg("-O")
        .arg(crate_name)
        .output()
        .map_err(|e| format!("Error compiling {}: {}", crate_name, e))?;

    // Measure compilation time
    let start_time = std::time::Instant::now();
    fs::read_dir(&crate_dir).unwrap().next().map_or(Ok(()), |_| {
        process::Command::new("rust-lint")
            .arg(crate_dir)
            .output()
            .map_err(|e| format!("Error running rust-lint: {}", e))?;
        Ok(())
    })?;

    let end_time = std::time::Instant::now();
    println!("Compilation time for {}: {} seconds", crate_name, (end_time - start_time).as_secs_f32());

    // Calculate memory usage
    let mem_usage = fs::metadata(&crate_dir)
        .unwrap()
        .len() as f64 / 1024.0;
    println!("Memory usage for {}: {:.2} MB", crate_name, mem_usage);

    Ok(())
}

fn main() {
    if let Err(err) = compile_and_measure_crate("my_crate") {
        eprintln!("{}", err);
        process::exit(1);
    }
}
