  this.refreshDialogFields = function (resourceId, url) {
    // Initialize variables and object
    var dialogFields = [];
    var oldTestamentBooks = [];

    // Call RESTful API to retrieve list of dialog fields
    return $http.get('api/dialog-fields/' + resourceId)
      .then(function (response) {
        dialogFields = response.data;

        // Iterate over the list of dialog fields and check if their names match specified field names to refresh
        angular.forEach(dialogFields, function (field) {
          var fieldMatches = false;
          for (var i = 0; i < arguments.length; i++) {
            if (field.name === arguments[i]) {
              fieldMatches = true;
              break;
            }
          }
          if (fieldMatches) {
            // Send a message to the parent window
            $window.parent.postMessage('refreshField', '*');
          }
        });
      })
      .catch(function (error) {
        console.error('Error while refreshing dialog fields:', error);
      });

    this.updateDialogField = function (resourceId, url, response) {
      // Process text data received from the parent window
      var messageText = response.message;
      var regexOldTestamentBooks = /(\b(Exodus|Leviticus|Numbers|Deuteronomy|Joshua|Judges|Ruth|1 Samuel|2 Samuel|1 Kings|2 Kings|1 Chronicles|2 Chronicles|Ezra|Nehemiah|Esther|Job|Psalms|Proverbs|Ecclesiastes|Song of Solomon|Isaiah|Jeremiah|Lamentations|Ezekiel|Daniel|Hosea|Joel|Amos|Obadiah|Jonah|Micah|Nahum|Habakkuk|Zephaniah|Haggai|Zechariah|Malachi)\b)/g;
      var match = regexOldTestamentBooks.exec(messageText);
      while (match) {
        var bookName = match[1];
        if (!oldTestamentBooks.includes(bookName)) {
          oldTestamentBooks.push({ name: bookName, frequency: 0 });
        }
        oldTestamentBooks.forEach(function (book) {
          if (book.name === bookName) {
            book.frequency++;
          }
        });
        match = regexOldTestamentBooks.exec(messageText);
      }

      // Return an object containing the names of Old Testament books found in the text, along with their frequency counts
      return { oldTestamentBooks: oldTestamentBooks };
    };

  };
}]);

