int start_server(int);
int validate_data(char*, int);

int main() {
    // Initialize the configuration file
    config_t config = {8080, "localhost", 1024};

    // Initialize the worker thread pool
    int num_threads = 5;
    pthread_t* threads = (pthread_t*)malloc(num_threads * sizeof(pthread_t));

    // Start each worker thread
    for(int i = 0; i < num_threads; i++) {
        int socket_fd = start_server(config.port);
        worker_thread_t* thread = (worker_thread_t*)malloc(sizeof(worker_thread_t));
        thread->socket_fd = socket_fd;
        pthread_create(&thread->thread_id, NULL, start_worker, thread);
    }

    // Wait for each worker thread to finish
    for(int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
        free(threads[i]);
    }

    return 0;
}

