package main

import (
	"fmt"
	"net/http"
)

func StartWebSocketConnection(url string) {
	conn, err := websocket.Dial(url)
	if err != nil {
		fmt.Println(err)
		return
	}
	defer conn.Close()

	for {
		_, message, err := conn.ReadMessage()
		if err != nil {
			fmt.Println(err)
			return
		}
		if message.Type() == websocket.CloseMessage {
			break
		}
		// Process the received message
	}

}

func SendHttpGetRequest(url string) (int, []byte, error) {
	req, err := http.NewRequest("GET", url, nil)
	if err != nil {
		return 0, nil, err
	}
	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		return 0, nil, err
	}
	defer resp.Body.Close()
	return resp.StatusCode, ioutil.ReadAll(resp.Body), nil
}

func SendHttpPostRequest(url string, data []byte) (int, []byte, error) {
	req, err := http.NewRequest("POST", url, bytes.NewBuffer(data))
	if err != nil {
		return 0, nil, err
	}
	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		return 0, nil, err
	}
	defer resp.Body.Close()
	return resp.StatusCode, ioutil.ReadAll(resp.Body), nil
}
