namespace EncryptedMessagingLib
{
    public enum CipherAlgorithm { TripleDES }

    public static class EncryptionHelper
    {
        private const string KeyRotationInterval = "1 hour"; // default interval

        public static byte[] Encrypt(string message, CipherAlgorithm algorithm, string key, string iv)
        {
            using (var des = CreateDes(algorithm, key, iv))
            {
                return Encrypt(des, Encoding.UTF8.GetBytes(message));
            }
        }

        public static string Decrypt(byte[] encryptedData, CipherAlgorithm algorithm, string key, string iv)
        {
            using (var des = CreateDes(algorithm, key, iv))
            {
                return Encoding.UTF8.GetString(Decrypt(des, encryptedData));
            }
        }

        private static TripleDESCryptoServiceProvider CreateDes(CipherAlgorithm algorithm, string key, string iv)
        {
            var des = new TripleDESCryptoServiceProvider
            {
                Key = Convert.FromBase64String(key),
                IV = Convert.FromBase64String(iv)
            };
            return des;
        }

        private static byte[] Encrypt(TripleDESCryptoServiceProvider des, byte[] data)
        {
            using (var ms = new MemoryStream())
            {
                using (var cs = new CryptoStream(ms, des.CreateEncryptor(), CryptoStreamMode.Write))
                {
                    cs.Write(data, 0, data.Length);
                }
                return ms.ToArray();
            }
        }

        private static byte[] Decrypt(TripleDESCryptoServiceProvider des, byte[] data)
        {
            using (var ms = new MemoryStream(data))
            {
                using (var cs = new CryptoStream(ms, des.CreateDecryptor(), CryptoStreamMode.Read))
                {
                    var decryptedData = new byte[ms.Length];
                    cs.Read(decryptedData, 0, decryptedData.Length);
                    return decryptedData;
                }
            }
        }

        public static void LogDecryptionAttempt(string message, bool success)
        {
            // integrate with existing logging framework to record logs
        }
    }
}
