        private readonly IPasswordHasher _passwordHasher;
        private readonly ILogger _logger;

        public UserService(IIdentityProvider identityProvider, IPasswortHasher passwordHasher, ILogger logger)
        {
            _identityProvider = identityProvider;
            _passwordHasher = passwordHasher;
            _logger = logger;
        }

        public async Task<string> AuthenticateAsync(string username, string password)
        {
            try
            {
                var user = await _identityProvider.GetUserAsync(username);
                if (user == null) return "User not found";

                var storedPasswordHash = user.PasswordHash;

                using (var sha256 = SHA256.Create())
                {
                    var saltedPassword = _passwordHasher.GetSaltedPassword(password, user.Salt);
                    var passwordHash = Convert.ToBase64String(sha256.ComputeHash(saltedPassword));
                    if (!storedPasswordHash.Equals(passwordHash))
                        return "Invalid password";
                }

                return "Login successful";
            }
            catch (Exception ex)
            {
                _logger.LogError(ex);
                return "Authentication failed";
            }
        }

        public async Task<string> AuthorizeAsync(string username, string scope)
        {
            try
