    private readonly ILogger<AescbcDecryptor> _logger;
    private readonly int _keySize;
    private readonly string _ivAlgorithm;
    private readonly int _blockSize;
    private readonly string _padding;

    public AescbcDecryptor(int keySize, string ivAlgorithm, int blockSize, string padding)
    {
        _keySize = keySize;
        _ivAlgorithm = ivAlgorithm;
        _blockSize = blockSize;
        _padding = padding;
        _logger = logger;
    }

    public byte[] Decrypt(byte[] ciphertext, byte[] key, byte[] iv)
    {
        using var aes = Aes.Create();
        aes.Key = key;
        aes.IV = iv;

        using var decryptor = aes.CreateDecryptor();

        using var ms = new MemoryStream(ciphertext);
        using var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read);

        byte[] decryptedBytes = new byte[ciphertext.Length];
        int bytesRead = cs.Read(decryptedBytes, 0, decryptedBytes.Length);

        _logger.LogInformation("Decrypted {Length} bytes", bytesRead);
        return decryptedBytes;
    }
