// ConfigurationManager.cs
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Net.Http;
using System.Threading.Tasks;

public class ConfigurationManager 
{
    private readonly Dictionary<string, ConfigSource> _configSources = new();
    private readonly HttpClient _httpClient;

    public ConfigurationManager(HttpClient httpClient) 
    {
        _httpClient = httpClient;
        InitializeConfigSources();
    }

    public async Task<Dictionary<string, object>> GetConfigurationAsync(string serviceId)
    {
        var config = await RetrieveConfigAsync(serviceId);
        if (config == null) 
            throw new Exception("Invalid configuration");

        return config;
    }

    private async Task<Dictionary<string, object>> RetrieveConfigAsync(string serviceId)
    {
        // Check cache for existing config
        if (_configSources.TryGetValue(serviceId, out var cachedConfig)) 
            return cachedConfig;

        // Fetch config from primary source (e.g., local file)
        var primarySource = _configSources[serviceId];
        var primaryConfig = await primarySource.GetConfigurationAsync();

        // Handle version mismatches and incompatible APIs
        if (!primaryConfig.IsCompatible()) 
            throw new Exception("Incompatible configuration");

        // Fetch additional config from secondary sources (e.g., remote databases, cloud storage)
        foreach (var source in _configSources.Where(s => s.Key != serviceId)) 
        {
            var secondaryConfig = await source.Value.GetConfigurationAsync();
            primaryConfig.Merge(secondaryConfig);
        }

        // Cache retrieved config for future use
        cachedConfig = primaryConfig;
        _configSources[serviceId] = new ConfigSource(primaryConfig);

        return primaryConfig;
    }

    private void InitializeConfigSources() 
    {
        // Register local file, remote database, and cloud storage sources
        _configSources.Add("local", new LocalFileConfigSource());
        _configSources.Add("remote", new RemoteDatabaseConfigSource(_httpClient));
        _configSources.Add("cloud", new CloudStorageConfigSource());
    }
}

// ConfigSource.cs
