  } catch (error) {
    console.error(error);
    res.status(500).send({ message: error.message });
  }
}

app.use(express.json());
app.post('/update-template', main);

// Start the microservice
const port = process.env.PORT || 3000;
app.listen(port, () => console.log(`Microservice started on port ${port}`));
