from typing import Dict, List

class DynamicJSONHandler:
    def __init__(self):
        self._redis_client = redis.Redis()
        self._schema_cache = {}

    def get_schema(self, schema_id: str) -> Dict:
        if not self._schema_cache.get(schema_id):
            response = requests.get(f'https://api.example.com/schemas/{schema_id}')
            if response.status_code == 200:
                self._store_schema(schema_id, response.json())
            else:
                raise Exception(f"Failed to retrieve schema {schema_id} with status code {response.status_code}")

        return self._schema_cache[schema_id]

    def _store_schema(self, schema_id: str, schema_data: Dict):
        self._redis_client.setex(schema_id, 3600, json.dumps(schema_data))
        self._schema_cache[schema_id] = schema_data

    def generate_random_string(self, length: int, character_set: str) -> str:
        return ''.join(random.choice(character_set) for _ in range(length))

    def hash_password(self, password: str) -> str:
        return hashlib.sha256(password.encode()).hexdigest()

    def validate_json(self, json_data: Dict) -> bool:
        schema_id = json_data.get('schemaId')
        if not schema_id:
            raise Exception("Invalid JSON data")

        try:
            self.get_schema(schema_id)
            return True
        except Exception as e:
            print(f"Error validating JSON: {str(e)}")
