#include <iostream>
#include <vector>
#include <unordered_map>

int countDisjointPairs(const std::vector<int>& arr) {
    int n = arr.size();
    std::vector<int> parent(n);
    for (int i = 0; i < n; ++i) {
        parent[i] = i;
    }

    int disjointCount = 0;
    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            if (find(parent, arr[i]) != find(parent, arr[j])) {
                // Perform union operation
                parent[find(parent, arr[j])] = parent[arr[i]];
                disjointCount++;
            }
        }
    }

    return disjointCount;
}

int find(const std::vector<int>& parent, int x) {
    if (parent[x] != x) {
        parent[x] = find(parent, parent[x]);
    }
    return parent[x];
}

int main() {
    // Example usage
    std::vector<int> arr = {1, 2, 3, 4, 5};
    int disjointCount = countDisjointPairs(arr);
    std::cout << "Number of disjoint pairs: " << disjointCount << "\n";
    return 0;
}
