#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>

#define MAX_THREADS 50
#define MAX_COMMANDS 1000

typedef struct {
    char* command;
    int priority;
} Command;

typedef struct {
    pthread_mutex_t lock;
    int commands_left;
    pthread_cond_t cond;
} ThreadData;

void* thread_func(void* arg) {
    ThreadData* data = (ThreadData*)arg;
    while (data->commands_left > 0) {
        pthread_mutex_lock(&data->lock);
        if (data->commands_left <= 0) {
            pthread_cond_signal(&data->cond);
            break;
        }
        Command* cmd = data->commands[data->commands_left - 1];
        printf("Thread %d executing command: %s\n", pthread_self(), cmd->command);
        // Execute the command here
        free(cmd);
        data->commands_left--;
        pthread_mutex_unlock(&data->lock);
    }
    pthread_cond_signal(&data->cond);
    return NULL;
}

int main() {
    pthread_t threads[MAX_THREADS];
    ThreadData data;
    pthread_mutex_init(&data.lock, NULL);
    pthread_cond_init(&data.cond, NULL);

    Command commands[MAX_COMMANDS];

    for (int i = 0; i < MAX_COMMANDS; i++) {
        commands[i].command = malloc(1024);
        sprintf(commands[i].command, "Command %d", i);
        commands[i].priority = i;
    }

    data.commands_left = MAX_COMMANDS;

    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_create(&threads[i], NULL, thread_func, &data);
    }

    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
