#include <string.h>

char* truncate_path(const char* path, int max_len) {
    if (!path || strlen(path) > max_len) return NULL;

    int len = strlen(path);
    char* truncated_path = (char*)malloc((max_len + 1) * sizeof(char));
    strncpy(truncated_path, path, min(len, max_len - 1));
    truncated_path[max_len] = '\0';

    // Log truncation event
    FILE* log_file = fopen("/path/to/log/file.log", "a");
    fprintf(log_file, "Path '%s' truncated to '%s'\n", path, truncated_path);
    fclose(log_file);

    return truncated_path;
}

