    stats->rx_packets = 0;
    stats->tx_packets = 0;
    stats->rx_bytes = 0;
    stats->tx_bytes = 0;
}

// Update the statistics for a network interface
void update_stats(NetworkInterfaceStats* stats, char* ifname, int rx_packets, int tx_packets, int rx_bytes, int tx_bytes) {
    strcpy(stats->ifname, ifname);
    stats->rx_packets += rx_packets;
    stats->tx_packets += tx_packets;
    stats->rx_bytes += rx_bytes;
    stats->tx_bytes += tx_bytes;
}

// Print the statistics for a network interface
void print_stats(NetworkInterfaceStats* stats) {
    printf("Interface: %s\n", stats->ifname);
    printf("RX Packets: %d\n", stats->rx_packets);
    printf("TX Packets: %d\n", stats->tx_packets);
    printf("RX Bytes: %d\n", stats->rx_bytes);
    printf("TX Bytes: %d\n", stats->tx_bytes);
}

// Thread-safe lock for concurrent access
pthread_mutex_t stats_lock = PTHREAD_MUTEX_INITIALIZER;

// Mutex for updating statistics
void update_stats_locked(NetworkInterfaceStats* stats, char* ifname, int rx_packets, int tx_packets, int rx_bytes, int tx_bytes) {
    pthread_mutex_lock(&stats_lock);
    update_stats(stats, ifname, rx_packets, tx_packets, rx_bytes, tx_bytes);
    pthread_mutex_unlock(&stats_lock);
}

