public class DistributedLogger {
    private static final String DEFAULT_LOGGER = "default_logger";
    private static final int MAX_LOGGERS = 5;

    private static ConcurrentMap<String, Logger> loggers = new ConcurrentHashMap<>();
    private static List<String> configuredLoggers = new ArrayList<>();
    private static boolean cloudLoggingEnabled = false;

    public void addLogger(String loggerName) {
        if (!loggers.containsKey(loggerName)) {
            loggers.putIfAbsent(loggerName, new Logger());
        }
    }

    public void removeLogger(String loggerName) {
        if (loggers.containsKey(loggerName)) {
            loggers.remove(loggerName);
        }
    }

    public void configureLogger(String loggerName, boolean enabled) {
        configuredLoggers.add(loggerName);
    }

    public void enableCloudLogging() {
        cloudLoggingEnabled = true;
    }

    public void disableCloudLogging() {
        cloudLoggingEnabled = false;
    }

    public void log(String message) {
        for (String logger : configuredLoggers) {
            Logger l = loggers.get(logger);
            if (l != null && l.isEnabled()) {
                l.log(message);
            }
        }
        if (cloudLoggingEnabled) {
