        timestamp(timestamp), eventType(eventType) {}

    // copy constructor for deep copy
    NetworkEventRecord(const NetworkEventRecord& other) : 
        timestamp(other.timestamp), eventType(other.eventType) {
            metadata = other.metadata;
        }
};

class EventManager {
public:
    static const int MAX_RECORDS_PER_BATCH = 1000;

    void addEvent(const NetworkEventRecord& record);
    bool removeOldEvents(int retentionPeriod);

    // internal caching mechanism
    class Cache {
    public:
        std::mutex mutex;
        std::vector<NetworkEventRecord> cacheRecords;

        void clearCache() {
            std::lock_guard<std::mutex> lock(mutex);
            cacheRecords.clear();
        }

        bool contains(const NetworkEventRecord& record) {
            std::lock_guard<std::mutex> lock(mutex);
            for (const auto& cachedRecord : cacheRecords) {
                if (record.timestamp == cachedRecord.timestamp &&
                    record.eventType == cachedRecord.eventType &&
                    record.metadata == cachedRecord.metadata)
                    return true;
            }
            return false;
        }

        void put(const NetworkEventRecord& record) {
            std::lock_guard<std::mutex> lock(mutex);
            cacheRecords.push_back(record);
        }
    };

private:
    Cache cache;
};

