class NetworkEventRecord {
public:
    int timestamp;
    int eventType;
    std::string metadata;

    // Constructor
    NetworkEventRecord(int timestamp, int eventType, const std::string& metadata) 
        : timestamp(timestamp), eventType(eventType), metadata(metadata) {}
};

// Event management system
class EventManagementSystem {
private:
    std::vector<NetworkEventRecord> events;
    std::mutex mutex;
    std::condition_variable condition;
    bool isRunning = true;

public:
    // Add event to the queue
    void addEvent(int timestamp, int eventType, const std::string& metadata) {
        std::unique_lock<std::mutex> lock(mutex);
        events.emplace_back(timestamp, eventType, metadata);
        lock.unlock();
        condition.notify_one();
    }

    // Process events in a separate thread
    void processEvents() {
        while (isRunning) {
            std::this_thread::sleep_for(std::chrono::milliseconds(10));
            std::unique_lock<std::mutex> lock(mutex);
            if (!events.empty()) {
                NetworkEventRecord event = events.front();
                events.pop_back();
                // Process the event
                processEvent(event);
            }
        }
    }

    // Process an event in a separate thread
    void processEvent(NetworkEventRecord event) {
        // Simulate processing time
        std::this_thread::sleep_for(std::chrono::milliseconds(50));
        // Send processed event to real-time event processing engine
        sendToEngine(event);
    }

    // Simulated method for sending events to the real-time event processing engine
    void sendToEngine(NetworkEventRecord event) {
        // Simulate API call
        std::this_thread::sleep_for(std::chrono::milliseconds(20));
        // Send event to engine
        std::cout << "Sending event " << event.timestamp << " to engine" << std::endl;
    }

    // Start the event processing thread
    void start() {
        std::thread thread(&EventManagementSystem::processEvents, this);
        thread.detach();
    }

    // Stop the event processing thread
    void stop() {
        isRunning = false;
    }
};

// Real-time event processing engine
class EventProcessingEngine {
public:
    void processEvent(NetworkEventRecord event) {
        // Simulate processing time
        std::this_thread::sleep_for(std::chrono::milliseconds(50));
        // Process the event
        std::cout << "Processed event " << event.timestamp << std::endl;
    }
};

int main() {
    EventManagementSystem eventManager;
    EventProcessingEngine engine;

    eventManager.start();

    for (int i = 0; i < 10; ++i) {
        eventManager.addEvent(i, 1, "Metadata");
    }

    eventManager.stop();

    return 0;
}
