import asyncio
from aiohttp import web, ClientSession
import json
import logging
import os
import redis
import time

logging.basicConfig(level=logging.INFO)

class LoadBalancer:
    def __init__(self):
        self.redis = redis.Redis(host='localhost', port=6379, db=0)
        self.services = {}
        self.throttles = {}

    async def handle_request(self, request):
        service_name = request.match_info.get('service')
        if not service_name:
            return web.HTTPBadRequest(text='Invalid Service')

        # Get the available services and their corresponding weights
        available_services = await self.redis.hvals('services')
        service_weights = await self.redis.hgetall('weights')

        # Calculate the load distribution for each service
        total_weight = sum(service_weights.values())
        load_distribution = {service: weight / total_weight for service, weight in service_weights.items()}

        # Select a random service based on the load distribution
        selected_service = random.choice(list(load_distribution.keys()))
        logging.info(f'Selected Service: {selected_service}')

        # Create a client session to communicate with the selected service
        async with ClientSession() as session:
            try:
                # Send the request to the selected service
                start_time = time.time()
                response = await session.request('GET', f'{selected_service}/{request.path_info}')
                end_time = time.time()

                # Log the request and response times
                logging.info(f'Request Time: {end_time - start_time} seconds')

                return web.Response(status=200, text='Service Request Successful')

            except asyncio.TimeoutError:
                # Handle timeout errors by retrying with a different service
                try:
                    selected_service = random.choice(list(load_distribution.keys()))
                    response = await session.request('GET', f'{selected_service}/{request.path_info}')
                    return web.Response(status=200, text='Service Request Successful')
                except asyncio.TimeoutError:
                    # Handle maximum retries exceeded error
                    return web.HTTPInternalServerError(text='Maximum Retries Exceeded')

            except Exception as e:
                # Handle any other exceptions by retrying with a different service
                try:
                    selected_service = random.choice(list(load_distribution.keys()))
                    response = await session.request('GET', f'{selected_service}/{request.path_info}')
                    return web.Response(status=200, text='Service Request Successful')
                except Exception as e:
                    # Handle maximum retries exceeded error
                    return web.HTTPInternalServerError(text='Maximum Retries Exceeded')

    def main(self):
        app = web.Application()
        app.add_routes([web.get('/{service}', self.handle_request)])

        web.run_app(app, port=8080)

if __name__ == '__main__':
    LoadBalancer().main()
