typedef struct {
    json_object *config;
    int version;
} config_t;

typedef struct {
    const char *key;
    int type;
} field_t;

typedef enum {
    FIELD_REQUIRED,
    FIELD_OPTIONAL
} field_required_t;

config_t *config_new(int version) {
    config_t *conf = malloc(sizeof(config_t));
    conf->version = version;
    conf->config = json_object_new();
    return conf;
}

void config_free(config_t *conf) {
    if (conf == NULL)
        return;
    json_object_put(conf->config);
    free(conf);
}

json_object *config_get_value(config_t *conf, const char *key) {
    json_object *value = json_object_object_get(conf->config, key);
    if (value == NULL && conf->version > 0) {
        // Load previous versions of the config
        for (int i = 1; i <= conf->version; i++) {
            FILE *file = fopen(strcat("config-", itoa(i), ".json"), "r");
            if (file != NULL) {
                json_object *prev_config = json_object_from_file(file);
                fclose(file);
                if (prev_config != NULL) {
                    value = json_object_object_get(prev_config, key);
                    break;
                }
            }
        }
    }
    return value;
}

int config_set_value(config_t *conf, const char *key, json_object *value) {
    // Validate the new value against the schema
    if (json_object_is_type(value, JSON_OBJECT)) {
        // Recursively set nested values
        for (json_object_iter iter = json_object_iterate(value);
             iter.next != NULL; iter = json_object_iterate(iter.next)) {
            const char *field_key = iter.key;
            json_object *child_value = json_object_get(value, field_key);
            if (child_value != NULL) {
                config_set_value(conf, strcat(key, ".", field_key), child_value);
            }
        }
    } else {
        // Set the value at the given key
        json_object_object_add(conf->config, key, value);
    }
    return 0;
}

int main() {
    config_t *conf = config_new(1);
    json_object *value = config_get_value(conf, "service");
    if (value != NULL) {
        // Process the configuration values
        for (json_object_iter iter = json_object_iterate(value); 
             iter.next != NULL; iter = json_object_iterate(iter.next)) {
            const char *field_key = iter.key;
            json_object *child_value = json_object_get(value, field_key);
            if (child_value != NULL) {
                // Validate and process the child values
                for (json_object_iter child_iter = json_object_iterate(child_value); 
                     child_iter.next != NULL; child_iter = json_object_iterate(child_iter.next)) {
                    const char *field_name = child_iter.key;
                    json_object *child_value = json_object_get(child_value, field_name);
                    if (child_value != NULL) {
                        // Handle the value according to its type
                        switch (json_object_get_type(child_value)) {
                            case JSON_INTEGER:
                                printf("%s: %d\n", field_key, json_object_get_int(child_value));
                                break;
                            case JSON_REAL:
                                printf("%s: %f\n", field_key, json_object_get_real(child_value));
                                break;
                            case JSON_STRING:
                                printf("%s: %s\n", field_key, json_object_get_string(child_value));
                                break;
                            default:
                                // Handle unknown types
                        }
                    }
                }
            }
        }
    } else {
        printf("No configuration found.\n");
    }
    config_free(conf);
    return 0;
}
