#include <condition_variable>
#include <chrono>

// Configurable session timeout (in seconds)
const int SESSION_TIMEOUT = 3600; // 1 hour

// Configurable inactivity timeout (in seconds)
const int INACTIVITY_TIMEOUT = 300; // 5 minutes

class UserSession {
public:
    std::string userId;
    int loginTimestamp;
    int duration;
    std::deque<std::string> activityLogs;

    UserSession(const std::string& userId, int loginTimestamp) 
        : userId(userId), loginTimestamp(loginTimestamp) {}
};

// Thread-safe session collection
class SessionCollection {
private:
    std::unordered_map<std::string, UserSession*> sessions;
    std::mutex mtx;
    std::condition_variable cv;

public:
    void addSession(const std::string& userId) {
        std::unique_lock<std::mutex> lock(mtx);
        sessions[userId] = new UserSession(userId, std::chrono::system_clock::now().time_since_epoch() / 1000);
    }

    void removeSession(const std::string& userId) {
        std::unique_lock<std::mutex> lock(mtx);
        if (sessions.find(userId) != sessions.end()) {
            delete sessions[userId];
            sessions.erase(userId);
        }
    }

    void updateSessionDuration(const std::string& userId, int duration) {
        std::unique_lock<std::mutex> lock(mtx);
        if (sessions.find(userId) != sessions.end()) {
            sessions[userId]->duration += duration;
        }
    }

    bool isSessionExpired(const std::string& userId) {
        std::unique_lock<std::mutex> lock(mtx);
        if (sessions.find(userId) == sessions.end()) return true;
        int loginTimestamp = sessions[userId]->loginTimestamp;
        auto now = std::chrono::system_clock::now().time_since_epoch() / 1000;
        int duration = now - loginTimestamp;
        return duration > SESSION_TIMEOUT || (duration > INACTIVITY_TIMEOUT && sessions[userId]->activityLogs.empty());
    }
};

// Adaptive eviction strategy
class EvictionStrategy {
public:
    static const int EVICTION_THRESHOLD = 10; // configurable threshold

    void evictSessions(SessionCollection& collection, size_t maxMemoryUsage) {
        std::list<std::pair<std::string, UserSession*>> sessionsToDelete;
        for (auto& session : collection.sessions) {
            if (session.second->duration > SESSION_TIMEOUT || session.second->activityLogs.empty()) {
                sessionsToDelete.emplace_back(session);
            }
        }

        // Evict sessions based on the threshold
        size_t evictedCount = 0;
        for (auto it = sessionsToDelete.begin(); it != sessionsToDelete.end() && evictedCount < EVICTION_THRESHOLD; ++it) {
            delete it->second;
            collection.sessions.erase(it->first);
            ++evictedCount;
        }
    }

    void garbageCollect(SessionCollection& collection, size_t maxMemoryUsage) {
        // Implement garbage collection logic here
    }
};

// Robust logging and monitoring system
class Logger {
public:
    void logSessionEvent(const std::string& event) {
        // Implement logging mechanism here
    }

    void monitorServiceHealth() {
        // Implement service health monitoring here
    }
};
```

Please note that this code provides the basic framework for designing a modular C++ library to manage `UserSession` collections. The actual implementation may require additional details, such as integrating with an external authentication service, handling session expiration and invalidation, and optimizing memory usage.']

