void init_library(int max_concurrent_connections, int max_retries) {
    // Set the maximum number of concurrent connections
    if (max_concurrent_connections > 0 && max_concurrent_connections <= MAX_CONCURRENT_CONNECTIONS) {
        config_service->max_concurrent_connections = max_concurrent_connections;
    } else {
        // Default to the maximum allowed value
        config_service->max_concurrent_connections = MAX_CONCURRENT_CONNECTIONS;
    }

    // Set the maximum number of retries for a failed connection
    if (max_retries > 0 && max_retries <= MAX_RETRIES) {
        config_service->max_retries = max_retries;
    } else {
        // Default to the maximum allowed value
        config_service->max_retries = MAX_RETRIES;
    }
}

