import org.yaml.snakeyaml.Yaml;
import org.yaml.snakeyaml.constructor.Constructor;

public class Pipeline {
    public static void main(String[] args) throws Exception {
        // Load configuration from YAML file
        File yamlFile = new File("config.yml");
        if (!yamlFile.exists()) {
            System.out.println("Configuration file not found.");
            return;
        }
        Yaml yaml = new Yaml();
        Constructor constructor = new Constructor();
        PipelineConfig config = (PipelineConfig) yaml.load(constructor, new Scanner(yamlFile));

        // Initialize pipeline instances
        ExecutorService executor = Executors.newFixedThreadPool(config.getPipelineInstances());
        for (int i = 0; i < config.getPipelineInstances(); i++) {
            executor.submit(new PipelineInstance(config));
