// Define the distributed queue system
class DistributedQueue {
    private Map<String, Queue<Integer>> queues = new HashMap<>();
    private Map<String, Integer> queueSizes = new HashMap<>();

    public void put(String queueName, int value) {
        // Implement a lock-free, thread-safe data structure for concurrent access
        if (!queues.containsKey(queueName)) {
            queues.put(queueName, new ConcurrentLinkedQueue<>());
            queueSizes.put(queueName, 0);
        }
        queues.get(queueName).add(value);
        queueSizes.put(queueName, queueSizes.getOrDefault(queueName, 0) + 1);
    }

    public int take(String queueName) {
        // Implement a lock-free, thread-safe data structure for concurrent access
        if (queues.containsKey(queueName)) {
            Queue<Integer> queue = queues.get(queueName);
            while (!queue.isEmpty()) {
                queueSizes.put(queueName, queueSizes.getOrDefault(queueName, 0) - 1);
                return queue.poll();
            }
        }
        return -1;
    }

    public Map<String, Integer> getQueueSizes() {
        return queueSizes;
    }
}

