#include <iostream>
#include <string>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>
#include <curl/curl.h>

class HttpClient {
public:
    // Constructor
    HttpClient();

    // Destructor
    ~HttpClient();

    // Asynchronous request function
    void makeRequest(const std::string& url, const std::string& method,
                      const std::string& body);

    // Set the maximum number of concurrent requests
    void setConcurrency(int concurrency);

private:
    CURL* curl;
    std::mutex mtx;
    std::condition_variable cv;
    int concurrency;

    // Helper function to make a request and handle errors
    void makeRequestHelper(const std::string& url, const std::string& method,
                            const std::string& body);
};

HttpClient::HttpClient() {
    curl = curl_easy_init();
    if (!curl) {
        std::cerr << "Failed to initialize CURL" << std::endl;
        exit(1);
    }
}

HttpClient::~HttpClient() {
    curl_easy_cleanup(curl);
}

void HttpClient::makeRequest(const std::string& url, const std::string& method,
                               const std::string& body) {
    if (concurrency == 0) {
        makeRequestHelper(url, method, body);
    } else {
        // Handle concurrency
        std::unique_lock<std::mutex> lock(mtx);
        while (concurrentRequests >= concurrency) {
            cv.wait(lock);
        }
        concurrentRequests++;
        makeRequestHelper(url, method, body);
        --concurrentRequests;
        cv.notify_all();
    }
}

void HttpClient::makeRequestHelper(const std::string& url, const std::string& method,
                                    const std::string& body) {
    CURL* easy = curl;
    CURLcode res;

    // Set URL and method
    curl_easy_setopt(easy, CURLOPT_URL, url.c_str());
    curl_easy_setopt(easy, CURLOPT_CUSTOMREQUEST, method.c_str());

    // Set request body (if any)
    if (!body.empty()) {
        struct curl_slist* sl = NULL;
        sl = curl_slist_append(sl, "Content-Type: application/json");
        sl = curl_slist_append(sl, body.c_str());
        curl_easy_setopt(easy, CURLOPT_READDATA, sl);
    }

    // Perform the request
    res = curl_easy_perform(easy);

    if (res != CURLE_OK) {
        std::cerr << "curl_easy_perform() failed: " << curl_easy_strerror(res)
                  << std::endl;
    }

    // Clean up
    curl_easy_cleanup(easy);
}

void HttpClient::setConcurrency(int concurrency) {
    this->concurrency = concurrency;
}
