import com.example.payment.exceptions.PaymentException;
import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.context.annotation.Bean;
import org.springframework.http.HttpMethod;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.client.RestTemplate;

@SpringBootApplication
public class PaymentMicroserviceApplication {

    public static void main(String[] args) {
        SpringApplication.run(PaymentMicroserviceApplication.class, args);
    }

    @Bean
    public RestTemplate restTemplate() {
        return new RestTemplate();
    }

    @PostMapping("/process-payment")
    public PaymentResponse processPayment(@RequestBody PaymentRequest paymentRequest) throws PaymentException {
        // Validate payment request
        validatePaymentRequest(paymentRequest);

        // Process payment using credit card, PayPal, Apple Pay, or Google Pay
        if (paymentRequest.getPaymentMethod().equals("credit-card")) {
            return processCreditCardPayment(paymentRequest);
        } else if (paymentRequest.getPaymentMethod().equals("paypal")) {
            return processPayPalPayment(paymentRequest);
        } else if (paymentRequest.getPaymentMethod().equals("apple-pay")) {
            return processApplePayPayment(paymentRequest);
        } else if (paymentRequest.getPaymentMethod().equals("google-pay")) {
            return processGooglePayPayment(paymentRequest);
        }

        // Handle unknown payment method
        throw new PaymentException("Unknown payment method");
    }

    private PaymentResponse processCreditCardPayment(PaymentRequest paymentRequest) throws PaymentException {
        // Call credit card gateway API
        RestTemplate restTemplate = new RestTemplate();
        PaymentResponse response = restTemplate.postForObject("https://credit-card-gateway.com/pay", paymentRequest, PaymentResponse.class);

        return response;
    }

    private PaymentResponse processPayPalPayment(PaymentRequest paymentRequest) throws PaymentException {
        // Call PayPal gateway API
        RestTemplate restTemplate = new RestTemplate();
        PaymentResponse response = restTemplate.postForObject("https://paypal-gateway.com/pay", paymentRequest, PaymentResponse.class);

        return response;
    }

    private PaymentResponse processApplePayPayment(PaymentRequest paymentRequest) throws PaymentException {
        // Call Apple Pay gateway API
        RestTemplate restTemplate = new RestTemplate();
        PaymentResponse response = restTemplate.postForObject("https://apple-pay-gateway.com/pay", paymentRequest, PaymentResponse.class);

        return response;
    }

    private PaymentResponse processGooglePayPayment(PaymentRequest paymentRequest) throws PaymentException {
        // Call Google Pay gateway API
        RestTemplate restTemplate = new RestTemplate();
        PaymentResponse response = restTemplate.postForObject("https://google-pay-gateway.com/pay", paymentRequest, PaymentResponse.class);

        return response;
    }

    private void validatePaymentRequest(PaymentRequest paymentRequest) {
        // Validate payment request fields (e.g., amount, currency, region)
    }
}

class PaymentResponse {
    // Response fields
}

class PaymentRequest {
    // Request fields (e.g., payment method, amount, currency, region)
}
```

