            features = self.feature_extractor(review, aggregation='average')
            return {'lang': lang, 'sentiment': sentiment_result, **features}
        except (ConnectionError, LangDetectException) as e:
            print(f"Error processing review: {e}")
            return {}

    def process_reviews(self, reviews: List[str]) -> List[Dict]:
        with ThreadPoolExecutor(max_workers=5) as executor:
