import asyncio
from typing import Dict, Any

class DistributedCachingFramework:
    def __init__(self, remote_config_service: str):
        self.remote_config_service = remote_config_service
        self.caches: Dict[str, Dict[str, Any]] = {}
        self.locks: Dict[str, asyncio.Lock] = {}

    async def get_preference(self, user_id: str) -> Any:
        if user_id not in self.caches:
            self.caches[user_id] = await self.remote_config_service.get_preferences(user_id)
            self.locks[user_id] = asyncio.Lock()

        return self.caches[user_id]

    async def set_preference(self, user_id: str, preference_key: str, value: Any) -> None:
        if user_id not in self.caches or preference_key not in self.caches[user_id]:
            await self.remote_config_service.update_preferences(user_id, {preference_key: value})
            await self.refresh_cache(user_id)

    async def refresh_cache(self, user_id: str) -> None:
        while True:
            try:
                new_prefs = await self.remote_config_service.get_preferences(user_id)
                if new_prefs != self.caches[user_id]:
                    self.caches[user_id] = new_prefs
                    break
            except Exception as e:
                print(f"Error refreshing cache for user {user_id}: {e}")

    async def sync_persistent_data(self) -> None:
        while True:
            try:
                await self.remote_config_service.sync_persistent_data()
                break
            except Exception as e:
                print(f"Error syncing persistent data: {e}")

    async def monitor_cache(self, user_id: str) -> None:
        while True:
            if not self.caches[user_id]:
                print(f"Cache for user {user_id} is empty")
            await asyncio.sleep(5)

    async def start_framework(self) -> None:
        tasks = [
            asyncio.create_task(self.sync_persistent_data()),
            asyncio.create_task(self.monitor_cache('12345')),
            # Add more tasks as needed
        ]
        await asyncio.gather(*tasks)
