package com.example.dynamicfileprocessor;

import java.io.IOException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.ForkJoinPool;
import org.apache.commons.pool2.impl.GenericObjectPoolConfig;
import software.amazon.awssdk.services.s3.S3Client;
import software.azure.blobstorage.BlobStorageClient;
import com.google.common.io.Files;
import com.google.gson.Gson;

public class DynamicFileProcessor {
    private S3Client s3Client = S3Client.create();
    private BlobStorageClient blobStorageClient = BlobStorageClient.create();
    private ExecutorService executorService = Executors.newFixedThreadPool(10);
    private ForkJoinPool forkJoinPool = new ForkJoinPool();

    public void processFiles() throws IOException {
        // Initialize file processors for AWS S3 and Azure Blob Storage
        FileProcessor s3FileProcessor = new S3FileProcessor(s3Client, executorService);
        FileProcessor blobStorageFileProcessor = new BlobStorageFileProcessor(blobStorageClient, forkJoinPool);

        // Process files concurrently from multiple clients
        List<File> filesToProcess = Files.readAllFiles();
        List<Future<String>> futures = new ArrayList<>();
        for (File file : filesToProcess) {
            FileProcessor processor;
            if (file.getUploadType() == UploadType.AWS_S3) {
                processor = s3FileProcessor;
            } else {
                processor = blobStorageFileProcessor;
            }
            Future<String> future = executorService.submit(() -> processor.processFile(file));
            futures.add(future);
        }

        // Handle file processing results
        for (Future<String> future : futures) {
            try {
                String result = future.get();
                System.out.println("File processed: " + result);
            } catch (ExecutionException e) {
                System.err.println("Error processing file: " + e.getMessage());
            }
        }

        // Clean up resources
        executorService.shutdown();
        forkJoinPool.shutdown();
    }
}
