#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

// Structure to hold line data
typedef struct {
    char *line;
    double geometric_mean;
} LineData;

// Thread-safe linked list for storing results
typedef struct {
    LineData *data;
    int size;
    pthread_mutex_t mutex;
} ResultList;

// Function to calculate geometric mean of numerical values
double geometric_mean(double arr[], int n) {
    double prod = 1.0;
    for (int i = 0; i < n; i++) {
        if (arr[i] > 0)
            prod *= pow(arr[i], 1.0 / n);
    }
    return round(prod, 2);
}

// Function to process a chunk of lines
void process_chunk(char *lines[], int chunk_size, ResultList *list) {
    pthread_mutex_lock(&list->mutex);

    for (int i = 0; i < chunk_size; i++) {
        char *line = lines[i];
        char *token = strtok(line, " ");
        int count = 0;
        double values[3] = {0.0};

        while (count < 3 && token) {
            if (strspn(token, "0123456789.-") > 0) {
                values[count++] = atof(token);
            }
            token = strtok(NULL, " ");
        }

        if (count >= 3) {
            double geometric_mean_val = geometric_mean(values, count);
            LineData *data = (LineData *)malloc(sizeof(LineData));
            data->line = line;
            data->geometric_mean = geometric_mean_val;
            list->data = realloc(list->data, (list->size + 1) * sizeof(LineData));
            list->data[list->size++] = *data;
        }

        free(data);
    }

    pthread_mutex_unlock(&list->mutex);
}

// Function to sort and write results
void process_results(ResultList *list) {
    qsort(list->data, list->size, sizeof(LineData), &line_cmp);

    FILE *output_file = fopen("output.txt", "w");
    if (output_file == NULL) {
        perror("Error opening output file");
        return;
    }

    for (int i = 0; i < list->size; i++) {
        fprintf(output_file, "%s %f\n", list->data[i].line, list->data[i].geometric_mean);
    }
    fclose(output_file);
}

// Comparison function for qsort
int line_cmp(const void *a, const void *b) {
    LineData *line1 = *(LineData *)a;
    LineData *line2 = *(LineData *)b;

    if (line1->geometric_mean > line2->geometric_mean)
        return -1;
    else if (line1->geometric_mean < line2->geometric_mean)
        return 1;
    else
        return 0;
}

int main() {
    // Initialize result list and logging service
    ResultList *list = (ResultList *)malloc(sizeof(ResultList));
    pthread_mutex_init(&list->mutex, NULL);
    list->data = NULL;
    list->size = 0;

    // Process log file in chunks
    char *lines[] = {"..."};  // Replace with actual log lines
    int chunk_size = sizeof(lines) / sizeof(*lines);

    while (chunk_size > 0) {
        process_chunk(lines, chunk_size, list);
        // Read next chunk of lines from the log file
        chunk_size = ...;  // Replace with actual chunk size
    }

    // Process and write results
    process_results(list);

    free(list->data);
    pthread_mutex_destroy(&list->mutex);
    free(list);

    return 0;
}
