void parallel_execute_commands(Environment* environment) {
    pthread_t threads[MAX_ENVIRONMENTS * MAX_COMMANDS];
    int thread_index = 0;

    for (int i = 0; i < environment->num_commands; i++) {
        for (int j = 0; j < MAX_ENVIRONMENTS; j++) {
            if (pthread_create(&threads[thread_index], NULL, execute_command, &environment->commands[i]) != 0) {
                printf("Failed to create thread\n");
                exit(1);
            }
            thread_index++;
        }
    }

    for (int i = 0; i < thread_index; i++) {
        pthread_join(threads[i], NULL);
    }
}

