import org.elasticsearch.action.get.GetRequest;
import org.elasticsearch.action.get.GetResponse;
import org.elasticsearch.client.RequestOptions;
import org.elasticsearch.client.RestClient;
import org.elasticsearch.client.RestHighLevelClient;

// Initialize the logging system
public class LoggingSystem {
    private static final String KAFKA_BOOTSTRAP_SERVERS = "kafka-bootstrap-servers";
    private static final String KAFKA_TOPIC_NAME = "logs_topic_name";
    private static final String ELASTICSEARCH_HOST = "elasticsearch-host";
    private static final int ELASTICSEARCH_PORT = 9200;

    private KafkaProducer<String, String> kafkaProducer;
    private RestHighLevelClient restHighLevelClient;
    private ObjectMapper objectMapper;

    // Initialize the logging system
    public LoggingSystem() {
        init();
    }

    private void init() {
        // Initialize Kafka Producer
        Properties properties = new Properties();
        properties.put("bootstrap.servers", KAFKA_BOOTSTRAP_SERVERS);
        kafkaProducer = new KafkaProducer<String, String>(properties);

        // Initialize Elasticsearch Client
        RestHighLevelClient restHighLevelClient = new RestHighLevelClient(
                RestClient.builder(new HttpHost(ELASTICSEARCH_HOST, ELASTICSEARCH_PORT)));

        // Initialize Jackson Object Mapper
        ObjectMapper objectMapper = new ObjectMapper();
        objectMapper.registerModule(new JacksonJaxbModule());

        this.kafkaProducer = kafkaProducer;
        this.restHighLevelClient = restHighLevelClient;
        this.objectMapper = objectMapper;
    }

    // Log a message to Kafka and Elasticsearch
    public void log(String message) {
        // Convert the message to JSON using Jackson
        String jsonMessage = new ObjectMapper().writeValueAsString(message);

        // Send the message to Kafka
        ProducerRecord<String, String> record = new ProducerRecord<>(KAFKA_TOPIC_NAME, message);
        kafkaProducer.send(record);

        // Index the message in Elasticsearch
        GetResponse getResponse = restHighLevelClient.get(GetRequest.builder().index("logs").id(message).build(), RequestOptions.DEFAULT);
    }
}

