NetworkConnectionStatus* createNetworkConnectionStatus(char* ipAddress, int portNumber) {
    NetworkConnectionStatus* connection = malloc(sizeof(NetworkConnectionStatus));
    connection->ipAddress = strdup(ipAddress);
    connection->portNumber = portNumber;
    connection->status = 0; // Not connected initially
    return connection;
}

// Function to free a network connection status structure
void freeNetworkConnectionStatus(NetworkConnectionStatus* connection) {
    if (connection != NULL) {
        free(connection->ipAddress);
        free(connection);
    }
}

// Thread-safe function to attempt a network connection
void* connectToNetwork(void* arg) {
    NetworkConnectionStatus* connection = (NetworkConnectionStatus*)arg;
    int retries = 0;
    int delay = INITIAL_RETRY_DELAY;

    while (connection->status == 0 && retries < MAX_RETRIES) {
        // Simulate the actual network connection attempt
        printf("Attempting to connect to %s:%d...\n", connection->ipAddress, connection->portNumber);
        sleep(delay); // Pause for the delay period

        if (/* Network connection successful */) {
            connection->status = 2; // Mark as connected
            break;
        } else {
            retries++;
            delay *= 2; // Double the delay for the next attempt
        }
    }

    printf("Connection to %s:%d status: %s\n", connection->ipAddress, connection->portNumber,
           connection->status == 0 ? "Failed" : connection->status == 1 ? "Connecting" : "Connected");
}

