// Define constants for socket options and buffer sizes
#define SO_REUSEADDR 1
#define BUFFER_SIZE 1024

// Function to create a new socket
int create_socket() {
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("Socket creation failed");
        exit(EXIT_FAILURE);
    }
    return sock;
}

// Function to set socket options
void set_socket_options(int sock) {
    int optval = SO_REUSEADDR;
    socklen_t optlen = sizeof(optval);
    setsockopt(sock, SOL_SOCKET, SO_REUSEADDR, &optval, optlen);
}

// Function to bind a socket to an address and port
int bind_socket(int sock, struct sockaddr_in* addr, int port) {
    int ret = bind(sock, (struct sockaddr*)addr, sizeof(*addr));
    if (ret < 0) {
        perror("Socket binding failed");
        exit(EXIT_FAILURE);
    }
    return ret;
}

// Function to listen on a socket
int listen_socket(int sock) {
    int ret = listen(sock, 3); // Listen for up to 3 connections
    if (ret < 0) {
        perror("Socket listening failed");
        exit(EXIT_FAILURE);
    }
    return ret;
}

// Function to accept a connection on a socket
int accept_connection(int sock) {
    struct sockaddr_in addr;
    int client_sock = accept(sock, (struct sockaddr*)&addr, sizeof(addr));
    if (client_sock < 0) {
        perror("Socket accepting failed");
        exit(EXIT_FAILURE);
    }
    return client_sock;
}

// Function to handle incoming data
void* handle_data(void* arg) {
    int sock = *(int*)arg;
    // Process data on the socket
    // ...
    return NULL;
}

// Function to start a new thread for handling data
void* start_thread(void* arg) {
    pthread_t thread;
    int ret = pthread_create(&thread, NULL, handle_data, arg);
    if (ret < 0) {
        perror("Thread creation failed");
        exit(EXIT_FAILURE);
    }
    return NULL;
}

// Main function to create and manage the socket
int main() {
    // Create a new socket
    int sock = create_socket();

    // Set socket options
    set_socket_options(sock);

    // Bind the socket to an address and port
    struct sockaddr_in addr;
    inet_pton(AF_INET, "127.0.0.1", &addr.sin_addr);
    addr.sin_port = htons(8080);
    bind_socket(sock, &addr, 8080);

    // Listen on the socket
    listen_socket(sock);

    // Accept connections and start new threads for handling data
    while (1) {
        int client_sock = accept_connection(sock);
        pthread_t thread;
        start_thread(&client_sock);
    }

    return 0;
}
