#include <stdlib.h>
#include <stdio.h>

// Define the structure for a DataRecord
typedef struct {
    int timestamp;
    void* payload; // variable-length binary payload
    void* config;  // pointer to an external sensor configuration object
} DataRecord;

// Define the linked list node structure
typedef struct _node {
    DataRecord record;
    struct _node* next;
} Node;

// Define the dynamic linked list structure
typedef struct {
    Node* head;
    Node* tail;
    int size;
} LinkedList;

// Function to create a new linked list
LinkedList* ll_create() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    return list;
}

// Function to insert a new record into the linked list
void ll_insert(LinkedList* list, DataRecord record) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->record = record;
    node->next = NULL;

    if (list->head == NULL) {
        list->head = node;
        list->tail = node;
    } else {
        node->next = list->head;
        list->head = node;
    }

    list->size++;
}

// Function to remove the record at the head of the linked list
void ll_remove_head(LinkedList* list) {
    if (list->head == NULL) return;

    Node* old_head = list->head;
    list->head = list->head->next;

    if (list->head == NULL) {
        list->tail = NULL;
    }

    free(old_head);
    list->size--;
}

// Function to iterate over the linked list
void ll_iterate(LinkedList* list, void (*func)(DataRecord)) {
    Node* node = list->head;
    while (node != NULL) {
        func(node->record);
        node = node->next;
    }
}
