// Function to serialize a record into a buffer
void record_serialize(Record *record, unsigned char **buffer) {
    // Serialize the record fields
    (*buffer) = (unsigned char *)malloc((sizeof(record->id) + strlen(record->name) + sizeof(record->value)) * sizeof(char));
    memcpy(*buffer, &record->id, sizeof(record->id));
    strcpy(*(char **)buffer + sizeof(record->id), record->name);
    memcpy(*(char **)buffer + sizeof(record->id) + strlen(record->name) + 1, &record->value, sizeof(record->value));

    // Increment the buffer pointer for next serialization
    *(char **)buffer += (sizeof(record->id) + strlen(record->name) + sizeof(record->value));
}

// Function to deserialize a record from a buffer
Record *record_deserialize(unsigned char **buffer, int *size) {
    Record *record = (Record *)malloc(sizeof(Record));

    // Deserialize the record fields
    record->id = *((int *)*buffer);
    strcpy(record->name, (*buffer + sizeof(record->id)));
    record->value = *((double *)(*buffer + sizeof(record->id) + strlen(record->name) + 1));

    // Reset the buffer pointer and update size
    *buffer += (sizeof(record->id) + strlen(record->name) + sizeof(record->value));
    *size -= (sizeof(record->id) + strlen(record->name) + sizeof(record->value));

    return record;
}

