void initializeRecords(int numRecords, int minKey, int maxKey) {
    // Initialize random number generator
    srand(time(NULL));

    // Allocate memory for records
    record_t* records = (record_t*)malloc(numRecords * sizeof(record_t));

    if (!records) {
        printf("Memory allocation failed!\n");
        return;
    }

    // Initialize each record's key with a random value within the specified range
    for (int i = 0; i < numRecords; i++) {
        records[i].key = minKey + rand() % ((maxKey - minKey) + 1);
        records[i].offset = (long)i;
    }

    // Connect to the database
    MYSQL* mysql = mysql_init(NULL);
    if (!mysql_real_connect(mysql, "localhost", "username", "password", "database_name", 0)) {
        printf("Database connection failed!\n");
        mysql_close(mysql);
        free(records);
        return;
    }

    // Insert records into the database
    for (int i = 0; i < numRecords; i++) {
        char query[1024];
        sprintf(query, "INSERT INTO table_name VALUES (%d, %ld)", records[i].key, records[i].offset);
        if (!mysql_query(mysql, query)) {
            printf("Record inserted successfully!\n");
        } else {
            printf("Error inserting record: %s\n", mysql_error(mysql));
        }
    }

    // Close the database connection
    mysql_close(mysql);

    // Clean up memory
    free(records);
}

int main() {
