// Function to initialize records with dynamic memory allocation
void initializeRecords(int initialCapacity, int growthFactor) {
    // Declare a pointer to the first record
    Record *records = (Record *)malloc(initialCapacity * sizeof(Record));

    // Initialize an index variable for keeping track of the current capacity
    int capacity = initialCapacity;

    // Function to dynamically resize the array when it becomes full
    void *reallocRecords(void *ptr, int newCapacity) {
        Record *newRecords = (Record *)malloc(newCapacity * sizeof(Record));
        int i;
        for (i = 0; i < capacity; i++) {
            newRecords[i] = records[i];
        }
        free(ptr);
        return newRecords;
    }

    // Function to add a record with key and offset
    void addRecord(int key, long offset) {
        if (capacity == 0 || capacity >= growthFactor) {
            capacity *= growthFactor;
            records = reallocRecords(records, capacity);
        }
        records[capacity - 1].key = key;
        records[capacity - 1].offset = offset;
    }

    // Function to get the record at a specified index
    Record *getRecord(int index) {
        if (index >= 0 && index < capacity) {
            return &records[index];
        } else {
            printf("Index out of range.\n");
            exit(1);
        }
    }

    // Function to free memory allocated for the records
    void freeRecords() {
        free(records);
    }

}

