class Record {
public:
    int key;
    long offset;

    Record(int k, long o) : key(k), offset(o) {}
};

class CacheManager {
private:
    std::vector<Record*> records;
    std::mutex mutex;
    std::map<int, long> recordOffsets;

public:
    CacheManager(size_t capacity) {
        records.reserve(capacity);
    }

    void addRecord(int key, long offset) {
        std::lock_guard<std::mutex> lock(mutex);
        Record* record = new Record(key, offset);
        records.push_back(record);
        recordOffsets[key] = offset;
    }

    void updateRecord(int key, long newOffset) {
        std::lock_guard<std::mutex> lock(mutex);
        if (recordOffsets.find(key) != recordOffsets.end()) {
            recordOffsets[key] = newOffset;
        }
    }

    ~CacheManager() {
        for (Record* record : records) {
            delete record;
        }
    }

    void synchronizeRecords(std::vector<Record*> remoteRecords) {
        std::lock_guard<std::mutex> lock(mutex);
        for (Record* record : remoteRecords) {
            if (!recordOffsets.count(record->key)) {
                records.push_back(new Record(record->key, record->offset));
                recordOffsets[record->key] = record->offset;
            }
        }
    }

    bool isWithinResourceLimits() {
        size_t totalKeys = 0;
        for (const auto& pair : recordOffsets) {
            totalKeys += pair.first;
            if (totalKeys > INT_MAX) {
                return false; // Resource limit exceeded
            }
        }
        return true;
    }

    void printCacheState() {
        std::cout << "Records: ";
        for (Record* record : records) {
            std::cout << "(" << record->key << ", " << record->offset << ") ";
        }
        std::cout << std::endl;
    }
};

