// Define a struct to hold environment information
typedef struct {
    char* name;
    char* config_file;
    int num_commands;
    char** commands;
} Environment;

// Function to execute a command in parallel
void* execute_command(void* env) {
    Environment* e = (Environment*)env;

    // Execute the command
    system(e->commands[0]);

    return NULL;
}

// Function to create and start multiple threads for parallel execution
int parallel_execute(int num_threads, Environment* environments[]) {
    pthread_t threads[num_threads];

    for (int i = 0; i < num_threads; i++) {
        // Create a new thread for each environment
        if (pthread_create(&threads[i], NULL, execute_command, environments[i]) != 0) {
            printf("Error creating thread\n");
            return -1;
        }
    }

    // Wait for all threads to finish
    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}

// Function to create a new environment and add commands to it
Environment* create_environment(char* name, char* config_file) {
    Environment* env = (Environment*)malloc(sizeof(Environment));

    env->name = strdup(name);
    env->config_file = strdup(config_file);
    env->num_commands = 0;
    env->commands = NULL;

    return env;
}

// Function to add a command to an environment
void add_command(Environment* env, char* command) {
    // Dynamically allocate space for the new command array
    char** new_commands = (char**)malloc((env->num_commands + 1) * sizeof(char*));

    // Copy the old commands into the new array
    for (int i = 0; i < env->num_commands; i++) {
        new_commands[i] = env->commands[i];
    }

    // Add the new command to the end of the array
    new_commands[env->num_commands] = strdup(command);

    // Update the environment's command count and array
    free(env->commands);
    env->commands = new_commands;
    env->num_commands++;
}

// Function to start parallel execution for all environments
int main() {
    Environment* env1 = create_environment("env1", "config_file_1");
    add_command(env1, "command1");
    add_command(env1, "command2");

    Environment* env2 = create_environment("env2", "config_file_2");
    add_command(env2, "command3");
    add_command(env2, "command4");

    int num_threads = 2;
    parallel_execute(num_threads, (Environment*[2]){env1, env2});

    // Free memory to prevent leaks
    free(env1->name);
    free(env1->config_file);
    free(env2->name);
    free(env2->config_file);
    free(env1->commands);
    free(env2->commands);

    return 0;
}
