  const authenticatedUser = identityProvider.authenticate(username, token);

  if (!authenticatedUser) {
    throw new Error('Invalid authentication credentials');
  }

  // Validate the session against the session store
  const isValidSession = sessionStore.validateSession(sessionID, username, role);

  if (!isValidSession) {
    loggingService.logError(`Invalid or expired session ${sessionID}`);
    return null;
  }

  // Check for RBAC permissions and authorize access
  if (role !== authenticatedUser.role) {
    throw new Error('Access denied due to mismatched roles');
  }

