typedef struct {
    time_t timestamp;
    unsigned char *payload;
    void *config;
} DataRecord;

// Define a linked list node
typedef struct Node {
    DataRecord record;
    struct Node *next;
} Node;

// Create a new linked list node
Node* create_node(DataRecord record) {
    Node *node = (Node*)malloc(sizeof(Node));
    node->record = record;
    node->next = NULL;
    return node;
}

// Insert a new node at the end of the list
void insert_node(Node **head, DataRecord record) {
    Node *new_node = create_node(record);
    if (*head == NULL) {
        *head = new_node;
    } else {
        Node *curr = *head;
        while (curr->next != NULL) {
            curr = curr->next;
        }
        curr->next = new_node;
    }
}

// Remove a node from the list
void remove_node(Node **head, DataRecord record) {
    if (*head == NULL) return;
    if ((*head)->record.timestamp == record.timestamp) {
        Node *temp = *head;
        *head = (*head)->next;
        free(temp);
        return;
    }
    Node *curr = *head;
    while (curr->next != NULL && curr->next->record.timestamp != record.timestamp) {
        curr = curr->next;
    }
    if (curr->next != NULL) {
        Node *temp = curr->next;
        curr->next = temp->next;
        free(temp);
    }
}

// Check if a node exists in the list
int contains_node(Node *head, DataRecord record) {
    Node *curr = head;
    while (curr != NULL && curr->record.timestamp != record.timestamp) {
        curr = curr->next;
    }
    return curr != NULL;
}

// Process incoming sensor data from multiple devices in real-time
void process_data(Node *head, void (*callback)(DataRecord)) {
    Node *curr = head;
    while (curr != NULL) {
        DataRecord record = curr->record;
        callback(record);
        curr = curr->next;
    }
}

