use std::fs;
use std::path::{Path, PathBuf};
use std::process::Command;

pub fn measure_compilation_time_and_memory(
    src_file: &str,
    log_hook: &dyn Fn(&str) -> String,
) -> Result<(u64, u64), Box<dyn std::error::Error>> {
    let mut command = Command::new("rustc");
    command.arg("--crate-name=mytest");
    command.arg(src_file);
    command.env("RUST_LOG_LEVEL", "debug");

    let output = match command.output() {
        Ok(output) => output,
        Err(e) => return Err(Box::new(e)),
    };

    let (stdout, stderr) = output.split_stdout_stderr();
    let log_output = format!("{}{}", stdout.as_slice(), stderr.as_slice());

    for line in log_output.lines() {
        if line.contains("error") {
            return Err(format!("Compilation error: {}", line).into());
        }
    }

    let time = match output.stdout().len() as u64 {
        0 => 0,
        _ => fs::metadata(src_file)?.len() as u64,
    };

    let memory_usage = Command::new("free")
        .arg("-m")
        .output()
        .unwrap()
        .total_bytes as u64;

    Ok((time, memory_usage))
}
