// Define the structure for DataRecord
typedef struct {
    int timestamp;
    unsigned char payload[1024]; // Variable-length binary payload
    void* config; // Pointer to an external sensor configuration object
} DataRecord;

// Define the linked list node structure
typedef struct Node {
    DataRecord data;
    struct Node* next;
} Node;

// Define the linked list structure
typedef struct {
    Node* head;
    Node* tail;
    pthread_mutex_t lock; // Lock for thread safety
} LinkedList;

// Function to create a new LinkedList instance
LinkedList* linkedListCreate() {
    LinkedList* ll = (LinkedList*)malloc(sizeof(LinkedList));
    ll->head = NULL;
    ll->tail = NULL;
    pthread_mutex_init(&ll->lock, NULL);
    return ll;
}

// Function to add a new DataRecord to the linked list
void linkedListAdd(LinkedList* ll, DataRecord data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data = data;
    newNode->next = NULL;

    if (ll->head == NULL) {
        ll->head = newNode;
        ll->tail = newNode;
    } else {
        ll->tail->next = newNode;
        ll->tail = newNode;
    }

    pthread_mutex_unlock(&ll->lock);
}

// Function to retrieve a DataRecord from the linked list
DataRecord* linkedListGet(LinkedList* ll, int timestamp) {
    Node* current = ll->head;
    while (current != NULL) {
        if (current->data.timestamp == timestamp) {
            return &current->data;
        }
        current = current->next;
    }
    return NULL;
}

// Function to free the linked list memory
void linkedListFree(LinkedList* ll) {
    Node* current = ll->head;
    Node* next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&ll->lock);
    free(ll);
}

