```php
<?php

use Redis;
use GuzzleHttp\Client;

class SessionManager {
    private $redis;
    private $identityProviderUrl;
    private $tokenLength = 64;
    private $maxTokenValidityHours = 24;

    public function __construct($redisHost, $redisPort, $identityProviderUrl) {
        $this->redis = new Redis();
        $this->redis->connect($redisHost, $redisPort);
        $this->identityProviderUrl = $identityProviderUrl;
    }

    public function generateSessionToken() {
        return bin2hex(random_bytes($this->tokenLength / 8));
    }

    public function validateSessionToken($sessionToken) {
        if (!$this->isSessionTokenValid($sessionToken)) {
            return false;
        }

        // Check Redis for session existence and validity
        $redisSessionData = $this->redis->hGetAll($sessionToken);
        if (!count($redisSessionData)) {
            return false;
        }

        return true;
    }

    public function createSession($username, $email) {
        $token = $this->generateSessionToken();

        // Store session in Redis
        $this->redis->hmset($token, [
            'username' => $username,
            'email' => $email,
            'expired' => false
        ]);

        return $token;
    }

    public function revokeSession($sessionToken) {
        $this->redis->hDel($sessionToken);
    }

    private function isSessionTokenValid($sessionToken) {
        // Check Redis for session existence and validity
        if (!$this->redis->exists($sessionToken)) {
            return false;
        }

        $redisSessionData = $this->redis->hGetAll($sessionToken);
        if (count($redisSessionData) == 0 || $redisSessionData['expired'] ?? true) {
            return false;
        }

        return true;
    }

    public function authenticateUser($username, $password) {
        // Call external identity provider to validate credentials
        $identityProviderClient = new Client(['base_uri' => $this->identityProviderUrl]);
        $response = $identityProviderClient->post('/authenticate', ['form_params' => [
            'username' => $username,
            'password' => $password
        ]]);

        if ($response->getStatusCode() !== 200) {
            return false;
        }

        // Get user-specific information required for session management
        $userData = json_decode($response->getBody()->getContents(), true);

        // Create session using username and other relevant data
        $sessionToken = $this->createSession($username, $userData['email']);

        return $sessionToken;
    }

    public function logoutUser($sessionToken) {
        $this->revokeSession($sessionToken);

        // Remove expired sessions from Redis periodically
        $this->removeExpiredSessions();
    }

    private function removeExpiredSessions() {
        // Check for expired sessions in Redis and remove them
        $expiredTokens = $this->redis->find('expired', 'true');

        foreach ($expiredTokens as $token) {
            $this->revokeSession($token);
        }
    }
}

// Example usage:
$sessionManager = new SessionManager('localhost', 6379, 'https://identity-provider.com');
$sessionToken = $sessionManager->authenticateUser('username', 'password');

if ($sessionToken !== false) {
    // User is authenticated; use the session token
} else {
    // Authentication failed
}
