from tornado.websocket import WebSocketHandler
import prometheus_client as pmc
import influxdb

class MonitoringPlatform(tornado.web.Application):
    def __init__(self, config):
        super().__init__()
        self.config = config
        self.prometheus_metrics = {}
        self.graphite_metrics = {}
        self.influxdb_client = None

    class PrometheusHandler(WebSocketHandler):
        async def open(self):
            self.prometheus_metrics = pmc.GaugeMetrics()
            self.prometheus_metrics.register(pmclient)

    class GraphiteHandler(WebSocketHandler):
        async def open(self):
            self.graphite_metrics = graphiteclient()

    class InfluxdbHandler(tornado.web.RequestHandler):
        def get(self):
            data = influxdb_client.query("SELECT * FROM <measurement_name>")
            self.write(data)

