            alerts = []
            for alert in self.alerts:
                if alert.triggered():
                    alerts.append(alert)
            self.write({"alerts": [str(a) for a in alerts]})

    class GrafanaHandler(tornado.web.RequestHandler):
        def get(self):
            data = grafanaclient().get()
            self.write(data)

    @asyncio.coroutine
    def start_prometheus(self):
