                self.prometheus_metrics[metric].observe(data[metric])
        if self.graphite_metrics:
            for metric in self.graphite_metrics:
                self.graphite_metrics[metric].observe(data[metric])

    async def process_alerts(self, alerts):
        await asyncio.gather(
            *[self.send_alert(a) for a in alerts]
        )

    async def send_alert(self, alert):
        if self.config.alerting_enabled:
            try:
                response = await http_client.fetch("http://alert_url")
                response.raise_for_status()
            except Exception as e:
                logging.error(f"Error sending alert: {str(e)}")

