        this.kubernetesClient = kubernetesClient;
        this.chart = chart;
    }

    public void deployService(String serviceNamespace, String serviceName) {
        // Create a new deployment for the service
        Deployable deployable = kubernetesClient.newDeploymentBuilder()
                .withNewMetadata().name(serviceName).namespace(serviceNamespace)
                .withNewSpec().replicas(1)
                .withNewContainer().name("service")
                .image("service-image").port(8080)
                .build();

        // Create the deployment
        deployable.create();

        // Scale the deployment
        kubernetesClient.resource(deployable).scaleToReplicaCount(3);

        // Get the service
        Service service = kubernetesClient.services().inNamespace(serviceNamespace).withName(serviceName).get();

        // Expose the service as a load balancer
        LoadBalancerService.loadBalancerService(kubernetesClient, service);
    }

    public void monitorService(String serviceNamespace, String serviceName) {
        // Get the service
        Service service = kubernetesClient.services().inNamespace(serviceNamespace).withName(serviceName).get();

        // Monitor the service using Prometheus and Grafana
        Prometheus prometheus = new Prometheus(kubernetesClient, service);
        Grafana grafana = new Grafana(kubernetesClient, service);

        // Visualize the metrics in Grafana dashboards
        grafana.visualizeMetrics(prometheus.metrics());
    }

