        List<Pod> pods = kubernetesClient.pods().inNamespace(namespace).list();
        List<Service> services = kubernetesClient.services().inNamespace(namespace).list();

        // Set quotas for CPU and memory usage
        Map<String, Double> cpuQuotas = Map.of("cpu- quota-1", 100.0, "cpu-quota-2", 200.0);
        Map<String, Long> memoryQuotas = Map.of("memory-quota-1", 1024L, "memory-quota-2", 2048L);

        // Apply the quotas
        kubernetesClient.resource(pods).applyQuotas(cpuQuotas, memoryQuotas);
        kubernetesClient.resource(services).applyQuotas(cpuQuotas, memoryQuotas);
    }

