#include <arpa/inet.h>
#include <pthread.h>

#define PORT 8080

typedef struct {
    int id;
    char* data;
} DataPackage;

void* process_data(void* package) {
    DataPackage* pkg = (DataPackage*)package;
    // Process the data
    printf("Processed data: %s\n", pkg->data);
    return NULL;
}

int main() {
    int sockfd, connfd;
    struct sockaddr_in servaddr, cliaddr;
    pthread_t thread;

    if ((sockfd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        printf("Socket creation failed...\n");
        exit(1);
    }

    servaddr.sin_family = AF_INET;
    servaddr.sin_addr.s_addr = INADDR_ANY;
    servaddr.sin_port = htons(PORT);

    if (bind(sockfd, (struct sockaddr*)&servaddr, sizeof(servaddr)) < 0) {
        printf("Bind failed...\n");
        exit(1);
    }

    listen(sockfd, 3);

    while (1) {
        int bytesReceived = recv(sockfd, &cliaddr, sizeof(cliaddr), 0);
        if (bytesReceived < 0) {
            perror("recv");
        } else {
            printf("Received connection from client...\n");

            pthread_create(&thread, NULL, process_data, &cliaddr);

            connfd = accept(sockfd, (struct sockaddr*)&cliaddr, sizeof(cliaddr));
            if (connfd < 0) {
                printf("Error in accepting the client request...\n");
                exit(1);
            }

            close(connfd);
        }
    }

    return 0;
}

