// Cache structure
typedef struct {
    pthread_mutex_t lock;
    int capacity;
    NLII* cache[NLII_CACHE_SIZE];
    int size;
} NLII_Cache;

// External data source API callback function
void (*api_callback)(const NLII*);

// Initialize NLII cache
NLII_Cache* nlii_cache_init(int capacity) {
    NLII_Cache* cache = (NLII_Cache*)malloc(sizeof(NLII_Cache));
    cache->capacity = capacity;
    cache->size = 0;
    pthread_mutex_init(&cache->lock, NULL);
    return cache;
}

// Add NLII to the cache
void nlii_cache_add(NLII_Cache* cache, const NLII* nlii) {
    pthread_mutex_lock(&cache->lock);
    if (cache->size < cache->capacity) {
        cache->cache[cache->size++] = *nlii;
    }
    pthread_mutex_unlock(&cache->lock);
}

// Get NLII from the cache
NLII* nlii_cache_get(NLII_Cache* cache, uint32_t RX_UE_INFORMATION_TAG) {
    pthread_mutex_lock(&cache->lock);
    for (int i = 0; i < cache->size; i++) {
        if (cache->cache[i]->RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG) {
            NLII* nlii = cache->cache[i];
            pthread_mutex_unlock(&cache->lock);
            return nlii;
        }
    }
    pthread_mutex_unlock(&cache->lock);
    return NULL;
}

// Refresh NLII data from the external source
void api_refresh(NLII_Cache* cache, void (*callback)(const NLII*)) {
    // API call logic here
    callback(nlui); // pass the updated NLII to the callback function

    pthread_mutex_lock(&cache->lock);
    for (int i = 0; i < cache->size; i++) {
        if (cache->cache[i]->RX_UE_INFORMATION_TAG == nlui->RX_UE_INFORMATION_TAG) {
            // Update the cached NLII
            cache->cache[i] = *nlui;
        }
    }
    pthread_mutex_unlock(&cache->lock);
}

// Main loop for updating NLII data in real-time
void* nlii_updater(void* arg) {
    while (1) {
        api_refresh(nlii_cache, api_callback);
        usleep(API_REFRESH_INTERVAL * 1000); // refresh interval in microseconds
    }
    return NULL;
}
