// Define structure for caching mechanism
typedef struct {
    void** cacheEntries;
    int capacity;
    pthread_mutex_t mutex;
} Cache;

// Function to initialize the caching mechanism
Cache* initCache(int capacity) {
    Cache* cache = (Cache*)malloc(sizeof(Cache));
    cache->cacheEntries = (void**)malloc(capacity * sizeof(void*));
    cache->capacity = capacity;
    pthread_mutex_init(&cache->mutex, NULL);
    return cache;
}

// Function to add an entry to the caching mechanism
void addToCache(Cache* cache, void* entry) {
    pthread_mutex_lock(&cache->mutex);
    for (int i = 0; i < cache->capacity; i++) {
        if (cache->cacheEntries[i] == NULL) {
            cache->cacheEntries[i] = entry;
            break;
        }
    }
    pthread_mutex_unlock(&cache->mutex);
}

// Function to get an entry from the caching mechanism
void* getFromCache(Cache* cache, int index) {
    pthread_mutex_lock(&cache->mutex);
    return cache->cacheEntries[index];
}

// Function to remove an entry from the caching mechanism
void removeFromCache(Cache* cache, int index) {
    pthread_mutex_lock(&cache->mutex);
    cache->cacheEntries[index] = NULL;
    pthread_mutex_unlock(&cache->mutex);
}

