// Core Pipeline Components
public class DataProcessor {
    private Map<String, DataProcessor> processors = new HashMap<>();

    public void process(String exchange, String data) {
        DataProcessor processor = processors.get(exchange);
        if (processor == null) {
            // Initialize or retrieve the processor for this exchange
            processor = new ExchangeSpecificDataProcessor(exchange);
            processors.put(exchange, processor);
        }
        processor.process(data);
    }

    public void start() {
        // Start all processors in parallel
        List<Thread> threads = new ArrayList<>();
        for (String exchange : processors.keySet()) {
            Thread thread = new Thread(() -> processors.get(exchange).start());
            threads.add(thread);
        }
        for (Thread thread : threads) {
            thread.start();
        }
    }

    public void stop() {
        // Stop all processors
