void des_encrypt(char* data, int key_length) {
    // Initialization of DES encryption
    DES_key_schedule schedule;
    unsigned char key[8];
    for (int i = 0; i < 8; i++) {
        key[i] = (unsigned char)key_length;
    }
    DES_set_key_schedule(NULL, &schedule);
    DES_cblock cdata = *reinterpret_cast<DES_cblock*>(data);

    // Encryption process
    DES_encrypt(&cdata, &schedule);
}

// Function to decrypt data using DES algorithm
void des_decrypt(char* data, int key_length) {
    // Initialization of DES decryption
    DES_key_schedule schedule;
    unsigned char key[8];
    for (int i = 0; i < 8; i++) {
        key[i] = (unsigned char)key_length;
    }
    DES_set_key_schedule(NULL, &schedule);
    DES_cblock cdata = *reinterpret_cast<DES_cblock*>(data);

    // Decryption process
    DES_decrypt(&cdata, &schedule);
}

