void aes_encrypt(char* data, int key_length) {
    // Initialization of AES encryption
    AES_KEY aes_key;
    unsigned char key[16];
    for (int i = 0; i < 16; i++) {
        key[i] = (unsigned char)key_length;
    }
    AES_set_encrypt_key(key, 128, &aes_key);
    AES_cblock cdata = *reinterpret_cast<AES_cblock*>(data);

    // Encryption process
