        key[i] = (unsigned char)key_length;
    }
    AES_set_decrypt_key(key, 128, &aes_key);
    AES_cblock cdata = *reinterpret_cast<AES_cblock*>(data);

    // Decryption process
    AES_decrypt(&cdata, &aes_key);
}

