void camellia_encrypt(char* data, int key_length) {
    // Initialization of Camellia encryption
    CAMELLIA_KEY camellia_key;
    unsigned char key[24];
    for (int i = 0; i < 24; i++) {
        key[i] = (unsigned char)key_length;
    }
    CAMELLIA_set_encrypt_key(key, 128, &camellia_key);
