void md5_generate(char* data) {
    // Initialization of MD5
    unsigned char result[16];
    MD5_CTX ctx;
    MD5_Init(&ctx);
    MD5_Update(&ctx, data, strlen(data));
    MD5_Final(result, &ctx);

    // Printing the generated cryptographic digest
    printf("MD5 Digest: ");
    for (int i = 0; i < 16; i++) {
        printf("%02x", result[i]);
    }
    printf("\n");
}

// Function to generate cryptographic digest using SHA algorithm
