    // Initialization of SHA
    unsigned char result[20];
    SHA_CTX ctx;
    SHA_Init(&ctx);
    SHA_Update(&ctx, data, strlen(data));
    SHA_Final(result, &ctx);

    // Printing the generated cryptographic digest
    printf("SHA Digest: ");
    for (int i = 0; i < 20; i++) {
        printf("%02x", result[i]);
    }
    printf("\n");
}

// Function to generate RSA signature using SHA1 algorithm
void rsa_generate(char* data) {
    // Initialization of RSA and SHA1
    RSA *rsa;
    unsigned char signature[256];
    SHA_CTX ctx;
    SHA_Init(&ctx);
    SHA_Update(&ctx, data, strlen(data));
    SHA_Final(signature, &ctx);

    // Signing the data using RSA
    rsa = RSA_new();
    BIGNUM* bn = BN_new();
    BN_set_word(bn, 1);  // Default exponent for signature
    rsa->e = bn;
    int len = i2d_RSAPrivateKey(rsa, &signature);
    printf("RSA Signature: ");
    for (int i = 0; i < len; i++) {
        printf("%02x", signature[i]);
    }
    printf("\n");
}

