    printf("SHA Integrity Check: %s\n", sha_digest);

    // Generating RSA signature for data encryption key
    char* rsa_signature = rsa_generate(encrypted_data);
    printf("RSA Signature: %s\n", rsa_signature);

    // Cleaning up
    free(encrypted_data);
    free(aes_encrypted_data);
