    enum CipherMode { ECB, CBC, GCM };
    enum KeyExchangeAlgorithm { DH, ECC };

    // Initialize the library with a key management service (KMS)
    CryptographicLibrary(std::shared_ptr<KMS> kms) : _kms(kms) {}

    // Encrypt data using AES-128/192/256 in ECB/CBC/GCM modes
    std::string encrypt(const std::string& plaintext, CipherMode mode) {
        if (_kms->isAvailable()) {
            // Use the KMS to retrieve a symmetric key and perform encryption
            return _encrypt(plaintext, mode);
