    TelemetryProcessor(int maxDevices, int bufferCapacity) : 
        maxDevices_(maxDevices), bufferCapacity_(bufferCapacity) {}

    // Method to handle incoming telemetry data from IoT devices
    void processTelemetryData(TelemetryData telemetryData) {
        // Acquire a lock for thread safety
        std::unique_lock<std::mutex> lock(mutex_);

        // Check if the device ID is valid and buffer has not exceeded capacity
        if (deviceIdToCount_.count(telemetryData.deviceId) <= maxDevices_ && 
