        // Release the lock when retrieving data
        std::unique_lock<std::mutex> lock(mutex_);

        // Retrieve a copy of the processed data and reset the buffer
        std::deque<TelemetryData> processedData = buffer_;
        buffer_.clear();
        deviceIdToCount_.clear();

        return processedData;
    }

