#include <condition_variable>

class TelemetryProcessor {
public:
    TelemetryProcessor(int buffer_size) : buffer_size_(buffer_size), buffer_(), running_(true) {}

    void start() {
        thread_ = std::thread([this]() { process_data(); });
    }

    void stop() {
        running_ = false;
        if (thread_.joinable()) {
            thread_.join();
        }
    }

    template<typename T>
    void send_data(T&& data) {
        std::unique_lock<std::mutex> lock(mutex_);
        buffer_.push(std::forward<T>(data));
        lock.unlock();

        cv_.notify_one();
    }

private:
    int buffer_size_;
    std::queue<std::string> buffer_;
    std::thread thread_;
    bool running_;
    std::mutex mutex_;
    std::condition_variable cv_;

    void process_data() {
        while (running_) {
            std::unique_lock<std::mutex> lock(mutex_);
            cv_.wait_for(lock, std::chrono::milliseconds(1));

            if (!buffer_.empty()) {
                // Process data
                auto data = buffer_.front();
                buffer_.pop();

                // Release lock and allow other threads to access the buffer
                lock.unlock();

                // Simulate processing time
                std::this_thread::sleep_for(std::chrono::milliseconds(10));
            }
        }
    }
};

int main() {
    TelemetryProcessor processor(1000);

    processor.start();

    for (int i = 0; i < 10000; ++i) {
        processor.send_data("Data " + std::to_string(i));
    }

    processor.stop();

    return 0;
}
