import java.util.concurrent.ExecutionException;
import java.util.concurrent.Future;

public class DataIngestionPipeline {
    public static void main(String[] args) throws InterruptedException, ExecutionException {
        // Kafka configuration
        Properties kafkaProps = new Properties();
        kafkaProps.put(ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG, "localhost:9092");
        kafkaProps.put(ConsumerConfig.KEY_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class.getName());
        kafkaProps.put(ConsumerConfig.VALUE_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class.getName());

        KafkaConsumer<String, String> kafkaConsumer = new KafkaConsumer<>(kafkaProps);
        kafkaConsumer.subscribe(Collections.singleton("my_topic"));

        // MQTT configuration
        Properties mqttProps = new Properties();
        mqttProps.put("host", "localhost");
        mqttProps.put("port", 1883);

        MqttClient mqttClient = new MqttClient(mqttProps);
        mqttClient.connect();

        // HTTP configuration
        HttpClient httpClient = HttpClients.createDefault();

        while (true) {
            // Consume Kafka messages and process events
            Future<ConsumerRecords<String, String>> future = kafkaConsumer.poll(100);
            ConsumerRecords<String, String> records = future.get();
            for (ConsumerRecord<String, String> record : records) {
                // Process event from Kafka
                System.out.println("Received Kafka message: " + record.value());

                // Send MQTT message and process events
                MqttMessage mqttMessage = new MqttMessage(record.key(), record.value());
                mqttClient.publish(mqttMessage);

                // Send HTTP request and process events
                HttpPost httpPost = new HttpPost("http://localhost:8080/event");
                httpPost.setEntity(new StringEntity(record.value()));
                httpClient.execute(httpPost);
            }
        }
    }
}
