from abc import ABC, abstractmethod
from typing import List, Dict
import time
import logging
import os
import random
import json
import requests

# Message Queue and Worker Pool
class MessageQueue(ABC):
    @abstractmethod
    def put(self, message: str) -> None:
        pass

    @abstractmethod
    def get(self) -> str:
        pass

class RabbitMQ(MessageQueue):
    def __init__(self, url: str) -> None:
        self.url = url

    def put(self, message: str) -> None:
        requests.post(f"{self.url}/messages", json={"message": message})

    def get(self) -> str:
        response = requests.get(f"{self.url}/messages")
        return response.json()["message"]

class WorkerPool:
    def __init__(self, queue: MessageQueue, num_workers: int) -> None:
        self.queue = queue
        self.workers = [Worker(queue) for _ in range(num_workers)]

    def start(self) -> None:
        for worker in self.workers:
            worker.start()

    def stop(self) -> None:
        for worker in self.workers:
            worker.stop()

class Worker:
    def __init__(self, queue: MessageQueue) -> None:
        self.queue = queue

    def start(self) -> None:
        while True:
            message = self.queue.get()
            if message:
                # Process the message
                print(f"Processing {message}")
            time.sleep(0.1)

    def stop(self) -> None:
        self.queue.put(None)
