    for (int i = 1; i < size; i++) {
        if (arr[i] > max)
            max = arr[i];
    }
    return max;
}

void printLargest(int *arr, int size) {
    printf("The largest integer in the array is: %d\n", largestInteger(arr, size));
}

int main() {
    int size;
    scanf("%d", &size);

    if (size < 0)
        printf("Invalid input! Size must be positive.\n");

    int *arr = (int *)malloc(size * sizeof(int));

    for (int i = 0; i < size; i++) {
        scanf("%d", &(arr[i]));
    }

    printLargest(arr, size);

    free(arr);

    return 0;
}
