// Function to execute the command
int exec_background_command(const char* cmd, const char* cwd) {
    pid_t child_pid;
    int status;

    // Fork a new process
    if ((child_pid = fork()) == -1) {
        perror("fork");
        return -1;
    }

    // Child process
    if (child_pid == 0) {
        // Set the working directory
        if (chdir(cwd)) {
            perror("chdir");
            exit(1);
        }

        // Execute the command
        if (execve(cmd, NULL, NULL) == -1) {
            perror("execve");
            exit(1);
        }
    } else {
        // Parent process
        // Wait for the child to finish
        waitpid(child_pid, &status, 0);

        return status;
    }

    return 0;
}

