    if (write(err_log_fd, timestamp, strlen(timestamp)) == -1) {
        perror("write");
    }

    if (write(err_log_fd, cmd, strlen(cmd)) == -1) {
        perror("write");
    }

    if (write(err_log_fd, " failed with status code: ", 29) == -1) {
        perror("write");
    }

    // Write the exit status
    char status_str[4];
    sprintf(status_str, "%d", status);
    write(err_log_fd, status_str, strlen(status_str));

    close(err_log_fd);

    return;
}

// Function to handle system resource monitoring and alerts
void monitor_system_resources(int* cpu_usage, int* memory_usage) {
    // Monitor CPU usage
    if (*cpu_usage > 80) {
        printf("CPU usage exceeded threshold!\n");
    }

    // Monitor memory usage
    if (*memory_usage > 90) {
        printf("Memory usage exceeded threshold!\n");
    }
}

// Function to execute the command with concurrent thread safety
void* execute_command(void* arg) {
    // Get the command and working directory from the argument
    struct cmd_arg* cmd_arg = (struct cmd_arg*)arg;

    int status = exec_background_command(cmd_arg->cmd, cmd_arg->cwd);

    // Log failure if the command execution failed
    log_failure(cmd_arg->cmd, status);

    return NULL;
}

int main(int argc, char** argv) {
    struct cmd_arg* cmd_arg = (struct cmd_arg*)malloc(sizeof(struct cmd_arg));
    cmd_arg->cmd = "your_command_here";
    cmd_arg->cwd = "/path/to/cwd";

    // Parse command-line arguments
    if (parse_args(argc, argv)) {
        return -1;
    }

    // Monitor system resources
    int cpu_usage = 0, memory_usage = 0;

    // Execute the command concurrently from multiple threads
    pthread_t thread_id[4];
    for (int i = 0; i < 4; i++) {
        if (pthread_create(&thread_id[i], NULL, execute_command, cmd_arg) != 0) {
            perror("pthread_create");
            return -1;
        }
    }

    // Wait for all threads to finish
    for (int i = 0; i < 4; i++) {
        pthread_join(thread_id[i], NULL);
    }

    free(cmd_arg);

    return 0;
}

struct cmd_arg {
    char* cmd;
    char* cwd;
};
