// Function to hash a given string using the SHA256 algorithm
unsigned char *hash_string(char *str) {
    // Initialize the SHA256 context
    SHA256_CTX sha256_ctx;

    // Calculate the length of the input string
    int len = strlen(str);

    // Update the SHA256 context with the input string
    SHA256_Update(&sha256_ctx, str, len);

    // Finalize the SHA256 calculation
    unsigned char *hash = (unsigned char *)malloc(32);
    SHA256_Final(hash, &sha256_ctx);

    return hash;
}

// Function to encrypt a given string using AES-256-CBC algorithm
unsigned char *encrypt_string(char *str) {
    // Initialize the AES context
    AES_KEY aes_key;

    // Generate a random initialization vector (IV)
    unsigned char iv[16];
    for(int i = 0; i < 16; i++) {
        iv[i] = rand() % 256;
    }

    // Encrypt the input string using AES-256-CBC algorithm
    unsigned char *encrypted = (unsigned char *)malloc(strlen(str) + 32);
    aes_cbc_encrypt((unsigned char*)str, encrypted, strlen(str), &aes_key, iv);

    return encrypted;
}

// Function to decrypt a given string using AES-256-CBC algorithm
char *decrypt_string(unsigned char *encrypted) {
    // Initialize the AES context
    AES_KEY aes_key;

    // Decrypt the input string using AES-256-CBC algorithm
    char *decrypted = (char *)malloc(strlen((char*)encrypted) + 1);
    aes_cbc_decrypt(encrypted, decrypted, strlen((char*)encrypted), &aes_key);

    return decrypted;
}

// Load and initialize OpenSSL library
void *load_openssl(void) {
    void *lib_openssl = dlopen(LIBRARY_NAME ".so", RTLD_LAZY);
    if (!lib_openssl) {
        printf("Error: %s\n", dlerror());
        exit(1);
    }

    // Initialize OpenSSL library
    int result = SSL_library_init();
    if (result != 0) {
        printf("Error: %d\n", result);
        exit(1);
    }

    return lib_openssl;
}

// Clean up after using the OpenSSL library
void cleanup(void *lib_openssl) {
    // Close and free the OpenSSL library
    int result = SSL_shutdown();
    if (result != 0) {
        printf("Error: %d\n", result);
    }

    dlclose(lib_openssl);
}
