```c
// nfapi_cache_manager.h
#ifndef NFAPI_CACHE_MANAGER_H
#define NFAPI_CACHE_MANAGER_H

#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int size;
    void **cache_entries;
} cache_t;

int init_cache(int size);
void *get_from_cache(const char *key);
int set_in_cache(void *data, const char *key);
int expire_cache_entry(const char *key);

// nfapi_cache_manager.c
#include "nfapi_cache_manager.h"

cache_t *cache = NULL;
pthread_mutex_t cache_mutex = PTHREAD_MUTEX_INITIALIZER;

int init_cache(int size) {
    // Initialize the cache with a specified size
    if (size <= 0) return -1;
    cache = malloc(sizeof(cache_t));
    cache->size = size;
    cache->cache_entries = malloc(size * sizeof(void *));
    return 0;
}

void *get_from_cache(const char *key) {
    // Retrieve an entry from the cache using a given key
    pthread_mutex_lock(&cache_mutex);
    for (int i = 0; i < cache->size; i++) {
        if (strcmp((char *)cache->cache_entries[i], key) == 0) {
            void *entry = cache->cache_entries[i];
            pthread_mutex_unlock(&cache_mutex);
            return entry;
        }
    }
    pthread_mutex_unlock(&cache_mutex);
    return NULL;
}

int set_in_cache(void *data, const char *key) {
    // Set a new entry in the cache with a given key and data
    pthread_mutex_lock(&cache_mutex);
    for (int i = 0; i < cache->size; i++) {
        if (strcmp((char *)cache->cache_entries[i], key) == 0) {
            // Update existing entry
            cache->cache_entries[i] = data;
            pthread_mutex_unlock(&cache_mutex);
            return 0;
        }
    }
    // Add new entry to the end of the cache
    for (int i = 0; i < cache->size; i++) {
        if (!cache->cache_entries[i]) {
            cache->cache_entries[i] = data;
            pthread_mutex_unlock(&cache_mutex);
            return 0;
        }
    }
    // Cache is full, handle error case
    pthread_mutex_unlock(&cache_mutex);
    return -1;
}

int expire_cache_entry(const char *key) {
    // Remove an entry from the cache using a given key
    pthread_mutex_lock(&cache_mutex);
    for (int i = 0; i < cache->size; i++) {
        if (strcmp((char *)cache->cache_entries[i], key) == 0) {
            free(cache->cache_entries[i]);
            cache->cache_entries[i] = NULL;
            pthread_mutex_unlock(&cache_mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&cache_mutex);
    return -1;
}

#endif // NFAPI_CACHE_MANAGER_H
