public class conditionalLogError {
    private static final int MAX_RETRIES = 5;
    private static final long MAX_WAIT_TIME = 30 * 1000; // 30 seconds

    public static void logError(boolean condition, String... messageArgs) throws IOException {
        if (!condition) return;

        String[] metadata = new String[] { "{\"level\": \"ERROR\", \"message\": \"" };
        for (String arg : messageArgs) {
            metadata[1] += arg + "\", ";
        }
        metadata[1] = metadata[1].substring(0, metadata[1].length() - 2);
        metadata[2] = "}", "{\"timestamp\": \"" + System.currentTimeMillis() + "\", \"source\": \"...\"}";

        for (int i = 0; i < MAX_RETRIES || i == 0; ) {
            try {
                // Call the external logging system
                logToExternalSystem(metadata);
                return;
            } catch (IOException e) {
                if (i >= MAX_RETRIES) {
                    // If retries exceed threshold, notify administrators
                    notifyAdmins(e);
                    throw e;
                }
                // Wait and retry
                try {
                    Thread.sleep(i * 5000); // exponential backoff in milliseconds
                } catch (InterruptedException ie) {
                    Thread.currentThread().interrupt();
                    return;
                }
            }
        }
    }

