    .output_file = "log.txt",
    .buffer_size = 1024,
    .mutex = PTHREAD_MUTEX_INITIALIZER
};

// Log message structure
typedef struct {
    log_level_t level;
    char *message;
} log_message_t;

// Log buffer structure
typedef struct {
    int size;
    log_message_t *messages;
} log_buffer_t;

// Initialize logging configuration from environment variables or default settings
void init_logging_config() {
    // Load configuration from environment variables or default settings
}

// Update logging configuration dynamically
void update_logging_config(int level, log_format_t format) {
    pthread_mutex_lock(&config.mutex);
    config.level = level;
    config.format = format;
    pthread_mutex_unlock(&config.mutex);
}

// Log message with given log level and format
void log_message(log_level_t level, const char *message) {
    if (level > config.level) return; // Only log messages with level >= current log level

    log_message_t log_msg = {level, message};

    pthread_mutex_lock(&config.mutex);
    log_buffer_t *buffer = get_log_buffer();
    buffer->messages[buffer->size++] = &log_msg;
    if (buffer->size >= config.buffer_size) {
        // Log buffer overflow: send logs to external service and reset buffer
    }
    pthread_mutex_unlock(&config.mutex);
}

// Write log messages to file or external service asynchronously
