using namespace std;

class SensorData {
public:
    string source;
    int value;

    SensorData(string src, int val) : source(src), value(val) {}
};

class DataProcessor {
public:
    queue<SensorData> dataQueue;
    map<string, function<void(SensorData)>> processors;

    void addProcessor(string name, function<void(SensorData)> processor) {
        processors[name] = processor;
    }

    void process() {
        while (true) {
            SensorData data = dataQueue.front();
            dataQueue.pop();

            for (auto& proc : processors) {
                proc.second(data);
            }
        }
    }

    void start() {
        thread t(&DataProcessor::process, this);
        t.detach();
    }
};

class DataWriter {
public:
    string filename;
    ofstream file;

    DataWriter(string filename) : filename(filename), file(filename) {}

    void write(SensorData data) {
        file << data.source << ":" << data.value << endl;
        file.flush();
    }

    ~DataWriter() {
        file.close();
    }
};

int main() {
    DataProcessor processor;
    processor.addProcessor("Sensor1", [](SensorData data) { cout << "Sensor 1: " << data.value << endl; });
    processor.addProcessor("Sensor2", [](SensorData data) { cout << "Sensor 2: " << data.value << endl; });

    processor.start();

    DataWriter writer("data.txt");

    thread t([&writer]() {
        while (true) {
            SensorData data;
            // simulate sensor data
            data.source = "Sensor1";
            data.value = rand() % 100;

            writer.write(data);

            this_thread::sleep_for(chrono::milliseconds(100));
        }
    });

    t.detach();

    return 0;
}
