    std::condition_variable conditionVariable_;
    std::queue<SensorData> sensorDataQueue_;

public:
    void pushData(SensorData data) {
        std::unique_lock<std::mutex> lock(mutex_);
        sensorDataQueue_.push(data);
        conditionVariable_.notify_all();
    }

    SensorData popData() {
        std::unique_lock<std::mutex> lock(mutex_);
        while (sensorDataQueue_.empty()) {
            conditionVariable_.wait(lock);
