#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <mysql/mysql.h>

typedef struct {
    int offset;
    char key[16];
    long value;
} record;

record* parse_record(char* buffer, int len) {
    // Parse and validate integers
    int offset = 0;
    char* p = buffer;
    while (*p != '\0') {
        if (sscanf(p, "%x", &offset) == 1)
            break;
        else {
            printf("Invalid integer format at offset %d\n", p - buffer);
            return NULL;
        }
        p++;
    }

    // Allocate memory for record structure
    record* rec = (record*)malloc(sizeof(record));
    if (!rec) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    // Copy key and value
    strncpy(rec->key, p, 16);
    rec->value = strtol(p + 17, NULL, 10);

    return rec;
}

int main() {
    int sockfd, connfd;
    struct sockaddr_in servaddr, cliaddr;
    socklen_t clilen;

    // Create socket
    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("socket creation failed");
        return -1;
    }

    // Set address and port number
    servaddr.sin_family = AF_INET;
    servaddr.sin_addr.s_addr = INADDR_ANY;
    servaddr.sin_port = htons(8080);

    // Bind socket to the specified IP address and port number
    if (bind(sockfd, (struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        perror("binding failed");
        return -1;
    }

    // Listen for incoming connections
    listen(sockfd, 3);
    clilen = sizeof(cliaddr);

    while (1) {
        // Accept connection from client
        connfd = accept(sockfd, (struct sockaddr *)&cliaddr, &clilen);
        if (connfd < 0) {
            perror("accept failed");
            continue;
        }

        char buffer[1024];
        int len;

        // Receive data from the client
        while ((len = recv(connfd, buffer, 1024, 0)) > 0) {
            record* rec = parse_record(buffer, len);
            if (!rec)
                continue;

            // Connect to database
            MYSQL *mysql;
            mysql_init(&mysql);
            mysql_real_connect(&mysql, "localhost", "username", "password", "database", 0);

            // Insert data into the database
            if (mysql_query(&mysql, "INSERT INTO table_name VALUES (rec->offset, rec->key, rec->value)") != 0) {
                printf("Error inserting data into the database: %s\n", mysql_error(&mysql));
                continue;
            }

            // Close database connection
            mysql_close(&mysql);
        }

        close(connfd);
    }

    return 0;
}
