from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.backends import default_backend
from requests.auth import HTTPBasicAuth
from requests.exceptions import ConnectionError, ReadTimeout
from concurrent.futures import ThreadPoolExecutor
from queue import Queue

class ConfigurationManager:
    def __init__(self):
        self.secrets_service = None
        self.cache = {}
        self.logger = logging.getLogger(__name__)
        self.logger.setLevel(logging.INFO)
        self.logger.addHandler(logging.StreamHandler())

    def set_secrets_service(self, service_url, token):
        self.secrets_service = {"url": service_url, "token": token}

    def get_secret(self, key):
        if not self.secrets_service:
            return None
        try:
            response = requests.get(f"{self.secrets_service['url']}/secrets/{key}", auth=HTTPBasicAuth(self.secrets_service["token"], ""))
            if response.status_code == 200:
                return response.json()["value"]
            else:
                self.logger.warning(f"Failed to retrieve secret {key}: {response.text}")
                return None
        except (ConnectionError, ReadTimeout) as e:
            self.logger.error(f"Error fetching secret {key}: {e}")
            return None

    def update_kickstart_template(self, template_path, params):
        if not os.path.exists(template_path):
            raise FileNotFoundError(f"{template_path} does not exist")

        try:
            with open(template_path) as f:
                template = f.read()

                for key, value in params.items():
                    template = re.sub(rf"\{\{ {key} \}\}", str(value), template)

                with open(template_path, "w") as f:
                    f.write(template)
        except Exception as e:
            self.logger.error(f"Error updating kickstart template: {e}")

    def cache_update(self, key, value):
        if not self.cache.get(key):
            self.cache[key] = value
            return True
        return False

    def handle_error(self, error):
        if isinstance(error, Exception):
            self.logger.error(f"Error occurred: {error.__class__.__name__}: {str(error)}")

            # Retry up to 5 times in case of transient issues
            for i in range(1, 6):
                try:
                    self.update_kickstart_template()
                    return
                except Exception as e:
                    if i == 5:
                        raise e

        else:
            self.logger.warning(f"Error occurred: {error}")

    def process_config(self, config_path):
        try:
            with open(config_path) as f:
                config = json.load(f)

                for key, value in config.items():
                    if isinstance(value, dict):
                        for nested_key, nested_value in value.items():
                            self.update_kickstart_template(template_path=os.path.join(os.getcwd(), "templates", f"{key}.kickstart"), params={nested_key: nested_value})
                    else:
                        self.update_kickstart_template(template_path=os.path.join(os.getcwd(), "templates", f"{key}.kickstart"), params={key: value})
        except Exception as e:
            self.handle_error(e)

    def run(self):
        with ThreadPoolExecutor(max_workers=5) as executor:
            for config in os.listdir("configs"):
                if not config.startswith("."):
                    future = executor.submit(self.process_config, os.path.join("configs", config))

                    # Handle concurrent futures
                    try:
                        result = future.result()
                    except Exception as e:
                        self.handle_error(e)

        self.logger.info(f"Configuration updates complete")
