    semaphore* new_semaphore = (semaphore*)malloc(sizeof(semaphore));
    if (!new_semaphore) {
        fprintf(stderr, "Memory allocation failed for semaphore creation.\n");
        return NULL;
    }
    new_semaphore->value = value;
    pthread_mutex_init(&new_semaphore->lock, NULL);
    return new_semaphore;
}

void destroy_semaphore(semaphore* sem) {
    pthread_mutex_destroy(&sem->lock);
    free(sem);
}

int get_semaphore_value(semaphore* sem) {
    int result;
    pthread_mutex_lock(&sem->lock);
    result = sem->value;
    pthread_mutex_unlock(&sem->lock);
    return result;
}

void decrement_semaphore_value(semaphore* sem) {
    pthread_mutex_lock(&sem->lock);
    --sem->value;
    pthread_mutex_unlock(&sem->lock);
}

void increment_semaphore_value(semaphore* sem) {
    pthread_mutex_lock(&sem->lock);
    ++sem->value;
    pthread_mutex_unlock(&sem->lock);
}

int acquire_semaphore(semaphore* sem, int timeout) {
    int result = 0;
    pthread_mutex_lock(&sem->lock);
    if (sem->value > 0) {
        --sem->value;
        result = 1;
    } else {
        pthread_cond_wait(&sem->cond, &sem->lock);
        ++sem->value;
    }
    pthread_mutex_unlock(&sem->lock);
    return result;
}

void release_semaphore(semaphore* sem) {
    pthread_mutex_lock(&sem->lock);
    ++sem->value;
    pthread_mutex_unlock(&sem->lock);
}

int resize_semaphores(int new_size) {
    int old_size = SEMAPHORE_POOL_SIZE;
    SEMAPHORE_POOL_SIZE = new_size;
    if (new_size > old_size) {
        for (int i = old_size; i < new_size; ++i) {
            semaphore* new_semaphore = create_semaphore(0);
            if (!new_semaphore) {
                return -1;
            }
            pthread_rwlock_wrlock(&pool_lock);
            if (semaphore_pool == NULL || i >= SEMAPHORE_POOL_SIZE) {
                free(semaphore_pool);
                semaphore_pool = new_semaphore;
            } else {
                int j;
                for (j = 0; j < SEMAPHORE_POOL_SIZE; ++j) {
                    if (semaphore_pool[j] == NULL) {
                        semaphore_pool[j] = new_semaphore;
                        break;
                    }
                }
                for (; j < SEMAPHORE_POOL_SIZE; ++j) {
                    free(semaphore_pool[j]);
                    semaphore_pool[j] = NULL;
                }
            }
            pthread_rwlock_unlock(&pool_lock);
        }
    } else if (new_size < old_size) {
        for (int i = new_size; i > 0; --i) {
            int j;
            for (j = 0; j < SEMAPHORE_POOL_SIZE; ++j) {
                if (semaphore_pool[j] != NULL && --i == 0) {
                    destroy_semaphore(semaphore_pool[j]);
                    semaphore_pool[j] = NULL;
                    break;
                }
            }
        }
    }
    return 0;
}

int main() {
    // Initialize logging and pool
    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file.\n");
        return -1;
    }
    semaphore_pool = (semaphore*)malloc(SEMAPHORE_POOL_SIZE * sizeof(semaphore));
    for (int i = 0; i < SEMAPHORE_POOL_SIZE; ++i) {
        pthread_mutex_init(&semaphore_pool[i].lock, NULL);
    }

    // Create semaphores and use them
    semaphore* s1 = create_semaphore(5);
    if (!s1) {
        return -1;
    }
    int val = get_semaphore_value(s1);
    decrement_semaphore_value(s1);
    release_semaphore(s1);

    // Log semaphore operations
    time_t current_time = time(NULL);
    fprintf(log_file, "%lu: Semaphore created with value %d.\n", current_time, val);
    fprintf(log_file, "%lu: Decrementing semaphore value.\n", current_time);
    fprintf(log_file, "%lu: Releasing semaphore.\n", current_time);

    // Resize semaphore pool
    if (resize_semaphores(2000) != 0) {
        return -1;
    }

    // Destroy semaphores and logging
    for (int i = 0; i < SEMAPHORE_POOL_SIZE; ++i) {
        destroy_semaphore(semaphore_pool[i]);
    }
    free(semaphore_pool);
    fclose(log_file);

    return 0;
}
