package com.example.logging.service;

import java.util.ArrayList;
import java.util.List;
import org.apache.commons.lang3.StringUtils;
import ch.qos.logback.classic.Logger;
import ch.qos.logback.core.StatusPrinter;
import com.amazonaws.services.cloudwatch.CloudWatch;
import com.amazonaws.services.cloudwatch.model.Dimension;
import com.amazonaws.services.cloudwatch.model.MetricData;
import com.amazonaws.services.cloudwatch.model.StandardUnit;
import com.example.logging.service.config.LogConfig;
import com.example.logging.service.handler.AwsCloudWatchHandler;
import com.example.logging.service.handler.ElasticSearchHandler;
import com.example.logging.service.handler.PrometheusHandler;
import com.google.common.collect.ImmutableMap;

public class LoggingService {
    private final Logger logger = (Logger) StatusPrinter.getInstance();
    private final LogConfig logConfig;
    private final List<LogHandler> handlers;

    public LoggingService(LogConfig logConfig) {
        this.logConfig = logConfig;
        this.handlers = new ArrayList<>();
        // Initialize logging handlers
        initLoggingHandlers();
    }

    private void initLoggingHandlers() {
        if (logConfig.isAwsCloudWatchEnabled()) {
            handlers.add(new AwsCloudWatchHandler(logConfig.getAwsCloudWatchEndpoint(), logConfig.getAwsRegion()));
        }
        if (logConfig.isElasticSearchEnabled()) {
            handlers.add(new ElasticSearchHandler(logConfig.getElasticSearchUrl()));
        }
        if (logConfig.isPrometheusEnabled()) {
            handlers.add(new PrometheusHandler(logConfig.getPrometheusUrl()));
        }
    }

    public void log(String logLevel, String message) {
        // Check log level and handle accordingly
        if (logLevel.equals("ERROR")) {
            logger.error(message);
        } else if (logLevel.equals("WARNING")) {
            logger.warn(message);
        } else if (logLevel.equals("INFO")) {
            logger.info(message);
        } else if (logLevel.equals("DEBUG")) {
            logger.debug(message);
        }

        // Handle log messages for each logging handler
        handlers.forEach(handler -> handler.handleLog(logLevel, message));
    }

    public void close() {
        // Close logging handlers
        handlers.forEach(LogHandler::close);
    }
}

interface LogHandler {
    void handleLog(String logLevel, String message);

    void close();
}
