    public static class QueueManager {
        private ConcurrentLinkedQueue<Runnable> queue;

        public QueueManager(int capacity) {
            this.queue = new ConcurrentLinkedQueue<>();
        }

        public void put(Runnable task) {
            queue.add(task);
        }

        public void drain() {
            while (!queue.isEmpty()) {
                Runnable task = queue.poll();
                if (task != null) {
                    executor.execute(task);
                }
            }
        }
    }

    private QueueManager queueManager;

    public DynamicNetworkCommunication(int maxPoolSize, long keepAliveTime, int queueCapacity) {
        this.executor = (ThreadPoolExecutor) Executors.newFixedThreadPool(maxPoolTime);
        this.executorService = Executors.newCachedThreadPool();
        this.executor.setKeepAliveTime(keepAliveTime, TimeUnit.MILLISECONDS);
        this.queueManager = new QueueManager(queueCapacity);
    }

    public void execute() {
        // Execute the request and handle errors
    }

