// FilterAndPaginate.js
import { useState, useEffect } from 'react';
import WebSocket from 'ws';

const FILTERS = {
  ATTRIBUTES: 'attributes',
  ELEMENT_TYPES: 'elementTypes',
  CUSTOM_ATTRIBUTES: 'customAttributes'
};

const DEFAULT_PAGE_SIZE = 10;

function filterAndPaginate({
  nodeTree,
  filters = [],
  pageSize = DEFAULT_PAGE_SIZE
}) {
  const [filteredNodes, setFilteredNodes] = useState([]);
  const [pageNodes, setPageNodes] = useState([]);
  const [currentPageIndex, setCurrentPageIndex] = useState(0);
  const [lastFilteredNode, setLastFilteredNode] = useState(null);

  useEffect(() => {
    const filteredNodes = nodeTree.filter((node) => {
      for (const filter of filters) {
        switch (filter.type) {
          case FILTERS.ATTRIBUTES:
            return getAttributeValue(node, filter.attributeName) === filter.value;
          case FILTERS.ELEMENT_TYPES:
            return node.nodeName === filter.elementType;
          case FILTERS.CUSTOM_ATTRIBUTES:
            return getNodeCustomAttribute(node, filter.customAttributeName) === filter.value;
        }
      }
      return true; // No filters applied, return all nodes
    });

    const pageNodes = filteredNodes.slice(currentPageIndex * pageSize, (currentPageIndex + 1) * pageSize);

    setFilteredNodes(filteredNodes);
    setPageNodes(pageNodes);
  }, [nodeTree, filters, currentPageIndex]);

  useEffect(() => {
    const ws = new WebSocket('wss://your-websocket-url.com');

    ws.onmessage = (event) => {
      const data = JSON.parse(event.data);
      if (data.type === 'update') {
        setLastFilteredNode(data.node);
        // Handle updates
      } else if (data.type === 'pagination') {
        // Handle pagination changes
      }
    };

    return () => {
      ws.close();
    };
  }, []);

  const handlePageChange = (index) => {
    setCurrentPageIndex(index);
  };

  const getAttributeValue = (node, attributeName) => node.getAttribute(attributeName);

  const getNodeCustomAttribute = (node, customAttributeName) => node.dataset[customAttributeName];

  return {
    filteredNodes,
    pageNodes,
    currentPageIndex,
    lastFilteredNode,
    handlePageChange
  };
}

export default filterAndPaginate;
