            },
            'handlers': {
                'console': {'class': 'logging.StreamHandler', 'formatter': 'default'},
                'file': {'class': 'logging.FileHandler', 'filename': 'logs.log', 'formatter': 'default'}
            },
            'loggers': {
                'root': {'level': 'DEBUG', 'handlers': ['console', 'file']}
            }
        })

    def start_processing(self):
        self.configure_logging()
        while True:
            # Read logs from Kafka
            log_data = self.kafka_producer.poll(timeout_ms=1000).poll()

            if log_data is not None and len(log_data) > 0:
                for log in log_data.values():
                    self.process_log(log)

    def anonymize_sensitive_info(self, log_data):
