        // Define a deduplication strategy (e.g., using a Set or a HashSet)
        Set<String> uniqueEvents = new HashSet<>();

        while (true) {
            // Consume events from Kafka
            ConsumerRecords<String, String> records = consumer.poll(100);

            for (ConsumerRecord<String, String> record : records) {
                String event = record.value();
                if (!uniqueEvents.add(event)) {
                    System.out.println("Duplicate event detected: " + event);
                }

                // Implement rate-limiting using a sliding window approach
                long now = System.currentTimeMillis();
                int count = 0;
                for (String previousEvent : uniqueEvents) {
                    if (now - Long.parseLong(previousEvent.split(":")[1]) <= 1000) {
                        count++;
                    }
                }
                if (count > 10) {
                    Thread.sleep(1000);
                }

                // Process events
                processEvent(event);

            }
        }
    }

