```kotlin
import java.util.*
import org.apache.kafka.clients.consumer.*

fun main() {
    val props = Properties()
    props.put("bootstrap.servers", "localhost:9092")
    props.put("key.deserializer", StringDeserializer::class.java.name)
    props.put("value.deserializer", StringDeserializer::class.java.name)
    val consumer = KafkaConsumer(props)

    // Subscribe to the desired topic
    consumer.subscribe(listOf("topic1", "topic2"))

    // Define a deduplication strategy (e.g., using a Set or a HashSet)
    val uniqueEvents: MutableSet<String> = mutableSetOf()

    while (true) {
        // Consume events from Kafka
        val records = consumer.poll(100)

        for (record in records) {
            val event = record.value()
            if (!uniqueEvents.add(event)) {
                println("Duplicate event detected: $event")
            }

            // Implement rate-limiting using a sliding window approach
            val now = System.currentTimeMillis()
            var count = 0
            for (previousEvent in uniqueEvents) {
                if (now - previousEvent.split(":")[1].toLong() <= 1000) {
                    count++
                }
            }
            if (count > 10) {
                Thread.sleep(1000)
            }

            // Process events
            processEvent(event)
        }
    }
