// https://crates.io/crates/http-client
use http::Uri;
use tokio::sync::{mpsc, mpsc::channel};
use tracing::{error, info, warn};

#[derive(Debug)]
pub enum ClientError {
    HttpError(http::Error),
    IoError(std::io::Error),
    Other(String),
}

impl std::fmt::Display for ClientError {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        match self {
            ClientError::HttpError(err) => err.fmt(f),
            ClientError::IoError(err) => err.fmt(f),
            ClientError::Other(msg) => msg.fmt(f),
        }
    }
}

impl std::error::Error for ClientError {}

async fn send_request(uri: &Uri, request: http::Request) -> Result<String, ClientError> {
    let client = reqwest::blocking::ClientBuilder::new()
        .timeout(std::time::Duration::from_millis(5000)) // timeout
        .connect_timeout(std::time::Duration::from_millis(2000)) // connect timeout
        .follow_redirect(true) // follow redirects
        .gzip(false) // do not gzip response body
        .build()
        .unwrap();

    match client.get_uri(uri).send().await {
        Ok(response) => {
            let status_code = response.status();
            if status_code.is_success() {
                let body = response.text().await?;
                Ok(body)
            } else {
                let body = response.text().await?;
                Err(ClientError::HttpError(http::Error::new(
                    status_code,
                    format!("Failed to retrieve resource: {}", body),
                )))
            }
        }
        Err(err) => Err(ClientError::IoError(err)),
    }
}

#[tokio::main]
async fn main() {
    let (tx, rx) = mpsc::channel(10);

    // Start the client
    for _ in 0..5 {
        let request = http::Request::get("https://example.com");
        tx.send(request).await.unwrap();
    }

    loop {
        match rx.recv().await {
            Ok(req) => println!("Received: {}", req),
            Err(_) => break,
        }
    }
}
```

