    {
        private readonly Dictionary<string, ValueRange<IValueGenerator>> _valueRanges;
        private readonly object _lock = new object();

        public DynamicValueManager()
        {
            _valueRanges = new Dictionary<string, ValueRange<IValueGenerator>>();
        }

        public void AddValueRange(string name, IValueGenerator generator, bool inclusive = false, bool exclusive = true)
