    public class TripleDesEncryption
    {
        private readonly int _keySize = 24; // Default key size in bytes
        private readonly int _ivSize = 8; // Default IV size in bytes

        public void SetKey(string key, string iv)
        {
            if (string.IsNullOrEmpty(key))
                throw new ArgumentException("Key cannot be null or empty", nameof(key));

            if (string.IsNullOrEmpty(iv))
                throw new ArgumentException("IV cannot be null or empty", nameof(iv));

            _keySize = Convert.ToInt32(key.Length);
            _ivSize = Convert.ToInt32(iv.Length);
        }

        public byte[] Encrypt(byte[] plaintext, string key, string iv)
        {
            using (TripleDESCryptoServiceProvider tripleDes = new TripleDESCryptoServiceProvider())
            {
                tripleDes.Key = Encoding.ASCII.GetBytes(key);
                tripleDes.IV = Encoding.ASCII.GetBytes(iv);

                using (MemoryStream ms = new MemoryStream())
                {
                    using (CryptoStream cs = new CryptoStream(ms, tripleDes.CreateEncryptor(), CryptoStreamMode.Write))
                    {
                        cs.Write(plaintext, 0, plaintext.Length);
                    }
                    return ms.ToArray();
                }
            }
        }

        public byte[] Decrypt(byte[] ciphertext, string key, string iv)
        {
            using (TripleDESCryptoServiceProvider tripleDes = new TripleDESCryptoServiceProvider())
            {
                tripleDes.Key = Encoding.ASCII.GetBytes(key);
                tripleDes.IV = Encoding.ASCII.GetBytes(iv);

                using (MemoryStream ms = new MemoryStream(ciphertext))
                {
                    using (CryptoStream cs = new CryptoStream(ms, tripleDes.CreateDecryptor(), CryptoStreamMode.Write))
                    {
                        byte[] decryptedBytes = new byte[ms.Length];
                        ms.Position = 0;
                        cs.Read(decryptedBytes, 0, decryptedBytes.Length);
