    [Route("api/[controller]")]
    public class DecryptController : ControllerBase
    {
        private readonly ILogger<DecryptController> _logger;
        private readonly IConfiguration _config;
        private readonly int _maxAttemptedDecryptionFailures = 5;

        public DecryptController(ILogger<DecryptController> logger, IConfiguration config)
        {
            _logger = logger;
            _config = config;
        }

        [HttpPost]
        [Route("decrypt")]
        public IActionResult Decrypt([FromBody]DecryptRequest request)
        {
            try
            {
                // Get the key and IV from configuration or a secure storage
                var key = Encoding.UTF8.GetBytes(_config["AES_KEY"]);
                var iv = Convert.FromBase64String(_config["AES_IV"]);

                using (var aes = Aes.Create())
                {
                    aes.Key = key;
                    aes.IV = iv;

                    // Decrypt the ciphertext
                    var decryptedBytes = DecryptCiphertext(aes, request.Ciphertext);

                    // Return the decrypted plaintext as a byte array
                    return new FileContentResult(decryptedBytes, "application/octet-stream")
                    {
                        FileDownloadName = "decrypted_data.bin"
                    };
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error decrypting ciphertext");

                // Handle decryption failures
                if (_maxAttemptedDecryptionFailures-- > 0)
                {
                    return StatusCode(500, "Failed to decrypt ciphertext. Try again later.");
                }
                else
                {
                    return StatusCode(500, "Maximum decryption attempts exceeded. Contact administrator.");
                }
            }
        }

        private byte[] DecryptCiphertext(Aes aes, byte[] ciphertext)
        {
            using (var memoryStream = new MemoryStream())
            {
                using (var cryptoStream = new CryptoStream(memoryStream, aes.CreateDecryptor(), CryptoStreamMode.Write))
                {
                    cryptoStream.Write(ciphertext, 0, ciphertext.Length);
                    cryptoStream.FlushFinalBlock();
                }

                return memoryStream.ToArray();
            }
        }
    }

    public class DecryptRequest
    {
        public byte[] Ciphertext { get; set; }
    }
}
