    component_collection_t* collection = malloc(sizeof(component_collection_t));
    if (!collection) return NULL;
    collection->components = malloc(initial_capacity * sizeof(struct component));
    if (!collection->components) {
        free(collection);
        return NULL;
    }
    collection->capacity = initial_capacity;
    collection->used = 0;
    return collection;
}

void component_collection_free(component_collection_t* collection) {
    for (size_t i = 0; i < collection->used; i++) {
        free(collection->components[i].name);
    }
    free(collection->components);
    free(collection);
}
