// Define the structure for DataRecord
typedef struct {
    long timestamp;
    unsigned char *payload;
    int payload_size;
    void *sensor_config;
} DataRecord;

// Define the linked list node structure
typedef struct Node {
    DataRecord *data;
    struct Node *next;
} Node;

// Function to create a new DataRecord
DataRecord* data_record_create(long timestamp, unsigned char *payload, int payload_size, void *sensor_config) {
    DataRecord *record = (DataRecord*)malloc(sizeof(DataRecord));
    record->timestamp = timestamp;
    record->payload = payload;
    record->payload_size = payload_size;
    record->sensor_config = sensor_config;
    return record;
}

// Function to create a new linked list node
Node* node_create(DataRecord *data) {
    Node *node = (Node*)malloc(sizeof(Node));
    node->data = data;
    node->next = NULL;
    return node;
}

// Function to insert a new DataRecord at the end of the linked list
void linked_list_insert(Node **head, DataRecord *data) {
    Node *new_node = node_create(data);
    if (*head == NULL) {
        *head = new_node;
    } else {
        Node *curr = *head;
        while (curr->next != NULL) {
            curr = curr->next;
        }
        curr->next = new_node;
    }
}

// Function to delete a DataRecord from the linked list
void linked_list_delete(Node **head, long timestamp) {
    if (*head == NULL) return;

    Node *curr = *head;
    Node *prev = NULL;
    while (curr != NULL && curr->data->timestamp != timestamp) {
        prev = curr;
        curr = curr->next;
    }

    if (curr != NULL) {
        DataRecord *data = curr->data;
        free(data);
        if (prev == NULL) {
            *head = curr->next;
        } else {
            prev->next = curr->next;
        }
        free(curr);
    }
}

// Function to iterate over the linked list and print each DataRecord
void linked_list_iterate(Node *head) {
    while (head != NULL) {
        DataRecord *data = head->data;
        printf("Timestamp: %ld, Payload Size: %d\n", data->timestamp, data->payload_size);
        head = head->next;
    }
}

int main() {
    // Create a new linked list
    Node *head = NULL;

    // Create some DataRecords and insert them into the linked list
    long timestamp1 = 1643723400;
    unsigned char *payload1 = "Payload 1";
    int payload_size1 = strlen(payload1);
    void *sensor_config1 = "Sensor Config 1";
    DataRecord *data1 = data_record_create(timestamp1, payload1, payload_size1, sensor_config1);
    linked_list_insert(&head, data1);

    long timestamp2 = 1643723410;
    unsigned char *payload2 = "Payload 2";
    int payload_size2 = strlen(payload2);
    void *sensor_config2 = "Sensor Config 2";
    DataRecord *data2 = data_record_create(timestamp2, payload2, payload_size2, sensor_config2);
    linked_list_insert(&head, data2);

    // Print each DataRecord in the linked list
    linked_list_iterate(head);

    return 0;
}
