public class EventProcessorFramework implements Ordered {

    private final Logger logger = LoggerFactory.getLogger(EventProcessorFramework.class);

    @Autowired
    private ApplicationContext context;

    @Autowired
    private ConversionService conversionService;

    @Autowired
    private RestTemplate restTemplate;

