        KafkaConsumer<String, String> kafkaConsumer = new KafkaConsumer<>("localhost:9092", "event-topic");
        MqttClient mqttClient = MqttClient.create("tcp://localhost:1883");

        LinkedBlockingQueue<Runnable> queue = new LinkedBlockingQueue<>();

