// Define the DataRecord structure
typedef struct {
    time_t timestamp;
    char* payload;
    void* sensor_config;
} DataRecord;

// Define the linked list node structure
typedef struct _Node {
    DataRecord* data;
    struct _Node* next;
} Node;

// Define the linked list structure
typedef struct {
    Node* head;
    Node* tail;
    int size;
} LinkedList;

// Function to create a new linked list
LinkedList* linkedListCreate();

// Function to add a new node to the linked list
void linkedListAdd(LinkedList* list, DataRecord* data);

// Function to remove a node from the linked list
void linkedListRemove(LinkedList* list, DataRecord* data);

// Function to get the size of the linked list
int linkedListGetSize(LinkedList* list);

// Function to print the contents of the linked list
void linkedListPrint(LinkedList* list);

// Custom memory allocator for performance optimization and minimal fragmentation
void* custom_malloc(size_t size);
void custom_free(void* ptr, size_t size);

// Data compression scheme for binary payloads
int compress_payload(char* payload, int len);
char* decompress_payload(char* compressed_payload, int len);

// Implementation of the linked list management library

LinkedList* linkedListCreate() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    return list;
}

void linkedListAdd(LinkedList* list, DataRecord* data) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return; // Handle memory allocation failure
    node->data = data;
    node->next = NULL;

    if (!list->head) {
        list->head = node;
        list->tail = node;
    } else {
        list->tail->next = node;
        list->tail = node;
    }
    list->size++;
}

void linkedListRemove(LinkedList* list, DataRecord* data) {
    Node* current = list->head;
    Node* previous = NULL;

    while (current && current->data != data) {
        previous = current;
        current = current->next;
    }

    if (!current) return; // Node not found

    if (previous) {
        previous->next = current->next;
    } else {
        list->head = current->next;
    }

    if (list->tail == current) {
        list->tail = previous;
    }

    free(current);
    list->size--;
}

int linkedListGetSize(LinkedList* list) {
    return list->size;
}

void linkedListPrint(LinkedList* list) {
    Node* current = list->head;

    while (current) {
        printf("Timestamp: %ld, Payload: %s, Sensor Config: %p\n", current->data->timestamp, current->data->payload, current->data->sensor_config);
        current = current->next;
    }
}

