// Node.js
const express = require('express');
const app = express();
const server = require('http').createServer(app);
const io = require('socket.io')(server);

const usersOnline = {};
const chatHistory = [];
const userTyping = {};

app.use(express.json());

// Define a simple lock manager using Raft consensus algorithm
class LockManager {
  constructor(nodes) {
    this.nodes = nodes;
    this.currentLeader = null;
  }

  async acquireLock(key, timeout) {
    // Find the current leader node
    const leaderNode = await findLeader();

    if (!leaderNode) {
      // No leader found, try again after a short delay
      setTimeout(() => acquireLock(key, timeout), 100);
      return false;
    }

    // Send request to leader node to acquire lock
    const response = await sendRequest(leaderNode, 'acquire-lock', key);

    if (response === true) {
      // Lock acquired, update local state
      this.currentLock = key;
      return true;
    } else {
      // Lock not acquired, try again after a short delay
      setTimeout(() => acquireLock(key, timeout), 100);
      return false;
    }
  }

  async releaseLock(key) {
    // Find the current leader node
    const leaderNode = await findLeader();

    if (!leaderNode) {
      // No leader found, try again after a short delay
      setTimeout(() => releaseLock(key), 100);
      return false;
    }

    // Send request to leader node to release lock
    await sendRequest(leaderNode, 'release-lock', key);
  }
}

// Define the real-time collaborative text editor
class TextEditor {
  constructor() {
    this.document = '';
    this.lockManager = new LockManager([1, 2, 3]); // Initialize with 3 nodes

    server.listen(3000, () => {
      console.log('Server started on port 3000');
    });

    io.on('connection', (socket) => {
      console.log('Client connected');

      socket.on('join', (username) => {
        usersOnline[username] = socket;
      });

      socket.on('disconnect', () => {
        delete usersOnline[socket.username];
      });

      socket.on('message', (data) => {
        // Handle incoming message from client
        const { username, text } = data;

        if (!userTyping[username]) {
          // Add message to chat history and broadcast to all clients
          chatHistory.push({ username, text });
          io.emit('new-message', chatHistory);
        }
      });

      socket.on('typing', (username) => {
        userTyping[username] = true;
      });

      socket.on('stop-typing', (username) => {
        delete userTyping[username];
      });

      // Handle document updates from clients
      socket.on('update-document', (data) => {
        const { username, text } = data;

        if (!userTyping[username]) {
          // Acquire lock before updating the document
          LockManager.acquireLock('document-update', 1000).then((locked) => {
            if (locked) {
              this.document = text;
              io.emit('new-document', this.document);
              LockManager.releaseLock('document-update');
            }
          });
        }
      });
    });
}

const editor = new TextEditor();
```

This code establishes the foundation for a real-time collaborative text editor, incorporating a distributed lock manager using Raft consensus algorithm to manage concurrent access and ensure atomic document updates. It also includes a basic implementation of user typing indicators, chat history, and document updates.

Please note that this is a simplified example, and you will need to add more functionality, error handling, and performance optimization to create a robust and scalable system."]

