public:
    NFAPI_CRC_INDICATION_POPULATOR(size_t nEntries, size_t timeoutMS)
        : entries_(nEntries), timeout_(timeoutMS), queue_(), processed_(0) {}

    void addEntry(const NFAPI_CRC_INDICATION_PDU_T& entry) {
        std::unique_lock<std::mutex> lock(mutex_);
        queue_.emplace(entry);
    }

    bool process() {
        if (std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::high_resolution_clock::now().time_since_epoch()) > timeout_) {
            return false;
