    NF_API_Array* array = (NF_API_Array*) malloc(sizeof(NF_API_Array));
    if (!array) return NULL;

    array->arr = (NFAPI_CRC_INDICATION_PDU_T*) calloc(MAX_ENTRIES, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->arr) {
        free(array);
        return NULL;
    }

    array->capacity = MAX_ENTRIES;
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

// Add an entry to the dynamic array
int add_entry(NF_API_Array* array, NFAPI_CRC_INDICATION_PDU_T* entry) {
    if (pthread_mutex_lock(&array->lock)) {
        return -1;  // Error locking
    }

    if (array->count >= array->capacity) {  // Need to resize the array
        size_t new_capacity = array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_arr = (NFAPI_CRC_INDICATION_PDU_T*) realloc(array->arr, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!new_arr) {
            pthread_mutex_unlock(&array->lock);
            return -1;  // Error allocating memory
        }

        array->arr = new_arr;
        array->capacity = new_capacity;
    }

    array->arr[array->count] = *entry;
    array->count++;

    pthread_mutex_unlock(&array->lock);
    return 0;  // Success
}

// Check the integrity of the populated data
int verify_data(NF_API_Array* array) {
    for (size_t i = 0; i < array->count; i++) {
        if (!array->arr[i].RX_UE_INFORMATION_TAG || !array->arr[i].RNTI || !array->arr[i].CRC_INDICATION_REL8_TAG) {
            return -1;  // Error verifying data
        }
    }

    return 0;  // Data is valid
}

// Free the dynamic array
void free_array(NF_API_Array* array) {
    if (pthread_mutex_lock(&array->lock)) {
        return;  // Error locking
    }

    pthread_mutex_unlock(&array->lock);

    free(array->arr);
    free(array);
}
