// Define the structure NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    int data1;
    char data2[20];
} NFAPI_CRC_INDICATION_PDU_T;

// Function to initialize a dynamic array of NFAPI_CRC_INDICATION_PDU_T structures
void* init_array(int size) {
    void* arr = malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    return arr;
}

// Function to free the memory allocated for the dynamic array
void free_array(void* arr) {
    free(arr);
}

// Function to add a new element to the dynamic array concurrently
void add_element(void* arr, int index, NFAPI_CRC_INDICATION_PDU_T element) {
    ((NFAPI_CRC_INDICATION_PDU_T*)arr)[index] = element;
}

// Function to get an element from the dynamic array concurrently
NFAPI_CRC_INDICATION_PDU_T get_element(void* arr, int index) {
    return ((NFAPI_CRC_INDICATION_PDU_T*)arr)[index];
}

// Main function to demonstrate concurrent access and modification of the dynamic array
int main() {
    pthread_t threads[4]; // Create 4 threads for demonstration purposes

    // Initialize the dynamic array with a size of 1000
    void* arr = init_array(1000);

    // Start the threads, each performing a different task (concurrently accessing and modifying the array)
    for (int i = 0; i < 4; i++) {
        pthread_create(&threads[i], NULL, thread_function, arr);
    }

    // Wait for all threads to finish
    for (int i = 0; i < 4; i++) {
        pthread_join(threads[i], NULL);
    }

    // Free the memory allocated for the dynamic array
    free_array(arr);

    return 0;
}

// Function for each thread to perform a different task concurrently
void* thread_function(void* arg) {
    void* arr = arg; // Get the dynamic array pointer

    // Example task: Adding an element at index 500 and then getting it
    int index = 500;
    NFAPI_CRC_INDICATION_PDU_T element = {1, "Hello"};

    add_element(arr, index, element);
    NFAPI_CRC_INDICATION_PDU_T retrieved_element = get_element(arr, index);

    // Print the retrieved element to demonstrate successful concurrency
    printf("Thread %p: Retrieved element at index %d is {%d, %s}\n", pthread_self(), index, retrieved_element.data1, retrieved_element.data2);

    return NULL;
}
