// Event processing system class
class EventProcessor {
public:
    EventProcessor() : _cacheSize(10000), _cacheExpirationTime(60), _maxRetries(5) {}

    void processEvents(std::vector<Event> events) {
        for (auto& event : events) {
            if (_cache.containsKey(event.getId())) {
                // Cache hit, update timestamp
                _cache.get(event.getId()).timestamp = std::time(nullptr);
            } else {
                // Cache miss, add to cache and process
                _cache.put(event.getId(), event);
                processEvent(event);
            }
        }
    }

    void cacheEviction() {
        auto it = _cache.end();
        while (it != _cache.begin()) {
            if (std::time(nullptr) - _cache.get(it->first).timestamp > _cacheExpirationTime) {
                _cache.erase(it--);
                _cacheSize--;
            } else {
                break;
            }
        }
    }

    void periodicCacheRefresh() {
        std::thread refreshThread([this]() {
            while (true) {
                cacheEviction();
                std::this_thread::sleep_for(std::chrono::seconds(60));
            }
        });
        refreshThread.detach();
    }

private:
    int _cacheSize;
    int _cacheExpirationTime;
    int _maxRetries;

    // In-memory cache
