            void handleWrite(const boost::system::error_code& ec);

            // Handle incoming messages from the server
            void handleMessage(const std::string& message);

            // Asynchronous connection establishment and reconnection logic
            class Connection {
                public:
                    Connection(WebSocketClient* parent, 
                               const boost::asio::ip::tcp::endpoint& ep)
                                : parent_(parent), ep_(ep) {}

                    ~Connection() {
                        if (socket_.is_open()) {
                            socket_.close();
                        }
                    }

                    void start();
                    void stop();

                private:
                    WebSocketClient* parent_;
                    boost::asio::ip::tcp::socket socket_;
                    boost::asio::ip::tcp::endpoint ep_;
            };

            // Asynchronous message sending and receiving logic
            class MessageSender {
                public:
                    MessageSender(WebSocketClient* parent)
                        : parent_(parent) {}

                    void send(const std::string& message);
                    void receive();

                private:
                    WebSocketClient* parent_;
            };
    };
}
