#include <mutex>
#include <condition_variable>
#include <chrono>
#include <map>
#include <unordered_map>
#include <vector>
#include <queue>
#include <string>
#include <algorithm>

// Define the payment gateway API interface
class PaymentGatewayAPI {
public:
    virtual void processTransaction(const std::string& transactionId, const std::string& amount, const std::string& currency) = 0;
};

// Define the credit card transaction processor class
class CreditCardTransactionProcessor {
private:
    PaymentGatewayAPI* paymentGatewayAPI;
    std::mutex mutex;
    std::condition_variable conditionVariable;
    std::map<std::string, std::queue<std::pair<std::string, std::string>>> transactionQueue;
    int maxConcurrentTransactions = 500;

public:
    CreditCardTransactionProcessor(PaymentGatewayAPI* paymentGatewayAPI) : paymentGatewayAPI(paymentGatewayAPI) {}

    // Process a credit card transaction
    void processTransaction(const std::string& transactionId, const std::string& amount, const std::string& currency) {
        std::unique_lock<std::mutex> lock(mutex);

        // Add the transaction to the queue if it's not too full
        while (transactionQueue.size() >= maxConcurrentTransactions) {
            conditionVariable.wait(lock);
        }

        transactionQueue[transactionId].first = amount;
        transactionQueue[transactionId].second = currency;

        // Release the lock and let other threads process transactions
        lock.unlock();

        // Start a new thread to process the transaction
        std::thread([this, transactionId]() {
            // Process the transaction using the payment gateway API
            paymentGatewayAPI->processTransaction(transactionId, amount, currency);

            // Remove the transaction from the queue
            std::unique_lock<std::mutex> lock(mutex);
            transactionQueue.erase(transactionId);

            // Notify other threads that a transaction has been processed
            conditionVariable.notify_all();
        }).detach();

        // Wait for all transactions to be processed before exiting
        while (!transactionQueue.empty()) {
            std::this_thread::sleep_for(std::chrono::seconds(1));
        }
    }

    // Rate-limit the number of transactions processed per second
    void rateLimit(int maxTransactionsPerSecond) {
        static int currentTransactionCount = 0;
        static auto startTime = std::chrono::high_resolution_clock::now();

        if (currentTransactionCount >= maxTransactionsPerSecond) {
            auto endTime = std::chrono::high_resolution_clock::now();
            auto duration = std::chrono::duration_cast<std::chrono::seconds>(endTime - startTime);

            // Sleep for the remaining time before processing more transactions
            std::this_thread::sleep_for(std::chrono::seconds(duration.count() - maxTransactionsPerSecond));
        }

        currentTransactionCount++;
    }
};

