    int start = 0;

    for (int end = 1; end < arr.size(); ++end) {
        if (arr[end] == arr[start]) {
            start = end;
        } else {
            disjointCount++;
            std::cout << "Disjoint pair: (" << arr[start] << ", " << arr[end]
