    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_ind_rel8;
    uint8_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

// Caching mechanism using a linked list
struct CacheNode {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct CacheNode* next;
};

typedef struct CacheNode* PduCache;

PduCache cache_head = NULL;
int cache_size = 0;

void insert_cache(NFAPI_CRC_INDICATION_PDU_T pdu) {
    PduCache new_node = (PduCache)malloc(sizeof(struct CacheNode));
    new_node->pdu = pdu;
    new_node->next = cache_head;
    cache_head = new_node;
    cache_size++;
}

NFAPI_CRC_INDICATION_PDU_T* find_in_cache(RNTI rnti) {
    PduCache current = cache_head;
    while (current != NULL) {
        if (current->pdu.rnti == rnti) {
            return &current->pdu;
        }
        current = current->next;
    }
    return NULL;
}

void validate_rnti(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    PduCache current = cache_head;
    while (current != NULL) {
        if (current->pdu.rnti == pdu->rnti) {
            // Duplicate RNTI found, handle accordingly
            printf("Duplicate RNTI detected: %x\n", pdu->rnti);
            return;
        }
        current = current->next;
    }
}

int create_pdu_array(int max_structs) {
    NFAPI_CRC_INDICATION_PDU_T* pdu_array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(max_structs * sizeof(NFAPI_CRC_INDICATION_PDU_T));
