        pdu_array[i].crc_ind_rel8.tag1 = (uint16_t)rand();
        pdu_array[i].crc_ind_rel8.tag2 = (uint16_t)rand();

        // Validate RNTI uniqueness and handle duplicates
        validate_rnti(&pdu_array[i]);

        // Insert structure into cache
        insert_cache(pdu_array[i]);
    }
    return max_structs;
}

