class HTTPResponseMessage {
public:
    enum class HttpStatusCode { OK = 200, BAD_REQUEST = 400 };

    HttpStatusCode status;
    std::string responseBody;
    std::unordered_map<std::string, std::string> headerFields;
};

class HTTPResponseArray {
private:
    const int maxMessages;
    int messageCount;
    int resizeFactor;

public:
    HTTPResponseArray(int maxMessages, int resizeFactor) : maxMessages(maxMessages), messageCount(0), resizeFactor(resizeFactor) {}

    void addMessage(const HTTPResponseMessage& message) {
        if (messageCount >= maxMessages && messageCount % resizeFactor == 0) {
            // Resize the array
            std::vector<HTTPResponseMessage> messages(maxMessages * 2);
            std::copy(std::begin(messages), std::end(messages), std::begin(this->messages));
            this->messages = std::move(messages);
        }

        this->messages[messageCount] = message;
        messageCount++;
    }

    const HTTPResponseMessage& getMessage(int index) const {
        if (index >= 0 && index < messageCount)
            return messages[index];
        throw std::out_of_range("Index out of range");
    }

private:
    std::vector<HTTPResponseMessage> messages;
};

class HTTPResponseArrayFactory {
public:
    static HTTPResponseArray create(int maxMessages, int resizeFactor) {
        return HTTPResponseArray(maxMessages, resizeFactor);
    }
};
