using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;

namespace DynamicComponentManager
{
    public class DynamicComponentManager
    {
        private readonly ILogger _logger;
        private readonly Dictionary<string, Component> _components = new();
        private readonly List<IGetter> _getters = new();
        private readonly List<IMessageBroker> _messageBrokers = new();
        private readonly List<IStorageProvider> _storages = new();

        public DynamicComponentManager(ILogger logger)
        {
            _logger = logger;
        }

        public void AddGetter(IGetter getter) => _getters.Add(getter);
        public void RemoveGetter(IGetter getter) => _getters.Remove(getter);

        public void AddMessageBroker(IMessageBroker messageBroker) => _messageBrokers.Add(messageBroker);
        public void RemoveMessageBroker(IMessageBroker messageBroker) => _messageBrokers.Remove(messageBroker);

        public void AddStorage(IStorageProvider storage) => _storages.Add(storage);
        public void RemoveStorage(IStorageProvider storage) => _storages.Remove(storage);

        public async Task<Component> GetComponentAsync(string id)
        {
            await Task.WhenAll(_getters.Select(g => g.Get(id)));
            return _components.GetValueOrDefault(id, null);
        }

        public async Task UpdateComponentAsync(Component component)
        {
            try
            {
                await Task.WhenAll(_messageBrokers.Select(m => m.Publish(component)));
                await _storages.Select(s => s.Update(component)).WhenAll();
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error updating component");
            }
        }

        public async Task<Dictionary<string, Component>> GetComponentsAsync()
        {
            var components = new Dictionary<string, Component>();
            await Task.WhenAll(_getters.Select(g => g.GetComponents().ForEach(c => { components.Add(c.Id, c); })));
            return components;
        }

        // Profile and optimize performance
        public void ProfilePerformance()
        {
            // todo: implement profiling tool
        }
    }

    public interface IGetter
    {
        Task<Component> Get(string id);
        Task<IEnumerable<Component>> GetComponents();
    }

    public interface IMessageBroker
    {
        Task Publish(Component component);
    }

    public interface IStorageProvider
    {
        Task Update(Component component);
    }
}
