class EventProcessor {
public:
    EventProcessor() : event_queue(), breaker(false) {}

    void process_events() {
        while (true) {
            if (breaker) {
                std::cout << "Circuit breaker triggered!" << std::endl;
                break;
            }
            auto event = event_queue.pop();
            // Process event
            std::this_thread::sleep_for(std::chrono::milliseconds(1));
        }
    }

private:
    std::queue<std::string> event_queue;
    bool breaker;
    std::mutex mtx;
    std::condition_variable cv;

    void trigger_circuit_breaker() {
        std::unique_lock<std::mutex> lock(mtx);
        breaker = true;
        cv.notify_one();
    }
};

