#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the structure for a DataRecord
typedef struct {
    int timestamp;
    char payload[];
    void* sensor_config;
} DataRecord;

// Define the structure for a Node in the dynamic linked list
typedef struct Node {
    DataRecord* data;
    struct Node* next;
} Node;

// Function to create a new node with given DataRecord
Node* create_node(DataRecord* record) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->data = record;
    node->next = NULL;
    return node;
}

// Function to insert a new node at the end of the list
void insert_node(Node** head, DataRecord* record) {
    Node* new_node = create_node(record);
    if (*head == NULL) {
        *head = new_node;
    } else {
        Node* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
}

// Function to print the linked list
void print_list(Node* head) {
    Node* current = head;
    while (current != NULL) {
        printf("Timestamp: %d, Payload: %s\n", current->data->timestamp, (char*)current->data->payload);
        current = current->next;
    }
}

// Function to free the linked list
void free_list(Node** head) {
    Node* current = *head;
    while (current != NULL) {
        Node* next = current->next;
        free(current->data);
        free(current);
        current = next;
    }
    *head = NULL;
}

// Function to clear and reset the list
void clear_list(Node** head) {
    free_list(head);
    *head = NULL;
}

int main() {
    Node* head = NULL;

    // Create some DataRecords
    DataRecord record1 = {"2022-01-01", "Hello, World!", NULL};
    DataRecord record2 = {"2022-01-02", "This is another record", NULL};
    DataRecord record3 = {"2022-01-03", "And one more...", NULL};

    // Insert the records into the list
    insert_node(&head, &record1);
    insert_node(&head, &record2);
    insert_node(&head, &record3);

    // Print the list
    print_list(head);

    // Clear and reset the list
    clear_list(&head);

    return 0;
}
