            if (retrieved_tag != NULL) {
                array[i]->rx_ue_information_tag = *retrieved_tag;
                retrieval_success = true;
            } else {
                // Handle failure and retry
                // ...

                // Fallback strategy: Use default value
                array[i]->rx_ue_information_tag = RNTI_DEFAULT_VALUE;
                break;
            }
        }

        if (!retrieval_success) {
            // Log the error and exception
            log_error("Failed to retrieve RX_UE_INFORMATION_TAG for RNTI %zu", i);
            // ...
        }
    }

    return array;
}

void free_nfaapi_crc_indication_pdu_array(NFAPI_CRC_INDICATION_PDU_T** array, size_t n) {
    for (size_t i = 0; i <= n; i++) {
        if (array[i] != NULL) {
            free(array[i]);
        }
    }

