#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <map>
#include <vector>
#include <chrono>

class ConnectionPool {
public:
    ConnectionPool(int maxConnections) : maxConnections_(maxConnections), connections_(), freeConnections_() {
        for (int i = 0; i < maxConnections_; ++i) {
            std::unique_ptr<Connection> connection(new Connection());
            connections_.push(std::move(connection));
            freeConnections_.emplace_back(connections_.top().get());
            connections_.pop();
        }
    }

    ~ConnectionPool() {
        for (auto& conn : connections_) {
            if (!conn->isConnected()) continue;
            conn->close();
        }
    }

    Connection* acquireConnection(const std::string& service, bool async = false) {
        std::unique_lock<std::mutex> lock(mutex_);
        while (freeConnections_.empty()) {
            cv_.wait(lock);
        }
        auto connection = freeConnections_.front();
        freeConnections_.pop();
        ++stats_.connectionsAcquired;
        if (!async) {
            // Synchronous usage
            return connection.get();
        }
        // Asynchronous usage, keep the connection and return a proxy
        return std::make_unique<ConnectionProxy>(connection.release());
    }

    void releaseConnection(Connection* conn) {
        if (conn->isConnected()) {
            std::unique_lock<std::mutex> lock(mutex_);
            freeConnections_.emplace_back(conn);
            ++stats_.connectionsReleased;
            cv_.notify_all();
        }
    }

private:
    int maxConnections_;
    std::queue<std::unique_ptr<Connection>> connections_;
    std::vector<Connection*> freeConnections_;
    std::mutex mutex_;
    std::condition_variable cv_;
    struct Stats {
        int connectionsAcquired = 0;
        int connectionsReleased = 0;
    } stats_;
};

class Connection {
public:
    Connection() : connected_(false) {}

    bool isConnected() const { return connected_; }

    void close() {
        // Close the connection
        connected_ = false;
    }
private:
    bool connected_;
};

class ConnectionProxy {
public:
    ConnectionProxy(Connection* conn) : conn_(conn) {}

    ~ConnectionProxy() {
        if (conn_) {
            conn_->close();
        }
    }

    void sendMessage(const std::string& message) {
        // Send the message asynchronously
        std::thread([this, message]() {
            // Handle the message asynchronously
        }).detach();
    }
private:
    Connection* conn_;
};

