```java
import java.io.*;
import java.util.zip.*;

public class Compressor {

    public static void compress(String inputPath, String outputPath) throws IOException {
        try (FileInputStream fis = new FileInputStream(inputPath);
             FileOutputStream fos = new FileOutputStream(outputPath)) {

            GZIPOutputStream gzip = new GZIPOutputStream(fos);
            byte[] buffer = new byte[1024];
            int bytesRead;
            while ((bytesRead = fis.read(buffer)) != -1) {
                gzip.write(buffer, 0, bytesRead);
            }
            gzip.close();
        }
    }

    public static void decompress(String inputPath, String outputPath) throws IOException {
        try (FileInputStream fis = new FileInputStream(inputPath);
             FileOutputStream fos = new FileOutputStream(outputPath)) {

            GZIPInputStream gzis = new GZIPInputStream(fis);
            byte[] buffer = new byte[1024];
            int bytesRead;
            while ((bytesRead = gzis.read(buffer)) != -1) {
                fos.write(buffer, 0, bytesRead);
            }
            gzis.close();
        }
    }

    public static void zip(String inputPath, String outputPath) throws IOException {
        try (FileInputStream fis = new FileInputStream(inputPath);
             FileOutputStream fos = new FileOutputStream(outputPath)) {

            ZipOutputStream zos = new ZipOutputStream(fos);
            byte[] buffer = new byte[1024];
            int bytesRead;
            while ((bytesRead = fis.read(buffer)) != -1) {
                ZlibInflaterInputStream zip = new ZlibInflaterInputStream(zos);
                byte[] compressed = new byte[bytesRead];
                zip.inflate(compressed);
                zos.putNextEntry(new ZipEntry("file.txt"));
                zos.write(compressed);
            }
        }
    }

    public static void unzip(String inputPath, String outputPath) throws IOException {
        try (FileInputStream fis = new FileInputStream(inputPath);
             FileOutputStream fos = new FileOutputStream(outputPath)) {

            ZipInputStream zis = new ZipInputStream(fis);
            ZipEntry entry;
            while ((entry = zis.getNextEntry()) != null) {
                byte[] buffer = new byte[1024];
                int bytesRead;
                while ((bytesRead = zis.read(buffer)) != -1) {
                    fos.write(buffer, 0, bytesRead);
                }
                zis.closeEntry();
            }
        }
    }

    public static void main(String[] args) throws IOException {
        compress("input.txt", "output.gz");
        decompress("input.gz", "output.txt");

        zip("input.txt", "output.zip");
        unzip("input.zip", "output.txt");
    }
}
