namespace SemaphoreApi
{
    [Route("api/[controller]")]
    public class SemaphoresController : ControllerBase
    {
        private readonly DistributedSemaphoreSystem _semaphores;

        public SemaphoresController(DistributedSemaphoreSystem semaphores)
        {
            _semaphores = semaphores;
        }

        // Initialize a semaphore
        [HttpPost]
        public async Task<IActionResult> InitializeSemaphore([FromBody]int id, int initialCount, int maxCount)
        {
            _semaphores.addSemaphor(id, initialCount, maxCount);
            return Ok();
        }

        // Adjust the limit of a semaphore
        [HttpPut]
        public async Task<IActionResult> AdjustSemaphoreLimit([FromBody]int id, int newMaxCount)
        {
            _semaphores.semaphores[id].maxCount = newMaxCount;
            return Ok();
        }

        // Get the current usage statistics for all semaphores
        [HttpGet]
        public async Task<IActionResult> GetStatistics()
        {
            var stats = new Dictionary<int, int>();
            foreach (var semaphore in _semaphores.semaphores)
            {
                stats.Add(semaphore.id, semaphore.count);
            }
            return Json(stats);
        }

        // Optimistic concurrency control with flexible conflict resolution
        [HttpPut]
        public async Task<IActionResult> UpdateSemaphore([FromBody]int id, int newCount)
        {
            if (_semaphores.semaphores[id].tryAcquire())
            {
                _semaphores.semaphores[id].count = newCount;
                return Ok();
            }
            else
            {
                // Conflict resolution mechanism (e.g., retry or abort)
                return Conflict("Conflict detected");
            }
        }

        // Atomically update multiple semaphores
        [HttpPost]
        public async Task<IActionResult> BatchUpdate([FromBody]List<BatchUpdateRequest> requests)
        {
            foreach (var request in requests)
            {
                _semaphores.semaphores[request.id].acquire();
                try
                {
                    // Update the semaphore's count atomically
                    _semaphores.semaphores[request.id].count = request.newCount;
                }
                finally
                {
                    _semaphores.semaphores[request.id].release();
                }
            }
            return Ok();
        }

        private class BatchUpdateRequest
        {
            public int id { get; set; }
            public int newCount { get; set; }
        }
    }
}
