    private final KafkaTemplate<String, String> kafkaTemplate;
    private final RabbitTemplate rabbitTemplate;

    public MessageProcessorService(KafkaTemplate<String, String> kafkaTemplate, RabbitTemplate rabbitTemplate) {
        this.kafkaTemplate = kafkaTemplate;
        this.rabbitTemplate = rabbitTemplate;
    }

    @PostMapping("/process-message")
    public void processMessage(@RequestBody String message) throws Exception {
        // Parse and validate the message
        Message parsedMessage = parseMessage(message);

        // Validate the message against a schema
        if (!validateMessage(parsedMessage)) {
            throw new RuntimeException("Invalid message");
        }

        // Transform the message into actionable insights
        Insights insights = transformMessage(parsedMessage);

        // Send the insights to downstream consumers
        kafkaTemplate.send("insights-topic", insights.toString());
    }

    @Bean
    public KafkaTemplate<String, String> kafkaTemplate() {
        return new KafkaTemplate<>(new DefaultKafkaProducerFactory<>(producerConfigs()));
    }

    private Map<String, Object> producerConfigs() {
        Map<String, Object> props = new HashMap<>();
        props.put("bootstrap.servers", "localhost:9092");
        props.put("acks", "all");
        props.put("retries", 0);
        return props;
    }
}

// Microservice 2: Event Store
@Service
public class EventStoreService {
    private final EventStore eventStore;

    public EventStoreService(EventStore eventStore) {
        this.eventStore = eventStore;
    }

    @PostMapping("/store-event")
    public void storeEvent(@RequestBody String event) throws Exception {
        // Parse and validate the event
        Event parsedEvent = parseEvent(event);

        // Validate the event against a schema
        if (!validateEvent(parsedEvent)) {
            throw new RuntimeException("Invalid event");
        }

        // Store the event in the event store
        eventStore.store(parsedEvent);
    }

    @Bean
    public EventStore eventStore() {
        return new InMemoryEventStore();
    }
}

// Microservice 3: Message Broker
@Service
public class MessageBrokerService {
    private final RabbitTemplate rabbitTemplate;

    public MessageBrokerService(RabbitTemplate rabbitTemplate) {
        this.rabbitTemplate = rabbitTemplate;
    }

    @PostMapping("/send-message")
    public void sendMessage(@RequestBody String message) throws Exception {
        // Send the message to a dead-letter queue
        rabbitTemplate.convertAndSend("dead-letter-queue", message);
    }
}

