['Here is a code block that implements the required C++ library:

```cpp
#include <iostream>
#include <map>
#include <string>
#include <thread>
#include <mutex>
#include <condition_variable>

class ResourceNode {
public:
    std::string id;
    int status; // 0 - Down, 1 - Up
    double latency;
    long lastUpdated;

    ResourceNode(std::string id) : id(id), status(0), latency(-1.0), lastUpdated(0) {}
};

class Tree {
public:
    std::map<std::string, ResourceNode*> nodes;
    std::mutex mtx;
    std::condition_variable cv;

    void addNode(ResourceNode* node) {
        std::unique_lock<std::mutex> lock(mtx);
        nodes[node->id] = node;
        cv.notify_all();
    }

    bool updateNode(std::string id, int status, double latency) {
        std::unique_lock<std::mutex> lock(mtx);
        if (nodes.find(id) == nodes.end()) return false;
        ResourceNode* node = nodes[id];
        node->status = status;
        node->latency = latency;
        node->lastUpdated = time(nullptr);
        cv.notify_all();
        return true;
    }

    void pruneNodes(int ageThreshold) {
        std::unique_lock<std::mutex> lock(mtx);
        for (auto& pair : nodes) {
            ResourceNode* node = pair.second;
            if ((time(nullptr) - node->lastUpdated) > ageThreshold) {
                delete node;
                nodes.erase(pair.first);
            }
        }
    }
};

int main() {
    Tree tree;

    // Create some test nodes
    ResourceNode* node1 = new ResourceNode("node1");
    ResourceNode* node2 = new ResourceNode("node2");

    // Add nodes to the tree
    tree.addNode(node1);
    tree.addNode(node2);

    // Update nodes
    tree.updateNode("node1", 1, 10.5);
    tree.updateNode("node2", 0, -1.0);

    // Prune old nodes
    tree.pruneNodes(3600); // One hour

    return 0;
}
```

This code provides a basic implementation of the dynamic tree structure management system using C++. The `ResourceNode` class represents individual networked resources with metadata about their status, latency, and last updated timestamp. The `Tree` class manages the collection of these nodes, offering methods for adding new nodes, updating existing ones, and pruning old or redundant entries.

This code is designed to be modular, scalable, and thread-safe, allowing it to handle high-throughput environments with thousands of network resources while minimizing memory footprint and cache pressure.']

