#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>

class Event {
public:
    std::string data;
    int type;

    Event(std::string data, int type) : data(data), type(type) {}
};

class Broker {
private:
    std::mutex mtx;
    std::condition_variable cv;
    std::queue<Event> events;

public:
    void publish(Event event) {
        std::unique_lock<std::mutex> lock(mtx);
        events.push(event);
        cv.notify_all();
    }

    void consume() {
        while (true) {
            std::unique_lock<std::mutex> lock(mtx);
            cv.wait(lock, [this] { return !events.empty(); });

            Event event = events.front();
            events.pop();

            // Process the event
            processEvent(event);

            lock.unlock();

            // Simulate some processing time
            std::this_thread::sleep_for(std::chrono::milliseconds(10));
        }
    }

private:
    void processEvent(Event event) {
        // Implement your event processing logic here
        std::cout << "Processed event: " << event.data << std::endl;
    }
};

int main() {
    Broker broker;

    // Publish some events
    for (int i = 0; i < 5; i++) {
        Event event("Event " + std::to_string(i), i);
        broker.publish(event);
    }

    // Consume the events
    while (true) {
        broker.consume();
    }

    return 0;
}
