```cpp
#include <iostream>
#include <fstream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <map>

class Logger {
public:
    enum class LogLevel { DEBUG, INFO, WARNING, ERROR, FATAL };

    Logger(const std::string& name) : name_(name), console_log_(false), file_log_(false), remote_log_(false) {}

    void setDestination(bool console, bool file, bool remote) {
        console_log_ = console;
        file_log_ = file;
        remote_log_ = remote;
    }

    void log(LogLevel level, const std::string& message) {
        if (level > LogLevel::FATAL) return;

        std::unique_lock<std::mutex> lock(log_mutex_);
        log_queue_.push({ level, message });
        lock.unlock();
        log_cv_.notify_one();
    }

private:
    struct LogEntry {
        LogLevel level;
        std::string message;
    };

    void run() {
        while (true) {
            LogEntry entry;
            if (!log_queue_.try_pop(entry)) break;

            if (console_log_) {
                std::cout << "[" << entry.level << "] " << name_ << ": " << entry.message << std::endl;
            }

            if (file_log_) {
                std::ofstream file("log.txt", std::ios_base::app);
                file << "[" << entry.level << "] " << name_ << ": " << entry.message << std::endl;
                file.close();
            }

            if (remote_log_) {
                // send log to remote server
            }
        }
    }

    void start() {
        thread_ = std::thread([this]() { run(); });
    }

    void stop() {
        if (thread_.joinable()) thread_.join();
    }

    std::string name_;
    bool console_log_, file_log_, remote_log_;
    std::mutex log_mutex_;
    std::condition_variable log_cv_;
    std::queue<LogEntry> log_queue_;
    std::thread thread_;
};

int main() {
    Logger logger("MyApp");

    logger.setDestination(true, true, false);

    logger.log(Logger::LogLevel::DEBUG, "Starting application");
    logger.log(Logger::LogLevel::INFO, "Loaded configuration file");
    logger.log(Logger::LogLevel::WARNING, "Network connection timed out");

    return 0;
}
```

