```java
import java.io.File;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.CopyOnWriteArrayList;

import org.apache.commons.lang3.StringUtils;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.autoconfigure.condition.ConditionalOnMissingBean;
import org.springframework.context.ApplicationContext;
import org.springframework.core.io.ResourceLoader;
import org.springframework.retry.annotation.Retryable;
import org.springframework.scheduling.concurrent.ConcurrentTaskExecutor;
import org.springframework.stereotype.Service;

@Service
public class StateLoaderService {

    private static final Logger logger = LoggerFactory.getLogger(StateLoaderService.class);

    @Autowired
    private ApplicationContext applicationContext;

    @Autowired
    private ResourceLoader resourceLoader;

    private Map<String, StateLoader> stateLoaders = new ConcurrentHashMap<>();

    private List<StateChangeListener> listeners = new CopyOnWriteArrayList<>();

    public void loadState(String stateId) {
        StateLoader stateLoader = stateLoaders.get(stateId);
        if (stateLoader == null) {
            throw new StateNotFoundException("No state found for ID: " + stateId);
        }
        try {
            stateLoader.load();
            notifyListeners(stateId);
        } catch (Exception e) {
            logger.error("Error loading state", e);
            int retryCount = 0;
            while (retryCount < 3 && e instanceof RetryableException) {
                try {
                    stateLoader.load();
                    notifyListeners(stateId);
                    break;
                } catch (RetryableException re) {
                    // Try again
                    retryCount++;
                    logger.error("Retrying load of state", re);
                }
            }
            if (retryCount >= 3) {
                logger.error("Failed to load state after 3 retries");
            }
        }
    }

    public void addStateChangeListener(StateChangeListener listener) {
        listeners.add(listener);
    }

    public void removeStateChangeListener(StateChangeListener listener) {
        listeners.remove(listener);
    }

    private void notifyListeners(String stateId) {
        for (StateChangeListener listener : listeners) {
            listener.stateLoaded(stateId);
        }
    }

    @ConditionalOnMissingBean
    public StateLoader localFileStateLoader() {
        return new LocalFileStateLoader(resourceLoader, getFilePath());
    }

    public String getFilePath() {
        // Get the file path from the configuration settings
        return "path/to/file";
    }

    @Retryable(maxAttempts = 3)
    private void loadFromLocalFile(StateLoader stateLoader) throws IOException {
        // Load state from local file
    }

    @Retryable(maxAttempts = 3)
    private void loadFromRESTEndpoint(StateLoader stateLoader) throws Exception {
        // Load state from REST endpoint
    }
}

class StateNotFoundException extends Exception {
    public StateNotFoundException(String message) {
        super(message);
    }
}

interface StateLoader {
    void load() throws IOException, Exception;
}

interface StateChangeListener {
    void stateLoaded(String stateId);
}
```']

