class TestRunner {
  constructor({
    timeout = 30000,
    retryAttempts = 3,
    logLevel = 'info',
    concurrencyLimit = 5,
  }) {
    this.timeout = timeout;
    this.retryAttempts = retryAttempts;
    this.logLevel = logLevel;
    this.concurrencyLimit = concurrencyLimit;
    this.testQueue = [];
    this.cache = {};
    this.analytics = new Analytics();
  }

  async loadResourceBundle(url) {
    try {
      const response = await fetch(url);
      if (!response.ok) {
        throw new Error(`Failed to load resource bundle: ${url}`);
      }
      return response.json();
    } catch (error) {
      console.error(error);
      return null;
    }
  }

  async executeTests(moduleName, tests) {
    const testResults = [];
    await Promise.all(
      this.testQueue.map(async (test) => {
        try {
          const result = await test(moduleName);
          testResults.push({ testName: test.name, result });
        } catch (error) {
          console.error(error);
          // Retry failed tests up to the specified retryAttempts
          if (this.retryAttempts > 0) {
            await this.executeTests(moduleName, [test]);
          }
        }
      })
    );
    return testResults;
  }

  async runTests(moduleName) {
    const tests = require(`./tests/${moduleName}`).default;
    this.testQueue = tests.map((test) => ({ name: test.name, func: test }));
    await this.executeTests(moduleName, this.testQueue);
  }

  getAnalytics() {
    return this.analytics.getMetrics();
  }
}

// Analytics.js
class Analytics {
  constructor() {
    this.metrics = {};
  }

  async addMetric(name, value) {
    if (!this.metrics[name]) {
      this.metrics[name] = [];
    }
    this.metrics[name].push(value);
  }

  getMetrics() {
    return this.metrics;
  }
}

