    const cachedResponse = await this.cache.get(themeId);
    if (cachedResponse) return cachedResponse;

    // Fetch from APIs
    const promises = this.apiList.map((api) => api.getTheme(themeId));
    const results = await Promise.all(promises);

    // Merge responses
    const mergedResponse = {};
    for (const [key, value] of Object.entries(results[0])) {
      if (!value || !Object.values(value).every(Boolean)) {
        throw new Error(`Failed to load theme ${themeId}`);
      }
      mergedResponse[key] = value;
    }

    // Cache response
    await this.cache.set(themeId, mergedResponse);

    return mergedResponse;
  }

  async applyTheme(themeId) {
    try {
      const themeData = await this.getTheme(themeId);
      // Apply theme data
      console.log(`Applied theme ${themeId}`);
    } catch (error) {
      console.error('Error applying theme:', error);
    }
  }

  startWorker(workerConfig) {
    const worker = new Worker(
      `import { ${workerConfig.name} } from './workers/${workerConfig.name}.js';`
    );
    this.workerPool.set(workerConfig.name, worker);
  }

  async processQueue() {
    while (this.themeQueue.length > 0) {
      const themeId = this.themeQueue.shift();
      await this.applyTheme(themeId);
      // Pause for a bit to avoid overwhelming the system
      await throttle(() => setTimeout(() => {}, 500), 1000);
    }
  }

  addThemeToQueue(themeId) {
    this.themeQueue.push(themeId);
  }

  async pause() {
    await new Promise((resolve) => setTimeout(() => resolve(), 100));
  }

  async resume() {
    await this.processQueue();
  }
}

export default ThemeManager;
