async fn compile_project(project_dir: &Path, build_type: &str) {
    let mut command = format!("rustc -Z {build_type} --out-dir={project_dir}/target");
    command.push_str("--lib --crate-type lib");
    let output = std::process::Command::new("rustc")
        .args(&command.split_whitespace())
        .output()
        .expect("Failed to compile project");

    if !output.status().is_success() {
        eprintln!("Compilation failed: {}", String::from_utf8_lossy(&output.stdout));
    } else {
        info!("Project compiled successfully");
    }
}

fn load_resource_bundles(project_dir: &Path) {
    // Load and unload resource bundles from a specified file path
    let bundle_path = project_dir.join("resource_bundle.txt");
    if bundle_path.exists() {
        let mut file = File::open(&bundle_path).expect("Failed to open file");
        let mut contents = String::new();
        file.read_to_string(&mut contents)
            .expect("Failed to read file contents");

        // Load resources
        for line in contents.lines() {
            // Split by comma and extract bundle name
            let (bundle_name, _) = line.split_once(',').unwrap();
            load_bundle(project_dir.join(bundle_name)).unwrap_or_else(|| panic!("Failed to load bundle"));
        }

