// Octree node structure
struct Node {
    int id;
    std::vector<Node*> children;
};

class Octree {
public:
    Octree(int maxLevel, int minCapacity) : maxLevel(maxLevel), minCapacity(minCapacity) {}

    void insert(int data) {
        root = insert(root, data);
    }

    void remove(int data) {
        root = remove(root, data);
    }

    std::vector<int> query(int x1, int y1, int z1, int x2, int y2, int z2) {
        return query(root, x1, y1, z1, x2, y2, z2);
    }

private:
    Node* root;
    int maxLevel;
    int minCapacity;

    Node* insert(Node* node, int data) {
        if (!node) {
            node = new Node();
            node->id = data;
        } else if (data < node->id) {
            if (node->children.empty()) {
                for (int i = 0; i < 8 && !node->children[i]; i++) {
                    node->children.push_back(new Node());
                }
            }
            insert(node->children[0], data);
        } else {
            // right child
            int idx = 7;
            while (!node->children[idx]) idx--;
            node->children[idx]->id = data;
        }
        return node;
    }

    Node* remove(Node* node, int data) {
        if (data == node->id) {
            // delete leaf node
            if (node->children.empty()) {
                delete node;
                return nullptr;
            } else {
                for (int i = 0; i < 8 && !node->children[i]; i++) {
                    node->children.pop_back();
                }
            }
        } else {
            // recursive search
            for (Node* child : node->children) {
                if (data < child->id) {
                    remove(child, data);
                } else if (data > child->id) {
                    return node;
                } else {
                    delete child;
                    child = nullptr;
                    break;
                }
            }
        }
        return node;
    }

    std::vector<int> query(Node* node, int x1, int y1, int z1, int x2, int y2, int z2) {
        std::vector<int> result;
        if (node && x1 <= node->id && x2 >= node->id &&
            y1 <= node->id && y2 >= node->id &&
            z1 <= node->id && z2 >= node->id) {
            // query within the current node
            for (Node* child : node->children) {
                std::vector<int> childResult = query(child, x1, y1, z1, x2, y2, z2);
                if (!childResult.empty()) {
                    result.insert(result.end(), childResult.begin(), childResult.end());
                }
            }
        } else {
            // query outside the current node
            for (Node* child : node->children) {
                std::vector<int> childResult = query(child, x1, y1, z1, x2, y2, z2);
                if (!childResult.empty()) {
                    result.insert(result.end(), childResult.begin(), childResult.end());
                }
            }
        }
        return result;
    }

    // Helper function to create a new node with the given data
    Node* createNode(int id) {
        Node* node = new Node();
        node->id = id;
        return node;
    }
};

int main() {
    Octree octree(3, 8);
    octree.insert(1);
    octree.insert(2);
    octree.insert(3);
    std::cout << "Querying: ";
    for (int data : octree.query(0, 0, 0, 10, 10, 10)) {
        std::cout << data << " ";
    }
    std::cout << std::endl;
    return 0;
}

```

