import logging
from typing import Dict, Any

class DistributedLogger:
    def __init__(self):
        self.loggers = {}
        self.config = {}

    def add_logger(self, name: str, logger: Any) -> None:
        self.loggers[name] = logger

    def remove_logger(self, name: str) -> None:
        if name in self.loggers:
            del self.loggers[name]

    def configure(self, config: Dict[str, Any]) -> None:
        self.config.update(config)

    def log(self, message: str, level: int, logger_name: str = "default") -> None:
        if level not in [logging.DEBUG, logging.INFO, logging.WARNING, logging.ERROR, logging.CRITICAL]:
            raise ValueError("Invalid log level")
        logger = self.loggers.get(logger_name)
        if logger is None:
            raise KeyError(f"Logger '{logger_name}' does not exist")
        config = self.config.get("format", "%(message)s")
        logger.setLevel(level)
        logger.info(config.format(message=message))

    def start(self) -> None:
        for name, logger in self.loggers.items():
            if name == "default":
                logger.setLevel(logging.INFO)
            else:
                logger.setLevel(logging.DEBUG)

    def stop(self) -> None:
        for logger in self.loggers.values():
            logger.flush()

class CloudLogger:
    def __init__(self, api_key: str, api_secret: str):
        self.api_key = api_key
        self.api_secret = api_secret

