package main;

import (
	"context"
	"fmt"
	"log"
	"net/http"
	"os"
	"sync"

	"github.com/apache/kafka-go/cluster"
	"github.com/go-kratos/kratos/v2/log"
	"github.com/hashicorp/memberlist"
)

const (
	// Default port for Kafka
	defaultPort = ":9092"

	// Default number of workers
	defaultWorkers = 5

	// Default amount of memory to use
	defaultMemoryUsage = "512MB"
)

var (
	memoryUsage string
	port         int
	workers      int
)

func main() {
	log.Init()
	log.Level(log.INFO)
	if len(os.Args) > 1 {
		for _, arg := range os.Args[1:] {
			switch arg {
			case "-p":
				fallthrough
			case "--port":
				port, _ = strconv.Atoi(arg)
			case "-w":
				fallthrough
			case "--workers":
				workers, _ = strconv.Atoi(arg)
			case "-m":
				fallthrough
			case "--memory":
				memoryUsage = arg
			default:
				log.Printf("Unknown flag: %s", arg)
			}
		}
	}

	if port == 0 {
		port = defaultPort
	}
	if workers == 0 {
		workers = defaultWorkers
	}
	if memoryUsage == "" {
		memoryUsage = defaultMemoryUsage
	}

	log.Println("Starting main function...")
	// Create a memberlist instance
	memberlistInstance, err := memberlist.NewMemberList(
		context.Background(),
		os.Getenv("MEMBERLIST_ID"),
		port,
	)
	if err != nil {
		log.Fatal(err)
	}
	defer func() { _ = memberlistInstance.Shutdown(context.Background()) }()

	// Create a cluster instance
	clusterInstance, err := cluster.NewCluster(
		context.Background(),
		memberlistInstance,
	)
	if err != nil {
		log.Fatal(err)
	}

	log.Println("Starting Kafka consumer...")
	// Start the Kafka consumer
	go startKafkaConsumer(clusterInstance)

	log.Println("Starting HTTP server...")
	// Start the HTTP server
	http.HandleFunc("/healthz", healthCheckHandler)
	http.ListenAndServe(fmt.Sprintf(":%d", port), nil)

	log.Println("Shutting down...")
}

func healthCheckHandler(w http.ResponseWriter, r *http.Request) {
	fmt.Fprint(w, "OK")
}
```

