import boto3
from azure.storage.blob import BlobServiceClient
from google.cloud import storage

class CloudStorage:
    def __init__(self):
        self.aws_s3 = boto3.client('s3')
        self.azure_blob_storage = BlobServiceClient.from_connection_string(
            "DefaultEndpointsProtocol=https;"
            "AccountName=<account_name>;"
            "AccountKey=<account_key>;"
            "BlobEndpoint=<blob_endpoint>"
        )
        self.google_cloud_storage = storage.Client()

    def upload_file(self, file_path):
        try:
            if file_path.startswith("s3://"):
                self.aws_s3.upload_file(file_path, "bucket_name", "file_name")
            elif file_path.startswith("azure://"):
                blob_client = self.azure_blob_storage.get_blob_client("container_name", "blob_name")
                with open(file_path, "rb") as data:
                    blob_client.upload_blob(data.read(), overwrite=True)
            elif file_path.startswith("gs://"):
                bucket_name = file_path.split(":")[1].split("/")[0]
                blob_name = file_path.split(":")[1].split("/")[1]
                blob = self.google_cloud_storage.bucket(bucket_name).blob(blob_name)
                with open(file_path, "rb") as data:
                    blob.upload_from_string(data.read(), content_type="application/octet-stream")
        except Exception as e:
            print(f"Error uploading file: {e}")

    def validate_url(self, url):
        if url.startswith("s3://"):
            return self.aws_s3.get_bucket(url.split(":")[1]).exists()
        elif url.startswith("azure://"):
            return self.azure_blob_storage.get_container_client("container_name").get_blob_client("blob_name").exists()
        elif url.startswith("gs://"):
            bucket_name = url.split(":")[1].split("/")[0]
            blob_name = url.split(":")[1].split("/")[1]
            return self.google_cloud_storage.bucket(bucket_name).blob(blob_name).exists()

    def sanitize_url(self, url):
        if url.startswith("s3://"):
            sanitized_url = f"s3://{url.split(':')[2]}"
        elif url.startswith("azure://"):
            sanitized_url = f"azure://{url.split(':')[1]}/{url.split(':')[2]}"
        elif url.startswith("gs://"):
            sanitized_url = f"gs://{url.split(':')[1]}/{url.split(':')[2]}"
        return sanitized_url

class UploadService:
    def __init__(self):
        self.cloud_storage = CloudStorage()
        self.upload_queue = asyncio.Queue()

    async def upload_file(self, file_path):
        try:
            await self.cloud_storage.upload_file(file_path)
        except Exception as e:
            print(f"Error uploading file: {e}")

    async def handle_upload(self, file_path):
        try:
            if not self.cloud_storage.validate_url(file_path):
                raise ValueError("Invalid URL")
            sanitized_url = self.cloud_storage.sanitize_url(file_path)
            await self.upload_queue.put((file_path, sanitized_url))
            print(f"File uploaded: {file_path}")
        except Exception as e:
            print(f"Error uploading file: {e}")

    async def main(self):
        while True:
            try:
                await asyncio.wait([self.handle_upload(file_path) for file_path in self.upload_queue.get_nowait()])
            except asyncio.QueueEmpty:
                pass
            time.sleep(0.1)

if __name__ == "__main__":
    loop = asyncio.get_event_loop()
    service = UploadService()
    loop.run_until_complete(service.main())
