// Node.js Service Code

const { spawn } = require('child_process');
const { createWriteStream, createReadStream } = require('fs');
const { performance } = require('perf_hooks');

class CommandExecutor {
  constructor({
    commandList,
    loggingService,
    externalDataSources,
  }) {
    this.commandList = commandList;
    this.loggingService = loggingService;
    this.externalDataSources = externalDataSources;
  }

  async executeCommands() {
    for (const command of this.commandList) {
      try {
        const { stdout, stderr } = await this.executeCommand(
          command.command,
          command.args,
          command.timeout,
          command.loggingLevel
        );
        // Log the output and execution details
        this.loggingService.log({
          command: command.command,
          stdout: stdout.toString(),
          stderr: stderr.toString(),
          level: command.loggingLevel,
        });
      } catch (error) {
        console.error('Error executing command:', error);
        // Implement fallback mechanism for failed commands
        if (error.name === 'PermissionDeniedError') {
          // Retry with increased timeout or alternative data sources
          await this.executeCommands();
        }
      }
    }
  }

  async executeCommand(command, args, timeout, loggingLevel) {
    const commandProcess = spawn(command, args, {
      stdio: 'pipe',
      timeout,
      resourceLimit: {
        cpu: 0.5, // Limit CPU usage to 50%
        memory: '128MB', // Limit memory usage to 128MB
      },
    });

    // Read command output and error streams asynchronously
    const stdout = await new Promise((resolve) =>
      commandProcess.stdout.pipe(createWriteStream('stdout.txt')).on('close', resolve)
    );
    const stderr = await new Promise((resolve) =>
      commandProcess.stderr.pipe(createReadStream('stderr.txt')).on('close', resolve)
    );

    // Check for timeout and invalid command errors
    if (commandProcess.killed || !commandProcess.exitCode) {
      throw new Error(`Command timed out or returned an error: ${stdout.toString()}`);
    }

    return { stdout, stderr };
  }
}

// Example usage:
const commandList = [
  {
    command: 'ls',
    args: ['-l'],
    timeout: 1000,
    loggingLevel: 'INFO',
  },
  {
    command: 'curl',
    args: ['https://example.com'],
    timeout: 5000,
    loggingLevel: 'DEBUG',
  },
];

const loggingService = require('./logging-service');
const externalDataSources = [require('./data-source-1'), require('./data-source-2')];

const commandExecutor = new CommandExecutor({ commandList, loggingService, externalDataSources });
commandExecutor.executeCommands();
```

