pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
UserProfile profiles[MAX_PROFILES]; // Define the maximum number of profiles
int num_profiles = 0;

void add_profile(int id, const char* name, const char* profile_pic_url) {
    pthread_mutex_lock(&lock);
    UserProfile new_profile;
    new_profile.id = id;
    strcpy(new_profile.name, name);
    strcpy(new_profile.profile_pic_url, profile_pic_url);
    profiles[num_profiles++] = new_profile;
    pthread_mutex_unlock(&lock);
}

void update_profile(int id, const char* new_name) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < num_profiles; i++) {
        if (profiles[i].id == id) {
            strcpy(profiles[i].name, new_name);
            break;
        }
    }
    pthread_mutex_unlock(&lock);
}

void remove_profile(int id) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < num_profiles; i++) {
        if (profiles[i].id == id) {
            memmove(&profiles[i], &profiles[i + 1], sizeof(UserProfile) * (num_profiles - i - 1));
            num_profiles--;
            break;
        }
    }
    pthread_mutex_unlock(&lock);
}

void* handle_updates(void*) {
    // Handle updates and errors
