    public enum LogLevel { DEBUG, INFO, WARNING, ERROR };

    // External log service implementations
    private Map<String, LogService> logServices = new HashMap<>();
    private AtomicReference<LogLevel> currentLogLevel = new AtomicReference<>(LogLevel.INFO);

    // Async logging executor
    private ExecutorService asyncExecutor = Executors.newCachedThreadPool();

    public void configure(String serviceName, LogService service) {
        logServices.put(serviceName, service);
    }

    public void setLogLevel(LogLevel level) {
        currentLogLevel.set(level);
    }

    public void log(String message, LogLevel level) {
        if (level.compareTo(currentLogLevel.get()) >= 0) {
            logger.log(level, message);
            // Asynchronous logging
            asyncExecutor.submit(() -> {
                try {
                    LogService service = getPreferredLogService();
                    service.log(message, level);
                } catch (Exception e) {
                    logger.error("Error logging to external services", e);
                }
            });
        }
