enum class DeviceStatus {
    ONLINE,
    OFFLINE,
    MAINTENANCE
};

class Device {
public:
    Device(const std::string& hostname, const std::string& uuid) : 
        hostname(hostname), uuid(uuid), status(DeviceStatus::ONLINE), temperature(0.0) {}

    void updateTemperature(double temp) { temperature = temp; }

    void setStatus(DeviceStatus status) { this->status = status; }

    DeviceStatus getStatus() { return status; }

    double getTemperature() { return temperature; }

    std::string getHostname() { return hostname; }

private:
    std::string hostname;
    std::string uuid;
    DeviceStatus status;
    double temperature;
};

class DeviceManager {
public:
    void addDevice(Device device) { devices[device.getUuid()] = device; }

    void updateDevice(const std::string& uuid, double temp, DeviceStatus status) {
        auto it = devices.find(uuid);
        if (it != devices.end()) {
            it->second.updateTemperature(temp);
            it->second.setStatus(status);
        }
    }

    void getDevices() {
        for (auto& device : devices) {
            std::cout << "Device: " << device.second.getHostname()
                      << ", Status: " << device.second.getStatus()
                      << ", Temperature: " << device.second.getTemperature()
                      << std::endl;
        }
    }

private:
    std::unordered_map<std::string, Device> devices;
};

int main() {
    DeviceManager manager;

    Device device1("Device 1", "UUID-1");
    device1.updateTemperature(25.0);
    device1.setStatus(DeviceStatus::MAINTENANCE);

    Device device2("Device 2", "UUID-2");
    device2.updateTemperature(30.0);
    device2.setStatus(DeviceStatus::ONLINE);

    manager.addDevice(device1);
    manager.addDevice(device2);

    manager.getDevices();

    return 0;
}
