using namespace std;

int main(int argc, char* argv[]) {
    vector<string> args(argv + 1, argv + argc);
    string manPage = "--manpage";
    string countLines = "-cs";
    string outputFile = "";
    string batchMode = "-b";

    for (auto& arg : args) {
        if (arg == manPage) {
            printUsageHelp();
            return 0;
        }
        else if (arg.find(countLines) != string::npos) {
            countLinesInFile(args);
            return 0;
        }
        else if (arg.find(outputFile) != string::npos) {
            outputFile = arg.substr(strlen(outputFile));
        }
        else if (arg == batchMode) {
            vector<string> filesToProcess;

            for (auto& file : args) {
                if (file.find(batchMode) == string::npos) {
                    filesToProcess.push_back(file);
                }
            }

            priority_queue<pair<int, string>, vector<pair<int, string>>, greater<pair<int, string>>> fileQueue;
            int fileSize = 0;

            for (auto& file : filesToProcess) {
                ifstream fin(file);
                fileSize = getLineCount(fin);
                fin.close();
                fileQueue.push({fileSize, file});
            }

            thread threads[4];

            for (int i = 0; i < 4 && !fileQueue.empty(); i++) {
                threads[i] = thread(processFile, ref(fileQueue));
            }

            for (auto& th : threads) {
                th.join();
            }
        }
    }

    return 0;
}

void printUsageHelp() {
    cout << "Usage: app [options]" << endl;
    cout << "Options:" << endl;
    cout << "--manpage  Display this help message" << endl;
    cout << "-cs       Count lines in input file" << endl;
    cout << "-o <file> Redirect output to file" << endl;
    cout << "-b        Batch process multiple files" << endl;
}

void countLinesInFile(vector<string>& args) {
    if (args.size() != 2) {
        printUsageHelp();
        return;
    }

    ifstream fin(args[1]);
    int lineCount = getLineCount(fin);
    fin.close();

    cout << "Total lines: " << lineCount << endl;
}

int getLineCount(istream& fin) {
    int lineCount = 0;

    for (string line; getline(fin, line);) {
        lineCount++;
    }

    return lineCount;
}

void processFile(priority_queue<pair<int, string>, vector<pair<int, string>>, greater<pair<int, string>>>& fileQueue) {
    while (!fileQueue.empty()) {
        pair<int, string> file = fileQueue.top();
        fileQueue.pop();

        try {
            ifstream fin(file.second);
            int lineCount = getLineCount(fin);
            fin.close();

            if (outputFile != "") {
                ofstream fout(outputFile);
                for (int i = 0; i < lineCount; i++) {
                    string line;
                    getline(fin, line);
                    fout << line << endl;
                }
                fin.close();
                fout.close();
            }
        }
        catch (...) {
            // Handle exceptions
        }
    }
}

int getLineCount(istream& fin) {
    int lineCount = 0;

    for (string line; getline(fin, line);) {
        lineCount++;
    }

    return lineCount;
}
