package com.example.dataprocessingpipeline;

import java.util.List;
import java.util.ArrayList;
import java.util.Map;
import java.util.HashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class DataProcessingPipeline {
    private ExecutorService executorService = Executors.newFixedThreadPool(10);
    private Map<String, DataProcessor> dataProcessors = new HashMap<>();
    private Map<String, DataTransformer> dataTransformers = new HashMap<>();
    private Map<String, StorageSolution> storageSolutions = new HashMap<>();

    public void addDataProcessor(String processorName, DataProcessor processor) {
        dataProcessors.put(processorName, processor);
    }

    public void addDataTransformer(String transformerName, DataTransformer transformer) {
        dataTransformers.put(transformerName, transformer);
    }

    public void addStorageSolution(String solutionName, StorageSolution solution) {
        storageSolutions.put(solutionName, solution);
    }

    public void processData(Map<String, Object> inputData) {
        executorService.submit(() -> {
            // Process data through pipeline
            for (String processor : dataProcessors.keySet()) {
                DataProcessor processorInstance = dataProcessors.get(processor);
                if (processorInstance.process(inputData)) {
                    break;
                }
            }

            for (String transformer : dataTransformers.keySet()) {
                DataTransformer transformerInstance = dataTransformers.get(transformer);
                inputData = transformerInstance.transform(inputData);
            }

            for (String solution : storageSolutions.keySet()) {
                StorageSolution solutionInstance = storageSolutions.get(solution);
                solutionInstance.store(inputData);
            }
        });
    }

    public interface DataProcessor {
        boolean process(Map<String, Object> inputData);
    }

    public interface DataTransformer {
        Map<String, Object> transform(Map<String, Object> inputData);
    }

    public interface StorageSolution {
        void store(Map<String, Object> data);
    }
}
