int countDisjointPairs(std::vector<int> arr) {
    int n = arr.size();
    std::unordered_map<int, int> parent;
    std::unordered_map<int, int> rank;

    for (int i = 0; i < n; i++) {
        parent[arr[i]] = arr[i];
        rank[arr[i]] = 0;
    }

    int time = 0;
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            if (find(parent, arr[i]) != find(parent, arr[j])) {
                unionSets(parent, rank, arr[i], arr[j]);
                std::cout << "Disjoint pair found: (" << arr[i] << ", " << arr[j] << "). Time taken: " << time << "ms" << std::endl;
            }
        }
        time++;
    }

    return 0;
}

int find(std::unordered_map<int, int>& parent, int x) {
    if (parent[x] != x)
        parent[x] = find(parent, parent[x]);
    return parent[x];
}

void unionSets(std::unordered_map<int, int>& parent, std::unordered_map<int, int>& rank, int x, int y) {
    int rootX = find(parent, x);
    int rootY = find(parent, y);

    if (rank[rootX] < rank[rootY]) {
        parent[rootX] = rootY;
    }
    else if (rank[rootX] > rank[rootY]) {
        parent[rootY] = rootX;
    }
    else {
        parent[rootY] = rootX;
        rank[rootX]++;
    }
}

int main() {
    std::vector<int> arr = {1, 2, 3, 4, 5};
    auto start = std::chrono::high_resolution_clock::now();
    int result = countDisjointPairs(arr);
    auto finish = std::chrono::high_resolution_clock::now();

    std::cout << "Time taken: " << std::chrono::duration_cast<std::chrono::microseconds>(finish - start).count() / 1000.0 << " seconds" << std::endl;

    return result;
}
