class ResourcePool {
public:
    ResourcePool(size_t capacity) : capacity_(capacity), resources_(new std::vector<void*>(capacity)) {}

    ~ResourcePool() {
        for (void* resource : *resources_) {
            // Release resources
        }
        delete resources_;
    }

    void acquire() {
        if (resources_->size() < capacity_) {
            resources_->push_back(new void()); // Create new resource
        } else {
            std::this_thread::sleep_for(std::chrono::microseconds(10)); // Simulate busy pool
        }
    }

    bool release(void* resource) {
        for (void*& r : *resources_) {
            if (&r == resource) {
                resources_->erase(std::remove(resources_->begin(), resources_->end(), &r), resources_->end());
                delete resource;
                return true;
            }
        }
        return false;
    }

private:
    size_t capacity_;
    std::vector<void*> resources_;
};

