public:
    ResourcePoolsManager() {}

    ~ResourcePoolsManager() {
        for (auto& pool : pools_) {
            delete pool.second;
        }
    }

    void addPool(const std::string& name, size_t capacity) {
        pools_[name] = new ResourcePool(capacity);
    }

    void removePool(const std::string& name) {
        auto it = pools_.find(name);
        if (it != pools_.end()) {
            delete it->second;
            pools_.erase(it);
        }
    }

    void acquireResource(const std::string& poolName, void* resource) {
        auto it = pools_.find(poolName);
        if (it != pools_.end()) {
            it->second->acquire();
            resourcePools_[poolName].push_back(resource); // Record acquired resource
        }
    }

    bool releaseResource(const std::string& poolName, void* resource) {
        auto it = pools_.find(poolName);
        if (it != pools_.end()) {
            return it->second->release(resource);
        }
        return false;
    }

private:
    std::map<std::string, ResourcePool*> pools_;
    std::map<std::string, std::vector<void*>> resourcePools_;
};

