                return;
            }
            catch (SqlException ex)
            {
                _logger.LogError(ex, "Error processing XML from database");
                if (i == retryCount - 1) throw;
                await Task.Delay(1000); // backoff
            }
        }
    }

    public async Task ProcessXmlFromRestApiAsync(string apiUrl, int retryCount = 3)
    {
        for (int i = 0; i < retryCount; i++)
        {
            try
            {
                using var client = new HttpClient();
                using var response = await client.GetAsync(apiUrl);

                response.EnsureSuccessStatusCode();

                // process XML here
                _logger.LogInformation("XML processed successfully");
                return;
            }
            catch (HttpRequestException ex)
            {
                _logger.LogError(ex, "Error processing XML from REST API");
                if (i == retryCount - 1) throw;
                await Task.Delay(1000); // backoff
            }
        }
    }

    public void EncryptData(string dataToEncrypt, out string encryptedData)
    {
        using var aes = Aes.Create();
        using var encryptor = aes.CreateEncryptor(aes.Key, aes.IV);

        byte[] bytesToEncrypt = Encoding.UTF8.GetBytes(dataToEncrypt);
        byte[] encryptedBytes = encryptor.TransformFinalBlock(bytesToEncrypt, 0, bytesToEncrypt.Length);

        encryptedData = Convert.ToBase64String(encryptedBytes);
    }

    public void DecryptData(string dataToDecrypt, out string decryptedData)
    {
        using var aes = Aes.Create();
        using var decryptor = aes.CreateDecryptor(aes.Key, aes.IV);

        byte[] bytesToDecrypt = Convert.FromBase64String(dataToDecrypt);
        byte[] decryptedBytes = decryptor.TransformFinalBlock(bytesToDecrypt, 0, bytesToDecrypt.Length);

        decryptedData = Encoding.UTF8.GetString(decryptedBytes);
    }
}

public class XmlLogger
{
