#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define structure for linked list nodes
typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
    struct NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDATION_PDU_T;

// Define custom memory pool for efficient memory allocation
typedef struct MemoryPool {
    void** blocks;
    int size;
    int used;
    pthread_mutex_t lock;
} MemoryPool;

// Initialize memory pool with initial block count and size
void initMemoryPool(MemoryPool* pool, int initialSize) {
    pool->blocks = (void*)malloc(initialSize * sizeof(void*));
    pool->size = initialSize;
    pool->used = 0;
    pthread_mutex_init(&pool->lock, NULL);
}

// Allocate memory from the custom pool
void* mallocFromPool(MemoryPool* pool, size_t size) {
    void* ptr;
    pthread_mutex_lock(&pool->lock);
    if (pool->used < pool->size) {
        ptr = pool->blocks[pool->used];
        pool->used++;
    } else {
        // Re-allocate the entire pool if it's full
        int newSize = pool->size * 2;
        pool->blocks = (void*)realloc(pool->blocks, newSize * sizeof(void*));
        pool->size = newSize;
        ptr = pool->blocks[pool->used];
        pool->used++;
    }
    pthread_mutex_unlock(&pool->lock);
    return ptr;
}

// Free memory from the custom pool
void freeFromPool(MemoryPool* pool, void* ptr) {
    pthread_mutex_lock(&pool->lock);
