public:
    CUSTOM_ALLOCATOR(size_t pool_size) : pool_(new char[pool_size]), size_(pool_size), free_list_(new CUSTOM_EVENT_RECORD*) {
        for (size_t i = 0; i < pool_size / sizeof(CUSTOM_EVENT_RECORD); ++i)
