<?php

class AuthController {
    private $config;
    private $logger;

    public function __construct($config, $logger) {
        $this->config = $config;
        $this->logger = $logger;
    }

    public function authenticate() {
        // Check for valid OAuth token in the request
        if (!isset($_COOKIE['oauth_token'])) {
            return redirect('login');
        }

        // Validate the OAuth token against external identity provider
        $token = $_COOKIE['oauth_token'];
        $provider = get_oauth_provider($token);
        if (!$provider) {
            // Token is invalid or expired, log out the user
            logout();
            return redirect('login');
        }

        // Authenticate the user and create a session
        $user_data = authenticate_user($provider->getUserInfo($token));
        start_session($user_data);

        return redirect('/logged_in_page');
    }

    public function login() {
        // Present the OAuth authorization link to the user
        $url = $config['oauth_provider_url'] . '?client_id=' . $config['client_id'] . '&redirect_uri=' . urlencode($config['redirect_uri']);
        header('Location: ' . $url);
        exit;
    }

    public function logout() {
        // Destroy the session and remove the OAuth token cookie
        destroy_session();
        setcookie('oauth_token', '', time() - 1, '/');
    }
}

