    void addDevice(DeviceConnectionStatus device) {
        std::lock_guard<std::mutex> lock(mutex);
        list.push_back(device);
    }

    DeviceConnectionStatus getDevice(int deviceID) {
        std::lock_guard<std::mutex> lock(mutex);
        for (auto& device : list) {
            if (device.deviceID == deviceID) {
                return device;
            }
        }
        return DeviceConnectionStatus(); // Return default constructor object
