        public DataProcessor(ILogger logger)
        {
            _logger = logger;
        }

        public void Start()
        {
            // start processing data from all sources
            foreach (var apiSource in _apiSources.Values)
            {
                Task.Run(() => ProcessRecordsFromApi(apiSource));
            }
        }

        private async Task ProcessRecordsFromApi(IApiSource apiSource)
