            while (true)
            {
                try
                {
                    var records = await apiSource.FetchRecords();
                    foreach (var record in records)
                    {
                        _records.Add(record);
                        // apply adaptive data retention policy
                        ApplyDataRetentionPolicy();
                    }
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, "Error processing records from API");
                }
            }
        }

