DynamicArray* create_dynamic_array(int initial_capacity) {
    DynamicArray* arr = malloc(sizeof(DynamicArray));
    arr->records = malloc(initial_capacity * sizeof(NetworkEventRecord*));
    arr->size = 0;
    arr->capacity = initial_capacity;
    return arr;
}

