Command commands[MAX_COMMANDS];
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to execute a command
void* execute_command(void* arg) {
    // Get the command from the argument
    Command* cmd = (Command*)arg;

    // Execute the command and log any errors
    system(cmd->command);

    // Free memory and update statistics
    free(cmd->command);
    pthread_mutex_lock(&mutex);
    num_commands--;
    if (max_memory_used > 0) {
        max_memory_used -= strlen(cmd->command) + 1;
    }
    pthread_mutex_unlock(&mutex);

    return NULL;
}

// Function to start a new command
void start_command(int id, char* command) {
    // Check for memory exhaustion
    if (num_commands >= MAX_COMMANDS || max_memory_used + strlen(command) + 1 > MAX_MEMORY) {
        // If the daemon is too busy, queue the command instead of executing it immediately
        int i;
        for (i = 0; i < num_commands; i++) {
            if (commands[i].id == -1) {
                break;
            }
        }
        if (i >= num_commands) {
            // If there is no available space, wait until one becomes available
            pthread_mutex_lock(&mutex);
            while (num_commands >= MAX_COMMANDS || max_memory_used + strlen(command) + 1 > MAX_MEMORY) {
                usleep(1000); // Sleep for a short time before re-checking
                pthread_mutex_unlock(&mutex);
            }
        }
        // Insert the command at the first available spot
        if (i < num_commands) {
            commands[i].id = id;
            commands[i].command = command;
            pthread_create(&commands[i].thread, NULL, execute_command, &commands[i]);
        } else {
            // If no space is available, this will be handled by the queuing mechanism
            commands[num_commands].id = id;
            commands[num_commands].command = command;
            pthread_create(&commands[num_commands].thread, NULL, execute_command, &commands[num_commands]);
            num_commands++;
        }
    } else {
        // If there is space available, start a new thread for the command
        commands[num_commands].id = id;
        commands[num_commands].command = command;
        pthread_create(&commands[num_commands].thread, NULL, execute_command, &commands[num_commands]);
        num_commands++;
    }
}

// Function to stop a running command
void stop_command(int id) {
    int i;
    for (i = 0; i < num_commands; i++) {
        if (commands[i].id == id) {
            break;
        }
    }
    if (i < num_commands) {
        pthread_kill(commands[i].thread, SIGKILL);
        free(commands[i].command);
        commands[i].id = -1;
        num_commands--;
    }
}

// Function to get the status of a command
int get_command_status(int id) {
    int i;
    for (i = 0; i < num_commands; i++) {
        if (commands[i].id == id) {
            break;
        }
    }
    if (i < num_commands) {
        return pthread_equal(pthread_self(), commands[i].thread);
    } else {
        return -1;
    }
}

int main() {
    // Initialize the daemon
    num_commands = 0;
    max_memory_used = 0;

    // Start a new thread to handle command execution
    pthread_t thread;
    pthread_create(&thread, NULL, execute_command, NULL);

    // Main loop for accepting user commands
    while (1) {
        char command[1024];
        printf("Enter a command: ");
        fgets(command, 1024, stdin);

        int id = 0;
        char* arg = NULL;
        char* cmd = strtok(command, " ");
        if (cmd != NULL) {
            id = atoi(cmd);
            arg = strtok(NULL, " ");
        }

        // Start a new command
        start_command(id, arg);
    }

    return 0;
}

