// Function to print usage information
void printUsage(std::ostream& os) {
    os << "Usage: log_parser [options] input_file\n";
    os << "Options:\n";
    os << "-o output_file  Write output to file instead of stdout.\n";
    os << "--manpage      Show this help message and exit.\n";
}

// Function to parse command line arguments
int parseArgs(int argc, char* argv[], std::string& input_file, bool& show_help) {
    for (int i = 1; i < argc; ++i) {
        if (std::string(argv[i]) == "--manpage") {
            show_help = true;
        } else if (std::string(argv[i]) == "-o" || std::string(argv[i]).find("-o") == 0) {
            if (i + 1 < argc) {
                input_file = argv[i + 1];
                i++;
            }
        }
    }

    return 0;
}

// Function to print the number of lines in a file
void printLines(const std::string& filename, bool show_count) {
    std::ifstream file(filename);
    if (!file.is_open()) {
        std::cerr << "Error opening file: " << filename << "\n";
        return;
    }

    int line_count = 0;
    std::string line;

    while (std::getline(file, line)) {
        line_count++;
    }

    if (show_count) {
        std::cout << line_count << " lines in file: " << filename << "\n";
    }
}

int main(int argc, char* argv[]) {
    std::string input_file;
    bool show_help = false;

    parseArgs(argc, argv, input_file, show_help);

    if (show_help) {
        printUsage(std::cout);
        return 0;
    }

    if (!input_file.empty()) {
        printLines(input_file, true);
    } else {
        std::cerr << "Error: No input file provided.\n";
        printUsage(std::cerr);
    }

    return 0;
}
