    char* result = NULL;

    // Check for edge cases
    if (!input || !prefix) {
        return NULL;
    }

    // Calculate the total size required for the modified string
    int totalSize = strlen(prefix) + strlen(input) + 1; // Add space for null-terminator

    // Allocate memory for the result string
    result = (char*)malloc(totalSize * sizeof(char));
    if (!result) {
        return NULL;
    }

    // Copy the prefix and input into the result string
    memcpy(result, prefix, strlen(prefix));
