typedef struct {
    time_t timestamp;
    char eventType[32];
    void* metadata;
} NetworkEventRecord;

// Dynamic array structure
typedef struct {
    NetworkEventRecord** records;
    size_t capacity;
    size_t count;
} DynamicArray;

DynamicArray* createDynamicArray(size_t initialCapacity) {
    DynamicArray* arr = (DynamicArray*)malloc(sizeof(DynamicArray));
    arr->records = (NetworkEventRecord**)malloc(initialCapacity * sizeof(NetworkEventRecord*));
    arr->capacity = initialCapacity;
    arr->count = 0;
    return arr;
}

void addRecordToDynamicArray(DynamicArray* arr, NetworkEventRecord* record) {
    if (arr->count == arr->capacity) {
        arr->capacity *= 2;
        arr->records = (NetworkEventRecord**)realloc(arr->records, arr->capacity * sizeof(NetworkEventRecord*));
    }
    arr->records[arr->count] = record;
    arr->count++;
}

void freeDynamicArray(DynamicArray* arr) {
    for (size_t i = 0; i < arr->count; i++) {
        free(arr->records[i]->metadata);
        free(arr->records[i]);
    }
    free(arr->records);
    free(arr);
}

// Caching strategy
typedef struct {
    time_t timestamp;
    void* data;
} CacheEntry;

CacheEntry** createCache(int initialCapacity) {
    return (CacheEntry**)malloc(initialCapacity * sizeof(CacheEntry*));
}

void addCacheEntry(CacheEntry** cache, int capacity, time_t timestamp, void* data) {
    for (int i = 0; i < capacity; i++) {
        if (!cache[i]->timestamp || cache[i]->timestamp <= timestamp) {
            cache[i]->timestamp = timestamp;
            cache[i]->data = data;
            return;
        }
    }
}

void freeCache(CacheEntry** cache, int capacity) {
    for (int i = 0; i < capacity; i++) {
        if (cache[i]->data)
            free(cache[i]->data);
        free(cache[i]);
    }
    free(cache);
}

