                free(events->records[i]->metadata);
                free(events->records[i]);
                events->count--;
                memmove(&events->records[i], &events->records[i + 1], (events->count - i) * sizeof(NetworkEventRecord*));
            }
        }

        // Handle periodic cleanup and cache invalidation
