public class DistributedLoggingFramework {
    // Define a flexible filtering mechanism using a query expression language (QUEL)
    public static class FilteringMechanism {
        private List<FilterExpression> filterExpressions;

        public FilteringMechanism() {
            this.filterExpressions = new ArrayList<>();
        }

        public void addFilterExpression(FilterExpression filterExpression) {
            this.filterExpressions.add(filterExpression);
        }

        public boolean applyFilters(LogEntry logEntry) {
            for (FilterExpression filterExpression : filterExpressions) {
                if (!filterExpression.apply(logEntry)) {
                    return false;
                }
            }
            return true;
        }
    }

    // Implement a multi-tiered compression strategy with dynamic adaptation
    public static class CompressionStrategy {
        private List<CompressionAlgorithm> algorithms;

        public CompressionStrategy() {
            this.algorithms = new ArrayList<>();
        }

        public void addAlgorithm(CompressionAlgorithm algorithm) {
            this.algorithms.add(algorithm);
        }

        public byte[] compress(byte[] data) {
            // Dynamic adaptation based on system metrics (CPU, memory, I/O)
            for (CompressionAlgorithm algorithm : algorithms) {
                if (algorithm.isApplicable(data)) {
                    return algorithm.compress(data);
                }
            }
            return null;
        }
    }

