    private Map<String, List<LogEntry>> cache;

    public CachingLayer() {
        cache = new HashMap<>();
    }

    public void put(String key, LogEntry logEntry) {
        // Store log entries in the cache
        cache.computeIfAbsent(key, k -> new ArrayList<>()).add(logEntry);
    }

    public List<LogEntry> get(String key) {
