    // Get an event by timestamp
    NetworkEventRecord* getEvent(int64_t timestamp) {
        std::unique_lock<std::mutex> lock(mutex_);
        auto it = cache_->find(timestamp);
        if (it != cache_->end()) {
            return &it->second;
        }
        return nullptr;
    }

    // Fetch events from the API
    void fetchEvents() {
        CURL *curl;
        CURLcode res;
        std::string readBuffer;

        curl_global_init(CURL_GLOBAL_DEFAULT);
        curl = curl_easy_init();
        if (curl) {
            std::vector<NetworkEventRecord> eventsToFetch;
            for (const auto& event : events_) {
                eventsToFetch.push_back(event);
            }
            Json::Value params;
            params["events"] = Json::Value::toString(eventsToFetch);
            curl_easy_setopt(curl, CURLOPT_URL, "https://api.example.com/events");
            curl_easy_setopt(curl, CURLOPT_POSTFIELDS, params.toString().c_str());
            res = curl_easy_perform(curl);
            if (res != CURLE_OK) {
                std::cerr << "cURL error: " << curl_easy_strerror(res) << std::endl;
            }
            curl_easy_cleanup(curl);
        }
        curl_global_cleanup();
    }

    // Run the cleanup operation
    void cleanUp() {
        std::lock_guard<std::mutex> lock(mutex_);
        while (!events_.empty()) {
            auto event = events_.front();
            events_.pop_front();
            cache_->erase(event.timestamp);
            if (retentionPolicy_.expired()) {
                break;
            }
        }
    }

private:
    std::vector<NetworkEventRecord> events_;
    std::unique_ptr<std::unordered_map<int64_t, NetworkEventRecord>> cache_;
    std::chrono::seconds retentionPolicy_;
    std::chrono::minutes cleanupInterval_;
    std::mutex mutex_;
};

