// Custom LRU cache class with configurable cache hit rate and memory usage trade-offs
class LRUCache {
public:
    LRUCache(int capacity, double cacheHitRate) : capacity_(capacity), cacheHitRate_(cacheHitRate), cacheSize_(0) {}

    // Insert or update a key-value pair in the cache
    void put(const std::string& key, const std::string& value) {
        if (cache_.count(key)) {
            // Update existing entry with new value
            auto it = cache_.find(key);
            it->second = value;
            --it->second.size;  // Decrement size for existing entry
            ++hitCount_;
            return;
        }

        if (cacheSize_ >= capacity_) {
            // Evict the least recently used item
            const auto& oldestEntry = cache_.begin();
            cache_.erase(oldestEntry);
            --cacheSize_;
        }

        // Insert new key-value pair
        cache_[key] = {value, 1};
        ++cacheSize_;

        if (rand() % int(pow(10, 9)) < cacheHitRate_ * int(pow(10, 8))) {
            // Mark as recently used
            it->second.size = 1;
        }
    }

    // Retrieve a value from the cache
    std::string get(const std::string& key) {
        if (cache_.count(key)) {
            const auto& entry = cache_[key];
            ++entry.second.size;
            return entry.first;
        }

        return "";
    }

private:
    struct CacheEntry {
        std::string value;
        int size;
    };

    std::unordered_map<std::string, CacheEntry> cache_;
    int capacity_, cacheSize_;
    double cacheHitRate_;
    int hitCount_ = 0;
};

