// Python Code
import hashlib
import os
from flask import Flask, request, jsonify
from flask_restful import Api, Resource
from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes

app = Flask(__name__)
api = Api(app)

class FileHash(Resource):
    def get(self, file_path):
        md5_hash = hashlib.md5()
        with open(file_path, 'rb') as f:
            for chunk in iter(lambda: f.read(4096), b""):
                md5_hash.update(chunk)
        return {'file_hash': md5_hash.hexdigest()}

class FileDecrypt(Resource):
    def post(self):
        file_data = request.get_json()['file']
        aes_key = bytes.fromhex(request.get_json()['aes_key'])
        iv = os.urandom(16)
        cipher = Cipher(algorithms.AES(aes_key), modes.CBC(iv))
        decryptor = cipher.decryptor()
        decrypted_file = decryptor.update(file_data) + decryptor.finalize()
        return {'decrypted_file': decrypted_file.decode('utf-8')}

api.add_resource(FileHash, '/file_hash')
api.add_resource(FileDecrypt, '/file_decrypt')

// C# Code
using System;
using System.IO;
using System.Security.Cryptography;
using Microsoft.AspNetCore.Mvc;

[ApiController]
public class FileController : ControllerBase
{
    [HttpGet("file_hash/{filePath}")]
    public IActionResult GetFileHash(string filePath)
    {
        using (var md5 = MD5.Create())
        {
            byte[] fileBytes = File.ReadAllBytes(filePath);
            var hashValue = md5.ComputeHash(fileBytes);
            return Ok($"MD5 Hash: {BitConverter.ToString(hashValue)}");
        }
    }

    [HttpPost("file_decrypt")]
    public IActionResult DecryptFile([FromBody] DecryptFileRequest request)
    {
        using (var aes = Aes.Create())
        {
            aes.Key = Convert.FromBase64String(request.AesKey);
            aes.IV = new byte[] { 0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x10, 0x11, 0x12, 0x13, 0x14, 0x15 };
            using (var ms = new MemoryStream(request.File))
            {
                ms.Position = 0;
                using (var cs = aes.CreateDecryptor())
                {
                    using (var sw = new StreamWriter(new MemoryStream()))
                    {
                        using (var sr = new StreamReader(ms))
                        {
                            string fileData = sr.ReadToEnd();
                            byte[] decryptedFileBytes = Convert.FromBase64String(fileData);
                            string decryptedFile = Encoding.UTF8.GetString(decryptedFileBytes);
                            return Ok($"Decrypted File: {decryptedFile}");
                        }
                    }
                }
            }
        }
    }
}

public class DecryptFileRequest
{
    public string AesKey { get; set; }
    public byte[] File { get; set; }
}
