public class NotificationDAO {

    public void save(Notification notification) {
        try (Connection conn = DriverManager.getConnection("jdbc:mysql://localhost:3306/notifications", "root", "password")) {
            String query = "INSERT INTO notifications (id, type, content) VALUES (?, ?, ?)";
            PreparedStatement stmt = conn.prepareStatement(query);
            stmt.setInt(1, notification.getId());
            stmt.setString(2, notification.getType().toString());
            stmt.setString(3, notification.getContent());
            stmt.executeUpdate();
        } catch (SQLException e) {
            // Handle database error
        }
    }

    public List<Notification> getNotifications() {
        try (Connection conn = DriverManager.getConnection("jdbc:mysql://localhost:3306/notifications", "root", "password")) {
            String query = "SELECT * FROM notifications";
            PreparedStatement stmt = conn.prepareStatement(query);
            ResultSet result = stmt.executeQuery();
            List<Notification> notifications = new ArrayList<>();
            while (result.next()) {
                Notification notification = new Notification();
                notification.setId(result.getInt("id"));
                notification.setType(NotificationType.valueOf(result.getString("type")));
                notification.setContent(result.getString("content"));
                notifications.add(notification);
            }
            return notifications;
        } catch (SQLException e) {
            // Handle database error
        }
    }
}

