    // Asynchronous request function
    void makeRequest(string url, string method, function<void(json::value)> callback) {
        // Create a new thread for handling requests
        thread t([this, url, method, callback]() {
            // Make the HTTP request using libcurl
            CURL *curl;
            CURLcode res;

            curl_global_init(CURL_GLOBAL_DEFAULT);
            curl = curl_easy_init();
            if(curl) {
                string fullUrl = host_ + ":" + to_string(port_) + url;
                curl_easy_setopt(curl, CURLOPT_URL, fullUrl.c_str());
                curl_easy_setopt(curl, CURLOPT_CUSTOMREQUEST, method.c_str());

                res = curl_easy_perform(curl);

                // Check for errors
                if(res != CURLE_OK) {
                    std::cerr << "cURL error: " << curl_easy_strerror(res) << std::endl;
                } else {
                    json::value result;

                    // Parse the response as JSON
                    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &result);
                    res = curl_easy_perform(curl);

                    // Call the callback function with the parsed JSON data
                    callback(result);
                }

                curl_easy_cleanup(curl);
            }
        });
    }

