using System;
using System.Data;
using System.Data.SqlClient;
using System.Threading;
using System.Threading.Tasks;

namespace DataAccessLayer
{
    public class DataAccess
    {
        private readonly string _connectionString;
        private readonly int _retryCount;
        private readonly TimeSpan _retryInterval;

        public DataAccess(string connectionString, int retryCount = 3, TimeSpan retryInterval = TimeSpan.FromMinutes(1))
        {
            _connectionString = connectionString;
            _retryCount = retryCount;
            _retryInterval = retryInterval;
        }

        public async Task<T> ExecuteQueryAsync<T>(string query, CancellationToken cancellationToken = default)
        {
            using var connection = new SqlConnection(_connectionString);
            connection.Open();

            using var command = new SqlCommand(query, connection);

            try
            {
                using var reader = await command.ExecuteReaderAsync(cancellationToken).ConfigureAwait(false);
                return (T)(object)reader;
            }
            catch (SqlException ex)
            {
                if (ex.Number == 3951) // Service temporarily unavailable
                {
                    await Task.Delay(_retryInterval, cancellationToken);
                    return await ExecuteQueryAsync<T>(query, cancellationToken);
                }
                else
                {
                    throw;
                }
            }
        }

        public async Task<int> ExecuteNonQueryAsync(string query, CancellationToken cancellationToken = default)
        {
            using var connection = new SqlConnection(_connectionString);
            connection.Open();

            using var command = new SqlCommand(query, connection);

            try
            {
                return await command.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);
            }
            catch (SqlException ex)
            {
                if (ex.Number == 3951) // Service temporarily unavailable
                {
                    await Task.Delay(_retryInterval, cancellationToken);
                    return await ExecuteNonQueryAsync(query, cancellationToken);
                }
                else
                {
                    throw;
                }
            }
        }

        public async Task<T> GetCacheValueAsync<T>(string cacheKey)
        {
            using var cache = new MemoryCache();
            if (cache.Contains(cacheKey))
            {
                return (T)cache.Get(cacheKey);
            }
            else
            {
                return await ExecuteQueryAsync<T>("SELECT * FROM CachedData WHERE Key = @key", new SqlParameter("@key", cacheKey));
            }
        }

        public async Task SetCacheValueAsync(string cacheKey, object value)
        {
            using var cache = new MemoryCache();
            await cache.SetAsync(cacheKey, value);
        }
    }
}
