import java.util.HashMap;
import java.util.Map;

public class CacheFramework {
    private Map<String, Object> cacheMap = new HashMap<>();
    private Map<String, Long> expirationTimes = new HashMap<>();

    public void put(String key, Object value, long ttl) {
        cacheMap.put(key, value);
        expirationTimes.put(key, System.currentTimeMillis() + ttl);
    }

    public Object get(String key) {
        Object value = cacheMap.get(key);
        if (value != null && isExpired(key)) {
            remove(key);
            return null;
        }
        return value;
    }

    private boolean isExpired(String key) {
        long expirationTime = expirationTimes.get(key);
        return System.currentTimeMillis() > expirationTime;
    }

    public void remove(String key) {
        cacheMap.remove(key);
        expirationTimes.remove(key);
    }

    // For dynamic data freshness
    public void invalidate(String key) {
        remove(key);
    }

    // For scalability and reliability
    public Object getWithRetries(String key, int maxAttempts) {
        Object value = null;
        for (int attempt = 0; attempt < maxAttempts; attempt++) {
            try {
                value = cacheMap.get(key);
                if (value == null || isExpired(key)) {
                    break;
                }
                return value;
            } catch (Exception e) {
                if (attempt < maxAttempts - 1) {
                    // Wait and retry
                    try {
                        Thread.sleep(1000); // adjust timeout as needed
                    } catch (InterruptedException ie) {
                    }
                } else {
                    throw new RuntimeException("Failed to retrieve value", e);
                }
            }
        }
        return null;
    }

    public void encryptAndDecrypt(String plaintext, String ciphertext) {
        // Implement encryption and decryption logic here
    }

    public void auditLog(String operation, Object data) {
        // Implement logging mechanism here
    }
}
