import java.util.*;

class NicConfig {
    String ip;
    int subnetMask;
    String macAddress;
    int vlanTag;

    public NicConfig(String ip, int subnetMask, String macAddress, int vlanTag) {
        this.ip = ip;
        this.subnetMask = subnetMask;
        this.macAddress = macAddress;
        this.vlanTag = vlanTag;
    }
}

class UnionFind {
    Map<NicConfig, Integer> parentMap;

    public UnionFind() {
        this.parentMap = new HashMap<>();
    }

    public void union(NicConfig a, NicConfig b) {
        int rootA = find(a);
        int rootB = find(b);

        if (rootA != rootB) {
            parentMap.put(rootA, rootB);
        }
    }

    private int find(NicConfig nic) {
        return parentMap.computeIfAbsent(nic, k -> k.vlanTag);
    }

    public long countDisjointPairs(List<NicConfig> nics) {
        long disjointCount = 0;
        Map<Integer, Integer> componentSizeMap = new HashMap<>();

        for (NicConfig nic : nics) {
            int root = find(nic);
            componentSizeMap.put(root, componentSizeMap.getOrDefault(root, 0) + 1);
        }

        for (Map.Entry<Integer, Integer> entry : componentSizeMap.entrySet()) {
            disjointCount += entry.getValue() * (entry.getValue() - 1) / 2;
        }
        return disjointCount;
    }
}

class NicManager {
    UnionFind unionFind;

    public NicManager() {
        this.unionFind = new UnionFind();
    }

    public Map<NicConfig, Long> checkDisjointness(List<NicConfig> nics) {
        Map<NicConfig, Long> results = new HashMap<>();

        for (NicConfig nic : nics) {
            long start = System.nanoTime();
            unionFind.union(nic, new NicConfig("", 0, "", 0));
            long end = System.nanoTime();

            results.put(nic, end - start);
        }
        return results;
    }
}

class CloudNicManager {
