        for (NicConfig nic : nics) {
            long start = System.nanoTime();
            int disjointCount = nicManager.nicManager.countDisjointPairs(nics);
            long end = System.nanoTime();

            results.put(nic, end - start);
        }
        return results;
    }

    public void handleCloudServiceError() {
        // Implement error handling strategies here
    }
}
