            for (int i = 0; i < MAX_CONCURRENT_CONNECTIONS; i++) {
                executor.submit(() -> {
                    try {
                        // Process and send data through the pipeline
                        messagingSystem.sendDataToPipeline(stages);
                    } catch (Exception e) {
                        // Handle errors and retries
                        handleException(e, RETRY_ATTEMPTS);
                    }
