    public function createSession(array $sessionData): string {
        // Generate a unique session ID
        $sessionId = uniqid();

        // Store the session data in Redis
        $this->redis->hSet($sessionId, 'data', json_encode($sessionData));

        return $sessionId;
    }

    public function getSession(string $sessionId): array {
        // Check if the session exists and is valid
        if (!$this->redis->exists($sessionId)) {
            throw new Exception("Session not found or invalid");
        }

        // Get the session data from Redis
        $sessionData = json_decode($this->redis->hGet($sessionId, 'data'), true);

        return $sessionData;
    }

    public function updateSession(string $sessionId, array $updatedData): void {
        // Store the updated session data in Redis with optimistic concurrency control
        if ($this->redis->hIncrTryLock($sessionId, 1, 'data', json_encode($updatedData))) {
            // Session updated successfully
        } else {
            throw new Exception("Session update failed due to concurrent modification");
        }
    }

    public function invalidateSession(string $sessionId): void {
        // Delete the session data from Redis
        $this->redis->delete($sessionId);
