```python
import csv
import json
import xml.etree.ElementTree as ET
import os
import numpy as np
from datetime import datetime, timedelta

class DataProcessor:
    def __init__(self):
        self.input_files = []
        self.output_file = None
        self.transform_rules = []

    def set_input_files(self, files):
        self.input_files = files

    def set_output_file(self, file):
        self.output_file = file

    def add_transform_rule(self, rule):
        self.transform_rules.append(rule)

    def process_data(self):
        for file in self.input_files:
            if file.endswith('.csv'):
                with open(file, 'r') as f:
                    reader = csv.reader(f)
                    for row in reader:
                        # Apply transformation rules
                        processed_row = []
                        for value in row:
                            for rule in self.transform_rules:
                                if rule.apply(value):
                                    processed_row.append(rule.transform(value))
                            if not processed_row:
                                processed_row.append(value)
                        if processed_row:
                            yield tuple(processed_row)

            elif file.endswith('.json'):
                with open(file, 'r') as f:
                    data = json.load(f)
                    for item in data:
                        # Apply transformation rules
                        processed_item = {}
                        for key, value in item.items():
                            for rule in self.transform_rules:
                                if rule.apply(value):
                                    processed_item[key] = rule.transform(value)
                            if not processed_item:
                                processed_item[key] = value
                        yield process_item

            elif file.endswith('.xml'):
                tree = ET.parse(file)
                root = tree.getroot()
                for child in root:
                    # Apply transformation rules
                    processed_child = {}
                    for key, value in child.items():
                        for rule in self.transform_rules:
                            if rule.apply(value):
                                processed_child[key] = rule.transform(value)
                        if not processed_child:
                            processed_child[key] = value
                    yield processed_child

    def write_output(self, data):
        with open(self.output_file, 'w') as f:
            writer = csv.writer(f)
            for row in data:
                writer.writerow(row)

class TransformationRule:
    def __init__(self, condition, transformation):
        self.condition = condition
        self.transformation = transformation

    def apply(self, value):
        if self.condition(value):
            return True
        return False

    def transform(self, value):
        return self.transformation(value)

if __name__ == '__main__':
    processor = DataProcessor()
    processor.set_input_files(['input.csv', 'input.json', 'input.xml'])
    processor.set_output_file('output.csv')
    rule1 = TransformationRule(lambda x: isinstance(x, int), lambda x: str(int(x) * 2))
    rule2 = TransformationRule(lambda x: not isinstance(x, dict), lambda x: 'unknown')
    processor.add_transform_rule(rule1)
    processor.add_transform_rule(rule2)

    with open('output.csv', 'w') as f:
        writer = csv.writer(f)
        for row in processor.process_data():
            writer.writerow(row)
