#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <queue>
#include <thread>
#include <mutex>

// Define a struct for log entry
struct LogEntry {
    std::string timestamp;
    std::string message;
};

// Define a class for log processor
class LogProcessor {
public:
    // Constructor
    LogProcessor(const std::string& inputFilePath, const std::string& outputFilePath);

    // Process logs
    void processLogs();

private:
    // Input and output file paths
    std::string inputFilePath;
    std::string outputFilePath;

    // Queue for processing log entries
    std::queue<LogEntry> logQueue;

    // Mutex for thread safety
    std::mutex mutex;
};

// Constructor implementation
LogProcessor::LogProcessor(const std::string& inputFilePath, const std::string& outputFilePath)
    : inputFilePath(inputFilePath), outputFilePath(outputFilePath) {
    // Initialize the log queue and mutex
}

// Process logs implementation
void LogProcessor::processLogs() {
    // Open the input file for reading
    std::ifstream inputFile(inputFilePath);

    // Read each log entry from the file
    while (inputFile) {
        // Parse the log entry
        LogEntry logEntry;
        inputFile >> logEntry.timestamp >> logEntry.message;

        // Add the log entry to the queue
        {
            std::unique_lock<std::mutex> lock(mutex);
            logQueue.push(logEntry);
        }
    }

    // Open the output file for writing
    std::ofstream outputFile(outputFilePath);

    // Process each log entry in the queue
    while (!logQueue.empty()) {
        // Dequeue a log entry
        LogEntry logEntry = logQueue.front();
        logQueue.pop();

        // Write the log entry to the output file
        outputFile << logEntry.timestamp << " " << logEntry.message << "\n";
    }
}

int main() {
    LogProcessor logProcessor("input.log", "output.log");
    logProcessor.processLogs();
    return 0;
}
