```java
package com.example.eventbroker;

import java.util.concurrent.BlockingQueue;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;
import java.util.logging.Level;
import java.util.logging.Logger;
import java.util.Map;
import java.util.HashMap;
import java.util.Set;
import java.util.HashSet;

public class EventBroker {

    private static final Logger LOG = Logger.getLogger(EventBroker.class.getName());

    // Configuration
    private int numThreads;
    private int maxEventsPerSecond;
    private Map<String, Consumer<Event>> eventHandlers;
    private Map<String, Set<String>> routingRules;

    // Event processing pipeline
    private BlockingQueue<Event> eventQueue;
    private ThreadPoolExecutor executor;

    public EventBroker(YamlConfig config) {
        this.numThreads = config.getNumThreads();
        this.maxEventsPerSecond = config.getMaxEventsPerSecond();
        this.eventHandlers = new HashMap<>();
        this.routingRules = new HashMap<>();

        // Initialize event queue and thread pool
        eventQueue = new LinkedBlockingQueue<>();
        executor = new ThreadPoolExecutor(numThreads, numThreads, 0, TimeUnit.MILLISECONDS);
    }

    public void start() {
        // Start event processing pipeline
        Thread producerThread = new Thread(() -> produceEvents());
        producerThread.start();

        // Start consumer threads
        for (int i = 0; i < numThreads; i++) {
            Thread consumerThread = new Thread(() -> consumeEvents());
            consumerThread.start();
        }
    }

    public void stop() {
        // Stop event processing pipeline
        executor.shutdown();

        // Wait for all threads to finish
        producerThread.interrupt();
        consumerThreads.forEach(Thread::interrupt);
        while (!executor.isTerminated()) {
            try {
                TimeUnit.MILLISECONDS.sleep(100);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }

    private void produceEvents() {
        // Simulate event production
        for (int i = 0; i < maxEventsPerSecond * 60 * 1000 / 50_000; i++) {
            Event event = createEvent();
            eventQueue.add(event);
        }
    }

    private void consumeEvents() {
        while (true) {
            try {
                Event event = eventQueue.take();
                handleEvent(event);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                return;
            } catch (Exception e) {
                LOG.log(Level.SEVERE, "Error handling event: " + e.getMessage());
            }
        }
    }

    private void handleEvent(Event event) {
        // Determine target consumers based on routing rules
        Set<String> consumerSet = routingRules.get(event.getType());

        // Route events to target consumers
        for (String consumer : consumerSet) {
            Consumer<Event> handler = eventHandlers.get(consumer);
            if (handler != null) {
                handler.accept(event);
            }
        }
    }

    private Event createEvent() {
        // Simulate creating an event with random data
        return new Event("INFO", "Hello, World!", System.currentTimeMillis());
    }
}

class YamlConfig {
    private int numThreads;
    private int maxEventsPerSecond;

    public int getNumThreads() {
        return numThreads;
    }

    public int getMaxEventsPerSecond() {
        return maxEventsPerSecond;
    }
}
