    void RetryNicConfigUpdate(const NicConfig& new_config, const std::string& node_id, int max_retries) {
        for (int i = 0; i < max_retries; i++) {
            try {
                UpdateNicConfig(new_config, node_id);
                return;
            } catch (const std::runtime_error& e) {
                // Log error and wait before retrying
                if (i < max_retries - 1) {
                    LOG_WARNING("Failed to update NIC config: {}", e.what());
                    Sleep(RETRY_INTERVAL);
                } else {
                    LOG_ERROR("Max retries exceeded for updating NIC config: {}", e.what());
                }
            }
        }
    }

    // Cache-efficient interface for cloud network management framework
    void UpdateNicConfigForCloudFramework(const NicConfig& new_config, const std::string& node_id) {
