    public static void main(String[] args) throws Exception {
        // Create Camel Context
        CamelContext context = new DefaultCamelContext();

        // Configure AMQP, MQTT, and Kafka components
        ActiveMQComponent amqpComponent = new ActiveMQComponent();
        amqpComponent.setConnectionFactory(new ActiveMQConnectionFactory("vm://localhost"));
        context.addComponent("activemq", amqpComponent);

        NioSocketAcceptor nioAcceptor = new NioSocketAcceptor();
        nioAcceptor.bind("tcp://localhost:5672");
        context.addService(nioAcceptor);

        KafkaProducer<String, String> kafkaProducer = new KafkaProducer<>("localhost:9092", "my-topic");
        context.addService(kafkaProducer);

        // Define routes for processing messages
        RouteBuilder routeBuilder = new RouteBuilder() {
            @Override
            public void configure() throws Exception {
                from("activemq:queue:amqp-queue")
                    .to("kafka:topic:kafka-topic");

                from("kafka:topic:kafka-topic")
                    .process(new MessageProcessor())
                    .to("activemq:queue:mqtt-queue");

                from("activemq:queue:mqtt-queue")
                    .to("tcp://localhost:1883");
            }
        };
