  ws.on('message', (message) => {
    const { type, content } = JSON.parse(message);
    switch (type) {
      case 'UPDATE':
        updateDocument(ws, content);
        break;
      case 'JOIN':
        joinDocument(ws, content);
        break;
      default:
        console.log(`Received unknown message: ${message}`);
    }
  });

  ws.on('close', () => {
    console.log('Connection closed');
  });
});

function updateDocument(ws, content) {
  const { userId, text } = content;
  // synchronize document state
  if (Object.keys(documentState).includes(userId)) {
    documentState[userId].text += text;
  } else {
    documentState[userId] = { text };
  }
  broadcastUpdate();
}

function joinDocument(ws, content) {
  const { userId } = content;
  // handle user joining
  ws.send(JSON.stringify({ type: 'JOINED', userId }));
}

function broadcastUpdate() {
  wss.clients.forEach((client) => {
    client.send(
      JSON.stringify({
        type: 'UPDATE',
        documentState,
      })
    );
  });
}

